SELECT 'moj-all-verified-judgments-review-002-chunk-016' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d0bf0167-1d8d-5e3c-aee2-019fac6b7a4d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد ذهب أخذه الزوج -انكار الدعوى -عدم وجود البينة من املدعية -البينة على املدعي واليمن على من أنكر -رفض املدعية مين املدعى عليه -احلكم برد دعوى املدعية.","document_number":"33468935","case_number":"32421469","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/29","year":"1434","subject":"مطالبة برد ذهب أخذه الزوج -انكار الدعوى -عدم وجود البينة من املدعية -البينة على املدعي واليمن على من أنكر -رفض املدعية مين املدعى عليه -احلكم برد دعوى املدعية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/11/29 :‬هـ‬\n                 ‫ُ‬                  ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪33468935 :‬‬\n                     ‫َر ْق ُم الدعوى‪32421469 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3434910‬تاريخه‪1434/2/11 :‬هـ‬\n\n\n  ‫مطالبــة بــرد ذهــب أخــذه الــزوج ‪ -‬انــكار الدعــوى ‪ -‬عــدم وجــود البينــة‬\n  ‫مــن املدعيــة ‪ -‬البينــة علــى املدعــي واليمــن علــى مــن أنكــر ‪ -‬رفــض‬\n             ‫املدعيــة ميــن املدعــى عليــه ‪ -‬احلكــم بــرد دعــوى املدعيــة‪.‬‬\n\n\n\n\n  ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( البينــة علــى املدعــي واليمــن علــى‬\n                                                                 ‫مــن أنكــر ) ‪.‬‬\n                          ‫‪ -2‬املادة ( ‪ ) 166‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n  ‫ادعــت املدعيــة بأنهــا كانــت زوجــة للمدعى عليه وقــام بطالقها مبوجب‬\n  ‫صــك الطــاق وقــد أخــذ ذهبهــا وتطلــب احلكــم لهــا بإعطائــه ذهبهــا‬\n  ‫‪،‬بعــرض دعــوى املدعيــة علــى املدعــى عليــه أنكــر مــا جــاء فيهــا وأنــه لــم‬\n  ‫يأخــذ منهــا شــيئ ًا والــذي حصــل أنــه رأى زوجتــه تلبــس الذهــب يف اليــوم‬\n  ‫الســابع مــن زواجهــا وال يــدري أيــن وضعتــه بعــد ذلــك وبعــد رجوعهــم‬\n  ‫مــن الســفر لــم يشــاهد الذهــب ‪ ،‬بطلــب البينــة مــن املدعيــة قالــت ال‬\n  ‫بينــة لهــا ‪ ،‬قــررت املدعيــة أنهــا ال تطلــب ميــن املدعــى عليــه ‪ ،‬بنــاء علــى‬\n  ‫مــا تقــدم مــن الدعــوى واإلجابــة وإلنــكار املدعــى عليــه دعــوى املدعيــة‬\n  ‫‪ ،‬ونظــر ًا لقولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن‬\n\n                                                                                          ‫‪44‬‬\n\f     ‫علــى مــن أنكــر ) وألنــه ال بينــة للمدعيــة علــى دعواهــا ‪ ،‬صــدر احلكــم‬\n     ‫بــرد دعــوى املدعيــة لعــدم ثبوتهــا ‪ ،‬قــرر املدعــى عليــه قناعتــه باحلكــم‬\n     ‫وقــررت املدعيــة اعتراضهــا علــى احلكــم بالئحــة اعتراضيــة فأفهمــت‬\n         ‫بتعليمــات االســتئناف ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n     ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32421469‬وتاريــخ‬\n     ‫‪ 1432/09/21‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321217633‬وتاريــخ‬\n     ‫‪1432/09/21‬ه ـ ففــي يــوم األربعــاء املوافق‪1432/10/30‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 01 : 51‬وفيهــا حضــرت ارتيريــة اجلنســية مبوجــب‬\n     ‫اإلقامــة رقــم وادعــت علــى الغائــب عــن مجلــس احلكــم قائلــه أن املدعــى‬\n     ‫عليــه كان زوجــي وطلقنــي مبوجــب صــك الطــاق رقــم ‪ 2/42/2‬وتاريخ‬\n     ‫‪1431/11/23‬ه ـ وقــد أخــذ ذهبــي وهــو عبــاره عــن طقم حبشــي وخمس‬\n     ‫بناجــر وســت خــوامت وطقــم ذهــب ومغــش ذهــب أطلــب احلكــم عليــه‬\n     ‫بإعطائــي ذهبــي هــذه دعــواي وإلحضــار املدعــى وعليــه تأجلــت اجللســة‬\n     ‫ويف جلســة أخــرى لــدي أنــا القاضــي يف احملكمــة العامــة مبحافظة جدة‬\n     ‫خلــف فضيلــة الشــيخ عليــه ففــي يــوم األحــد املوافق‪1433/11/28‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــرت املدعيــة ‪ .....‬أريتيريــة‬\n     ‫اجلنســية باإلقامــة رقــم‪ ...‬وحضــر حلضورهــا املدعــى عليــه ‪ .....‬اثيوبــي‬\n     ‫اجلنســية باإلقامــة رقــم‪ ...‬وبنــاء علــى املــادة ‪ 166‬مــن نظــام املرافعــات‬\n     ‫الشــرعية جــرى تــاوة مــا مت ضبطــه ســابقا فصادقــت عليــه املدعيــة‬\n‫‪45‬‬\n\f‫وبعــرض مــا جــاء يف الدعــوى علــى املدعــى عليــه قــال مــا ذكرتــه املدعيــة‬\n‫مــن الطــاق فصحيــح وأمــا مــا ذكرتــه مــن الذهــب فليــس بصحيــح وأنــا‬\n‫لــم أخــذ منهــا شــيئا والــذي حصــل أنــي رأيــت زوجتــي يف ســابع يــوم مــن‬\n‫زواجــي تلبــس الذهــب وال أدري أيــن وضعتــه بعــد ذلــك وبعــد رجوعنــا‬\n‫مــن الســفر لــم أشــاهد الذهــب أبــدا هكــذا قــال وبطلــب البينــة مــن‬\n‫املدعيــة قالــت ال بينــة لــدي هكــذا قالــت فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وإلنــكار املدعــى عليــه دعــوى املدعيــة ولقولــه صلــى‬\n‫اهلل عليــه وســلم ‪ ( :‬البينــة علــى املدعــي واليمــن علــى مــن أنكــر )‬\n‫احلديــث وألنــه ال بينــة للمدعيــة علــى دعواهــا فقــد حكمــت بــرد دعــوى‬\n‫املدعيــة لعــدم ثبوتهــا وأفهمتهــا بــأن لهــا ميــن املدعــى عليــه فقالــت ال‬\n‫أطلــب ميينــه هكــذا قالــت وبعرضــه علــى املدعــى عليــه قــرر القناعــة‬\n‫وبعرضــه علــى املدعيــة قــررت عــدم القناعــة وطلبــت االســتئناف فأجيــب‬\n‫إلــى طلبهــا وجــرى تســليمها نســخة مــن احلكــم لالعتــراض عليــه خــال‬\n‫ثالثــن يومــا تبــدأ مــن تاريــخ احلكــم وإذا انتهــت مــدة االعتــراض ولــم‬\n‫تتقــدم بالالئحــة االعتراضيــة فيســقط حقهــا يف طلــب االســتئناف‬\n‫ويكتســب احلكــم القطعيــة وأغلقــت اجللســة الســاعة ‪ 11 : 30‬وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                         ‫يف ‪1433/11/28‬ه ـ ‪.‬‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن قضــا َة‬\n‫االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n‫مــن فضيلــة الشــيخ القاضــي باحملكمــة العامــة بجــدة املســجل بعــدد‬\n‫‪ 33468935‬وتاريــخ ‪1433/11/29‬ه ـ املتضمــن دعــوى ضــد احملكــوم‬\n\n\n                                                                                    ‫‪46‬‬\n\f     ‫في ــه مبا دون باطن الصك ‪ ،‬وبدراســة احلكم وص ــورة ضبط ــه والئحته‬\n     ‫االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم وبــاهلل التوفيــق وصل ــى اهلل‬\n                                   ‫عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪47‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":44,"source_page_end":47,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1b96da165fee162158cc3b3a0798e27128ba06723d98881de5154a9260f8bd64","normalized_text_hash":"14c729254ee4ce7fb09752bf28f3c60d60cd0be2d5ee068dcaba10a9b3e59d7b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p44-33468935"},{"id":"2c246ac4-717b-556b-9752-3681db866fac","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -إعادة املهر مقابل الطاق -قيام والد الزوجة بتسليم زوج ابنته قيمة املهر مقابل الطاق -إقرار املدعى عليه (الزوج) باستالم املهر من والد زوجته هبة -ثبوت وقوع الطاق بدون عوض قبل قبض املهر -مطالبة والد الزوجة إعادة قيمة املهر -مصادقة املدعى عليه على حدوث الطاق بغير عوض -إلزام املدعى عليه بإعادة املبلغ للمدعي .","document_number":"3436764","case_number":"33583387","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/13","year":"1434","subject":"زوجية -إعادة املهر مقابل الطاق -قيام والد الزوجة بتسليم زوج ابنته قيمة املهر مقابل الطاق -إقرار املدعى عليه (الزوج) باستالم املهر من والد زوجته هبة -ثبوت وقوع الطاق بدون عوض قبل قبض املهر -مطالبة والد الزوجة إعادة قيمة املهر -مصادقة املدعى عليه على حدوث الطاق بغير عوض -إلزام املدعى عليه بإعادة املبلغ للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/13 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3436764 :‬‬\n                   ‫َر ْق ُم الدعوى‪33583387 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34202537‬تاريخه‪1434/4/30 :‬هـ‬\n\n\n‫زوجيــة ‪ -‬إعــادة املهــر مقابــل الطــاق‪ -‬قيــام والــد الزوجــة بتســليم‬\n‫زوج ابنتــه قيمــة املهــر مقابــل الطــاق ‪ -‬إقــرار املدعــى عليــه (الــزوج)‬\n‫باســتالم املهــر مــن والــد زوجتــه هبــة ‪ -‬ثبــوت وقــوع الطــاق بــدون عــوض‬\n‫قبــل قبــض املهــر ‪ -‬مطالبــة والــد الزوجــة إعــادة قيمــة املهــر ‪ -‬مصادقــة‬\n‫املدعــى عليــه علــى حــدوث الطــاق بغيــر عــوض ‪ -‬إلــزام املدعــى عليــه‬\n                                                      ‫بإعــادة املبلــغ للمدعــي ‪.‬‬\n\n\n\n\n                       ‫‪ .1‬قاعدة‪ :‬األصل أن على القابض ملال غيره الضمان‬\n                                            ‫‪ .2‬قاعدة‪ :‬األصل عدم الهبة‬\n                           ‫‪ .3‬املادة ‪ 49‬و ‪ 176‬من نظام املرافعات الشرعية‬\n\n\n\n\n‫أقــام وكيــل امــرأة دعــوى يطالــب فيهــا املدعــى عليــه بإعــادة مبلــغ‬\n‫اســتلمه مــن وليهــا مقابــل طالقهــا ألنــه تبــن أن الطــاق أثبــت مبوجــب‬\n‫صــك شــرعي قبــل اســتالم العــوض وذكــر فيــه أنــه بــا مقابــل فــا حــق‬\n‫للمدعــى عليــه باســتالم العــوض ‪ ،‬أقــر املدعــى عليــه مبــا جــاء يف دعــوى‬\n‫املدعــي مــن أنــه اســتلم املبلــغ مــن ولــي مطلقتــه وذكــر أنــه هبــة ‪ ،‬عــدل‬\n‫املدعــي وكالــة دعــواه فجعــل املدعــي ولــي املــرأة ألن املبلــغ صــرف مــن‬\n\n                                                                                      ‫‪48‬‬\n\f     ‫حســابه للمدعــى عليــه ‪ ،‬طلبــت احملكمــة مــن املدعــى عليــه البينــة علــى‬\n     ‫مــا ذكــره مــن الهبــة فقــال ال بينــة لــي فأفهمتــه احملكمــة بــأن لــه ميــن‬\n     ‫املدعــي الــذي ســلمه املبلــغ بأنــه لــم يســلمه لــه هبــة وإمنــا مقابــل طــاق‬\n     ‫ابنتــه وأنــه لــم يعلــم بطالقهــا قبــل تســليم املبلــغ ‪ ،‬فطلــب املدعــى عليــه‬\n     ‫ميــن املدعــي فحلفهــا ألن مــن املقــرر شــرعا أن األصــل عــدم الهبــة وأن‬\n     ‫القابــض ملــال غيــره عليــه الضمــان وألن اليمــن تشــرع يف جانــب أقــوى‬\n     ‫املتداعيــن وحيــث حلــف املدعــي أنــه لــم يســلم املــال للمدعــى عليــه هبــة‬\n     ‫وإمنــا مقابــل الطــاق ‪ ،‬لــذا حكمــت احملكمــة علــى املدعــى عليــه بدفــع‬\n                     ‫املبلــغ للمدعــي ‪ ،‬اعتــرض املدعــى عليــه ‪ ،‬صــدق احلكــم ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة وبنــاء‬\n     ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة برقــم‬\n     ‫وتاريخ ‪1433/9/20‬هـ املقيدة باحملكمة برقم وتاريخ ‪1433/09/20‬هـ‬\n     ‫حضــر ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬بصفتــه وكيال‬\n     ‫عن مبوجب الوكالة الصادرة من كتابة عدل برقم يف ‪1433/9/13‬هـ‬\n     ‫وادعــى علــى احلاضــر معــه ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪ ....‬بصفتــه وكيــا عــن مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n     ‫برقــم ‪ ....‬يف ‪1433/11/2‬ه ـ قائــا يف دعــواه كان املدعــى عليــه أصالــة‬\n     ‫زوجــا ملوكلتــي ثــم طلقهــا بتاريــخ ‪1433/6/10‬ه ـ بقولــه لهــا طالــق ثــم‬\n     ‫طالــق ثــم طالــق بعــد الدخــول دون عــوض قاصــدا إيقــاع ثــاث طلقــات‬\n     ‫وذلــك مبوجــب الصــك الصــادر مــن هــذه احملكمــة يف ‪1433/6/14‬ه ـ‬\n     ‫ولــم يخبــر موكلتــي بهــذا الطــاق حــن إصــدار صكــه وبعــد حصــول‬\n\n‫‪49‬‬\n\f‫الطــاق حضــر املدعــى عليــه وكالــة وهــو والــد املدعــى عليــه أصالــة‬\n‫إلــى والــد موكلتــي وتفــاوض معــه علــى أمــر موكلتــي واملدعــى عليــه‬\n‫أصالــة وانتهــى هــذا التفــاوض علــى أن يقــوم والــد موكلتــي بإرجــاع‬\n‫مهرهــا وقــدره أربعــون ألــف ريــال علــى أن يقــوم املدعــى عليــه بتطليــق‬\n‫موكلتــي بعــد اســتالم مبلــغ املهــر فقــام والــد موكلتــي بتســليم املهــر‬\n‫للمدعــى عليــه أصالــة وقــدره أربعــون ألــف ريــال وذلــك مبوجــب الشــيك‬\n‫رقــم ‪ 117‬يف ‪1433/8/14‬ه ـ علــى مصــرف الراجحــي مــن حســاب والــد‬\n‫موكلتــي ألمــر املدعــى عليــه أصالــة مببلــغ أربعــن ألــف ريــال ‪ 40000‬ثــم‬\n‫ســلم املدعــى عليــه ورقــة مراجعــة حملكمــة الســتالم صــك الطــاق‬\n‫وعنــد اســتالم والــد موكلتــي لصــك الطــاق املذكــور تبــن أن املدعــى‬\n‫عليــه أصالــة طلــق موكلتــي ثــاث طلقــات بــدون عــوض قبــل تفــاوض‬\n‫والــده مــع والــد موكلتــي وقــد خرجــت موكلتــي مــن العــدة ولكــون‬\n‫املدعــى عليــه أصالــة اســترجع املهــر مــع أنــه طلــق قبــل اســترجاع املهــر‬\n‫بــدون عــوض فإنــي أطلــب احلكــم علــى املدعــى عليــه أصالــة بــأن يعيــد‬\n‫إلــى موكلتــي مــا اســتلمه مــن والدهــا وقــدره أربعــون ألــف ريــال وذلــك‬\n‫ألن والــد موكلتــي أعــاد املهــر مــن حســاب موكلتــي نيابــة عنهــا هــذه‬\n‫دعــواي وبســؤال املدعــى عليــه وكالــة عــن دعــوى املدعــي وكالــة أجــاب‬\n‫بقولــه مــا ذكــره املدعــي وكالــة يف دعــواه مــن أن موكلــي طلــق‬\n‫موكلتــه بــدون عــوض باللفــظ املذكــور بعــد الدخــول بهــا وأن موكلــي‬\n‫اســتلم مــن حســاب والــد موكلــة املدعيــة بعــد الطــاق أربعــن ألــف ريــال‬\n‫بالشــيك املذكــور فهــذا صحيــح ولكــن والــد املدعيــة هــو الــذي ســلمني‬\n‫الشــيك املذكــور باملبلــغ املذكــور وذكــر أنــه هبــة البنــي املدعــى عليــه‬\n‫أصالــة فقمــت أنــا بتســليم ابنــي املدعــى عليــه أصالــة الشــيك املذكــور‬\n\n\n                                                                                    ‫‪50‬‬\n\f     ‫فصرفــه موكلــي ولــم نطلــب ال أنــا وال موكلــي إعــادة شــيء مــن مهــر‬\n     ‫موكلــة املدعــي ولــم نفــاوض والدهــا علــى ذلــك هكــذا أجــاب املدعــى‬\n     ‫عليــه وكالــة ونظــرا إلــى أن املهــر ســلم مــن والــد املدعية أصالــة بتصادق‬\n     ‫الطرفــن وهــو غيــر ممثــل يف هــذه الدعــوى فقــد قــررت إدخالــه لســماع‬\n     ‫مــا لديــه ووافــق الطرفــان علــى ذلــك ويف جلســة أخــرى حضــر ســعودي‬\n     ‫بالســجل رقــم وقــرر بقولــه إن املبلــغ املدعــى بــه دفعتــه أنــا مــن حســابي‬\n     ‫اخلــاص للمدعــى عليــه أصالــه وقــدره أربعــون ألــف ريــال وأنــا وبنتي شــيء‬\n     ‫واحــد ولذلــك قدمــت الدعــوى هــي وكل مــا جــاء يف دعــوى املدعــي‬\n     ‫وكالــة صحيــح وأطلــب إدخالــي يف الدعــوى واحلكــم لــي باملبلــغ املدعى‬\n     ‫بــه وإنــي أوكل املدعــي وكالــة يف النيابــة عنــي يف هــذه الدعــوى لــه حــق‬\n     ‫املرافعــة واملدافعــة والصلــح واإلقــرار والقناعــة باألحــكام واالعتــراض‬\n     ‫عليهــا هكــذا قــرر احلاضــر ووافــق الطرفــان علــى إدخالــه ويف جلســة‬\n     ‫أخــرى حضــر املدعــي وكالــة واملدعــى عليــه وكالــة وقــد قــرر املدعــي‬\n     ‫وكالــة بقولــه إن موكلتــي ليــس لهــا دعــوى يف املبلــغ املدعــى بــه ألنــه‬\n     ‫لوالدهــا وإننــي أعــدل الطلــب يف دعــواي وأطلــب احلكــم باملبلــغ املدعــى‬\n     ‫بــه لوالــد موكلتــي املذكــور الــذي وكلنــي باملطالبة يف اجللســة املاضية‬\n     ‫هكــذا قــرر املدعــي وكالــة وقــد ســألت املدعــى عليــه وكالــة عــن‬\n     ‫الشــيك هــل ســلمه والــد املدعيــة بعــد علمــه بالطــاق أو قبلــه فأجــاب إن‬\n     ‫والــد املدعيــة ســلمني الشــيك هبــة باختيــاره بعــد صــدور الطــاق بــدون‬\n     ‫عــوض وبعــد علمــه بــأن الطــاق حصــل بــدون عــوض هكــذا قــرر‬\n     ‫املدعــى عليــه وكالــة وبعرضــه علــى املدعــي وكالــة قــال إن والــد‬\n     ‫موكلتــي ســلم املدعــى عليــه شــيكا بأربعــن ألــف ريــال لصرفــه بأمــره‬\n     ‫هــو ال بأمــر ابنــه املدعــى عليــه أصالــة وذلــك بعــد شــهرين مــن حصــول‬\n\n\n‫‪51‬‬\n\f‫الطــاق وقبــل علمــه بحصــول الطــاق ولــم يســلمه علــى أنــه هبــة وإمنــا‬\n‫علــى أنــه عــوض للطــاق قبــل علمــه بحصولــه فلمــا ســلمه هــذا الشــيك‬\n‫قــام املدعــى عليــه وكالــة بتســليم والــد موكلتــي تذكــرة مراجعــة‬\n‫ملراجعــة احملكمــة الســتالم صــك الطــاق فاتصــل علــي والــد موكلتــي‬\n‫وأخبرنــي بذلــك فقلــت مــا دام أن الطــاق حصــل فإنه ال يســتحق العوض‬\n‫فاســحب الشــيك فقــال إننــي ال أســتطيع ســحبه خشــية حــدوث مشــكلة‬\n‫فقلــت لــه أصــدر شــيكا أخــر بنفــس املبلــغ باســم املدعــى عليــه أصالــة‬\n‫وبأمــره شــخصيا حتــى نســتطيع اســترجاعه بعــد االطــاع علــى صــك‬\n‫الطــاق فقــام والــد موكلتــي بســحب الشــيك األول وإبدالــه بالشــيك‬\n‫محــل الدعــوى ألمــر املدعــى عليــه أصالــة هكــذا قــرر املدعــي وكالــة‬\n‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال صحيــح أن والــد املدعيــة‬\n‫ســلمني شــيكني يف وقتــن مختلفــن باملبلــغ املدعــى بــه األول باســمي‬\n‫والثانــي باســم موكلــي وكالهمــا ســلم بعــد علمــه بحصــول الطــاق‬\n‫وقــد ســلمني الشــيك األول الــذي باســمي عصــرا وطلــب منــي أن أذهــب‬\n‫إلــى احملكمــة لتســجيله بصــك الطــاق ثــم حضــر إلــي بعــد العشــاء مــن‬\n‫نفــس اليــوم واســترجع الشــيك األول وســلمني الشــيك الثانــي وقــال إن‬\n‫ذلــك أســهل عنــد الشــيخ حتــى يســجل أنكــم أخــذمت حقكــم فذهبــت‬\n‫إلــى الشــيخ الــذي أصــدر الطــاق فقــال إن الطــاق حصــل بــدون عــوض‬\n‫هكــذا قــرر املدعــى عليــه وكالــة ويف جلســة أخــرى حضــر املدعــي‬\n‫وكالــة واملدعــى عليــه وكالــة وقــد أحضــر الطرفــان ردا مفصــا حلالــة‬\n‫الزوجــن منــذ العقــد وحتــى الفــراق وقــد أرفــق صــورة مــن تفصيــل‬\n‫املدعــي وكالــة واملدعــى عليــه علــى الدعــوى يف املعاملــة وقــد ســألت‬\n‫الطرفــن هــل لديهمــا زيــادة بينــة وإيضــاح علــى مــا تقــدم فأجابــا بالنفــي‬\n\n\n                                                                                     ‫‪52‬‬\n\f     ‫ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه وكالــة وقــد‬\n     ‫قــدم الطرفــان ردودهمــا وأرفقــت باملعاملــة وهــي ردود مطولــة وقــد‬\n     ‫ســألت املدعــى عليــه وكالــة هــل قــام والــد املدعيــة بتســليم الشــيك بعــد‬\n     ‫تســلمه للصــك أم قبلــه فقــال إننــي ســلمت لوالــد املدعيــة تذكــرة‬\n     ‫املراجعــة وأخبرتــه أن الطــاق حصــل مــن دون عــوض وأن صــك الطــاق‬\n     ‫يف احملكمــة فســلمني الشــيك وال أعلــم هــل كان قــد اســتلم الصــك أم‬\n     ‫ال هكــذا قــرر وبعرضــه علــى املدعــي وكالــة قــرر بقولــه إن موكلــي‬\n     ‫ســلم الشــيك قبــل أن يعلــم أن الطــاق بــدون عــوض هكــذا قــرر املدعــي‬\n     ‫وكالــة فســألت املدعــى عليــه وكالــة هــل لديــه بينــة علــى أن والــد‬\n     ‫املدعيــة ســلم الشــيك بعــد علمــه بــأن الطــاق حصــل بــدون عــوض فقــال‬\n     ‫نعــم لــدي بينــة علــى ذلــك وأطلــب املهلــة إلحضارهــا ويف جلســة أخــرى‬\n     ‫حضــر املدعــي وكالــة واملدعــى عليــه وكالــة وقــد قــرر املدعــى عليــه‬\n     ‫وكالــة بقولــه إننــي ال أســتطيع إحضــار الشــاهد الــذي وعــدت بإحضاره‬\n     ‫يف اجللســة الســابقة وال أســتطيع إحضــار زيــادة بينــة علــى أن املبلــغ هبــة‬\n     ‫أو زيــادة بينــة علــى ســائر مــا قدمتــه وقــد قــرر املدعــي وكالــة بقولــه إننــا‬\n     ‫ال نعلــم لنــا بينــة غيــر مــا قدمنــاه وقــد جــرى االطــاع علــى صــورة الشــيك‬\n     ‫التــي قدمهــا املدعــى عليــه وكالــة وذكــر أنهــا صــورة طبــق األصــل‬\n     ‫فوجــد أن رقــم الشــيك وتاريخــه كمــا ذكــر املدعــي وكالــة وقيمتــه‬\n     ‫وقــد ذكـ ــر فيـ ــه أن املبلـ ــغ اســترجاع كـام ــل املهــر كم ــا اطلعــت علــى‬\n     ‫صـ ــك طــاق املذكــور الص ــادر مــن هــذه احملكمــة برق ــم يف‬\n     ‫‪1433/6/14‬ه ـ املتضمــن طــاق ‪ ..........‬لزوجتــه املدخــول بهــا ‪ ..........‬يف‬\n     ‫‪1433/6/10‬ه ـ بلفــظ طالــق ثــم طالــق ثــم طالــق بقصــد إيقــاع ثــاث‬\n     ‫طلقــات بــدون عــوض فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي وكالــة‬\n\n\n‫‪53‬‬\n\f‫املتضمنــة أن املدعــى عليــه أصالــة اســترجع مهــر بنــت موكلــه وقــدره‬\n‫أربعــون ألــف ريــال مــع أنــه طلــق قبــل اســترجاع املهــر بــدون عــوض وطلبــه‬\n‫احلكــم علــى املدعــى عليــه أصالــة بــأن يعيد إلــى والد موكلتــه املتداخل‬\n‫يف هــذه الدعــوى مــا اســتلمه منــه وقــدره أربعــون ألــف ريــال وملصادقــة‬\n‫املدعــى عليــه وكالــة علــى أن موكلــه طلــق بنــت املدعــي أصالــة‬\n‫املتداخــل يف هــذه الدعــوى بــدون عــوض باللفــظ املذكــور بعــد الدخــول‬\n‫بهــا وأن موكلــه اســتلم مــن حســاب والــد البنــت بعــد الطــاق أربعــن‬\n‫ألــف ريــال بالشــيك املذكــور ودفعــه بــأن هــذا املبلــغ ســلم هبــة ملوكلــه‬\n‫دون طلــب أو تفــاوض علــى إعــادة املهــر ونظــرا إلــى أن صــك الطــاق‬\n‫أثبــت أن الطــاق بــدون عــوض علــى الصفــة املذكــورة ونظــرا إلــى أن‬\n‫األصــل يف القابــض ملــال غيــره الضمــان واألصــل عــدم الهبــة خاصــة أنــه‬\n‫ذكــر يف الشــيك أنــه اســترجاع لكامــل املهــر ممــا يقــوي جانــب املدعــي‬\n‫املتداخــل أنــه إمنــا دفــع عوضــا مــن أجــل التطليــق ال هبــة ونظــرا إلــى أنــه‬\n‫تبــن أن الطــاق حصــل بــدون عــوض قبــل دفــع املبلــغ ولــم يحضــر املدعى‬\n‫عليــه وكالــة بينــة علــى أن املبلــغ دفــع بعــد العلــم أن الطــاق حصــل‬\n‫بــدون عــوض واألصــل عــدم العلــم بذلــك وألن اليمــن تشــرع يف حــق مــن‬\n‫ظهــر صدقــه وقــوي جانبــه تقويــة لقولــه واســتظهارا فقــد أفهمــت املدعى‬\n‫عليــه وكالــة بــأن ملوكلــه ميــن املتداخــل أصالــة والــد البنــت بأنــه إمنــا‬\n‫دفــع املبلــغ املذكــور عوضــا للطــاق ال هبــة وأنــه دفعــه قبــل علمــه بــأن‬\n‫الطــاق حصــل بــدون عــوض فقــال املدعــى عليــه وكالــة نطلــب ميينــه‬\n‫علــى ذلــك وبســؤال املدعــي وكالــة عــن اســتعداد موكلــه باليمــن قــال‬\n‫إن لــدى موكلــي بينــة علــى أن املبلــغ دفــع عوضــا للطــاق ال هبــة وأطلــب‬\n‫ســماعها ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليه وكالة‬\n\n\n                                                                                         ‫‪54‬‬\n\f     ‫وقــد حضــر يف هــذه اجللســة املتداخــل أصالــة وقــرر بقولــه إننــي ال‬\n     ‫أســتطيع إحضــار الشــاهد ومســتعد بــأداء اليمــن املطلوبــة وقــرر املدعــى‬\n     ‫عليــه وكالــة طلبــه ميــن املتداخــل املذكــور وبطلــب اليمني مــن املتداخل‬\n     ‫فهــد العامــر حلــف قائــا واهلل العظيــم إننــي إمنــا دفعــت املبلــغ املذكــور‬\n     ‫وقــدره أربعــون ألــف ريــال عوضــا للطــاق ال هبــة وإننــي دفعتــه قبــل‬\n     ‫علمــي بــأن الطــاق حصــل بــدون عــوض هكــذا حلــف فبنــاء علــى مــا‬\n     ‫تقــدم مــن دعــوى املدعــي وألداء اليمــن املطلوبــة فقــد حكمــت علــى‬\n     ‫املدعــى عليــه أصالــة بــأن يعيــد للمتداخــل املبلــغ املذكــور الــذي اســتلمه‬\n     ‫منــه وقــدره أربعــون ألــف ريــال وبعــرض احلكــم علــى املدعــى عليــه‬\n     ‫وكالــة قــرر عــدم القناعــة وطلــب االســتئناف بالئحــة اعتراضيــة فأفهــم‬\n     ‫بــأن صــك احلكــم يصــدر غــدا وأن عليــه احلضــور غــدا الســتالم صــورة‬\n     ‫صــك احلكــم وتقــدمي الالئحــة خــال ثالثــن يومــا مــن تاريــخ يــوم غــد‬\n     ‫فــإن لــم يقــدم الالئحــة خاللهــا ســقط حقــه يف االســتئناف واكتســب‬\n     ‫احلكــم القطعيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                      ‫آله وصحبه وسلم ‪ .‬حرر يف ‪1434/2/12‬هـ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة وبنــاء‬\n     ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة برقــم‬\n     ‫وتاريــخ ‪1433/9/20‬ه ـ املقيــدة باحملكمة برقــم وتاريخ ‪1433/09/20‬‬\n     ‫ه ـ ففــي يــوم اإلثنــن املوافق‪1434/04/22‬ه ـ افتتحــت اجللســة وقــد‬\n     ‫عــادت إلينــا املعاملــة مــن محكمــة االســتئناف بالقصيــم وبرفقهــا‬\n     ‫قــرار محكمــة االســتئناف رقــم يف ‪1434/4/6‬ه ـ املتضمــن مــا نصــه‬\n     ‫بعــد املقدمــة وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫وأوراق املعاملــة لوحــظ اآلتــي أوال أن املدعــى عليــه وكالــة أقــر باســتالم‬\n\n\n‫‪55‬‬\n\f‫موكلــه للمبلــغ املدعــى بــه بالشــيك املذكــور ورضــي بيمــن املتداخــل‬\n‫املدعــي أصالــة ولــم جنــد أن فضيلتــه حتقــق مــن أن املدعــى عليــه وكالــة‬\n‫مخــول لــه يف الوكالــة حــق اإلقــرار وقبــول اليمــن وذلــك وفــق املــادة‬\n‫‪ 49‬مــن نظــام املرافعــات الشــرعية ثانيــا لــم يــدون فضيلتــه يف الضبــط‬\n‫اســتالم املدعــى عليــه وكالــة لنســخة احلكــم لالعتــراض عليــه وأخــذ‬\n‫توقيعــه يف دفتــر الضبــط وهــذا مخالــف ملقتضــى املــادة (‪ )176‬مــن نظــام‬\n‫املرافعــات الشــرعية فعلــى فضيلتــه مالحظــة مــا ذكــر وإحلــاق مــا يجريه‬\n‫بالضبــط والصــك وســجله ثــم إعــادة املعاملــة إلكمــال الزمهــا انتهــى‬\n‫قــرار االســتئناف ويف هــذه اجللســة حضــر املدعــى عليــه وكالــة وحضــر‬\n‫حلضــوره املدعــى عليــه أصالــه ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم وجــرى ســؤال املدعــى عليــه أصالــه هــل خــول موكلــة باإلقــرار‬\n‫وطلــب اليمــن وقبولهــا فأجــاب املدعــى عليــه أصالــه بقولــه إننــي ذهبــت‬\n‫لكاتــب عــدل ووكلــت والــدي بالوكالــة املذكــورة وطلبــت أن أوكلــه‬\n‫يف كل مــا يخــص هــذه القضيــة فأصــدر لــي الوكالــة املذكــورة‬\n‫وبالنســبة لإلقــرار الــذي أقــر بــه موكلــي عنــي فإنــي أنــا الــذي خولــت‬\n‫موكلــي املذكــور باإلقــرار عنــي يف هــذه القضيــة وطلــب اليمــن‬\n‫وقبولهــا والرضــى بهــا وجميــع مــا قالــه موكلــي وأقــر بــه نيابــة عنــي‬\n‫يف اجللســات الســابقة فإنــه صحيــح وقــد مت بعــد الرجــوع إلــي وموافقتــي‬\n‫وقــد أجــزت جميــع مــا قــام بــه نيابــة عنــي يف كل اجللســات الســابقة مــن‬\n‫إقــرار وطلــب ميــن وقبولهــا ورضــا بهــا وغيــر ذلــك هكــذا قــرر املدعــى‬\n‫عليــه أصالــه وعليــه أجيــب أصحــاب الفضيلــة عــن املالحظــة االولــى‬\n‫أن املدعــى عليــه أصالــه قــد أجــاز إقــرار موكلــه عنــه وقبولــه اليمــن‬\n‫عنــه وذكــر أنــه مت بعــد الرجــوع إليــه وموافقتــه وأجيــب عــن املالحظــة‬\n\n\n                                                                                   ‫‪56‬‬\n\f     ‫الثانيــة بــأن املدعــى عليــه وكالــة ســلم نســخة مــن الصــك يف تاريــخ‬\n     ‫‪1434/2/13‬ه ـ وقــدم الالئحــة االعتراضيــة قبــل انتهــاء املــدة ولــم يتــم‬\n     ‫أخــذ توقيعــه علــى الضبــط ســهوا مــن الكاتــب وقــد قــرر املدعــى عليــه‬\n     ‫وكالــة يف هــذه اجللســة بقولــه إننــي اســتلمت صــورة صــك احلكــم يف‬\n     ‫تاريخ‪1434/2/13‬ه ـ هكــذا قــرر هــذا مــا أجيــب بــه أصحــاب الفضيلــة‬\n     ‫ولــم يظهــر لــي خــاف مــا حكمــت بــه وبــاهلل التوفيــق وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/22‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة وبنــاء‬\n     ‫علــى املعاملــة احملالــة لنــا من فضيلة رئيس احملكمة العامة برقم وتاريخ‬\n     ‫‪1433/9/20‬ه املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/09/20‬ه ـ ففــي‬\n     ‫يـ ــوم الســبت املوافــق ‪1434/05/11‬ه ـ افتتحــت اجللســة الســاعة الثانيــة‬\n     ‫عشــر وخمســة عشــرة دقيقــة وقــد عــادت إلينــا املعاملــة مــن محكمــة‬\n     ‫االســتئناف بالقصيــم برقــم يف ‪1434/5/11‬ه ـ وبرفقهــا قــرار محكمــة‬\n     ‫االســتئناف بالقصيــم رقــم يف ‪1434/4/30‬ه ـ املتضمــن املصادقــة علــى‬\n     ‫احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                            ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/11‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا رئيــس احملكمــة والقائــم بعمــل‬\n     ‫املكتــب القضائــي الســادس وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة برقــم وتاريــخ ‪1433/09/20‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/09/20‬ه ـ ففــي يــوم اإلثنــن‬\n     ‫املوافق‪1434/06/12‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة‬\n     ‫ســعودي بالســجل رقــم بصفتــه وكيــا عــن مبوجــب الوكالــة الصــادرة‬\n     ‫مــن كتابــة عــدل برقــم يف ‪1433/9/13‬ه وقــرر بقولــه إننــي اســتلمت‬\n\n\n‫‪57‬‬\n\f‫املبلــغ احملكــوم بــه وقــدره أربعــون ألــف ريــال مبوجــب الشــيك املســحوب‬\n‫علــى مصــرف الراجحــي فــرع الريــان برقــم يف ‪2013/4/10‬م وقــرر أنــه‬\n‫هــذا هــو آخــر املبلــغ املطالــب بــه هكــذا قــرر وعلــى ذلــك جــرت منــي‬\n‫املصادقــة وبذلــك تكــون القضيــة منتهيــة وجــرى إحلاقــه حتــى ال يخفــى‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪1434/6/12‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة عنيــزة برقــم ( ‪ ) ....‬وتاريــخ ‪1434/4/24‬هــ؛ املقيــدة‬\n‫لــدى احملكمــة برقــم ( ‪ ) ....‬وتاريــخ ‪1434/4/28‬هــ؛ اخلاصــة بدعــوى‬\n‫‪ ....‬الوكيــل عــن ‪ ....‬ضــد ‪ ....‬الوكيــل عــن ‪ ....‬؛ بشــأن مطالبتــه بــأن‬\n‫يعيــد املدعــى عليــه أصالــة إلــى موكلتــه املهــر الــذي اســتلمه مــن والدهــا‬\n‫وقــدره أربعــون ألــف ريــال؛ املنتهيــة بالصــك الصــادر مــن فضيلــة الشــيخ‬\n‫‪ ....‬القاضــي باحملكمــة؛ املســجل برقــم ( ‪ ) ....‬وتاريــخ ‪1434/2/13‬ه ـ‬\n‫؛ املتضمــن حكــم فضيلتــه علــى املدعــى عليــه أصالــة بــأن يعيــد املبلــغ‬\n‫املذكــور إلــى والــد املدعيــة أصالــة ؛ علــى النحــو املفصــل فيــه؛ وقــد‬\n‫ســبق منــا دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة‪ .‬وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط والصك‬\n‫ـاء علــى قرارنــا رقــم ( ‪ ) ....‬وتاريــخ ‪1434/4/6‬ه ـ قررنــا املصادقة على‬   ‫بنـ ً‬\n‫مــا حكــم بــه فضيلتــه بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل‬\n                                     ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                      ‫‪58‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":48,"source_page_end":58,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2ca6757cf50f851e32207d4686367bce9d01ed9c763ca16684bdaee6af419a7d","normalized_text_hash":"49124a4073a3244e8fac99409905636faa9ff4fc363788c39fa1729cf1b47c14","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p48-3436764"},{"id":"44b77a53-08f1-543e-81b0-3adba6a7ff33","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -مطالبة زوج إمتام النكاح أو رد املهر والشبكة -صادق املدعى عليه وقرر أن الزوجة رفضت إمتام النكاح لغير سبب ظاهر -قصر الطلبات على رد املهر والشبكة واملبالغ التي سلمها املدعى -ال ضرر وال ضرار -احلكم بإلزام املدعى عليها إرجاع املبالغ املدعى بها - إفهام املدعى بعدم استالم املبلغ إال عند املخالعة.","document_number":"34201385","case_number":"33659139","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/29","year":"1434","subject":"زوجية -مطالبة زوج إمتام النكاح أو رد املهر والشبكة -صادق املدعى عليه وقرر أن الزوجة رفضت إمتام النكاح لغير سبب ظاهر -قصر الطلبات على رد املهر والشبكة واملبالغ التي سلمها املدعى -ال ضرر وال ضرار -احلكم بإلزام املدعى عليها إرجاع املبالغ املدعى بها - إفهام املدعى بعدم استالم املبلغ إال عند املخالعة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/4/29 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34201385 :‬‬\n                        ‫َر ْق ُم الدعوى‪33659139 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34251262‬تاريخه‪1434/6/25 :‬هـ‬\n\n\n     ‫زوجيــة ‪ -‬مطالبــة زوج إمتــام النــكاح أو رد املهــر والشــبكة ‪ -‬صــادق املدعى‬\n     ‫عليــه وقــرر أن الزوجــة رفضــت إمتــام النــكاح لغيــر ســبب ظاهــر‪ -‬قصــر‬\n     ‫الطلبــات علــى رد املهــر والشــبكة واملبالــغ التــي ســلمها املدعــى ‪ -‬ال ضــرر‬\n     ‫وال ضــرار ‪ -‬احلكــم بإلــزام املدعــى عليهــا إرجــاع املبالــغ املدعــى بهــا ‪-‬‬\n                           ‫إفهــام املدعــى بعــدم اســتالم املبلــغ إال عنــد املخالعــة‪.‬‬\n\n\n\n\n                   ‫‪ .1‬قول الرسول صلى اهلل عليه وسلم (ال ضرر وال ضرار)‬\n                                                      ‫‪ .2‬قاعدة الضرر يزال‬\n     ‫‪ .3‬مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة يف‬\n                                                           ‫تســبيب احلكــم ‪.‬‬\n\n\n\n\n     ‫أقــام املدعــي دعــوى يطالــب والــد زوجتــه بإمتــام الــزواج ومتكينــه مــن‬\n     ‫زوجتــه أو إرجــاع املهــر والشــبكة ‪ ،‬اقــر املدعــى عليــه مبــا جــاء يف‬\n     ‫دعــوى املدعــي وقــرر أن ابنتــه هــي التــي رفضــت إمتــام النــكاح فجــرى‬\n     ‫إحضارهــا وســؤالها فقــررت انــه ال رغبــة لهــا يف إمتــام النــكاح مــن غيــر‬\n     ‫ســبب ظاهــر فقــرر املدعــي انــه ال مانــع لديــه مــن مخالعــة املدعــى عليهــا‬\n     ‫مقابــل إعــادة املبالــغ التــي دفعهــا لهــا مــن املهــر والشــبكة كمــا قــررت‬\n\n‫‪59‬‬\n\f‫املــرأة ووليهــا املوافقــة علــى املخالعــة بعــد خصــم قيمــة احلفــل الــذي أقيــم‬\n‫بعــد كتابــة العقــد ‪ ،‬وعظــت احملكمــة املــرأة للرجــوع إلــى زوجهــا إال‬\n‫أنهــا أصــرت علــى مفارقتــه وألن املانــع مــن إمتــام النــكاح كان مــن قبــل‬\n‫املــرأة ونظــر ًا الن الضــرر يــزال ولقــول الرســول صلــى اهلل عليــه وســلم‬\n‫( ال ضــرر وال ضــرار ) وألن مــا يطالــب بــه املدعــى عليــه مــن خصــم‬\n‫قيمــة وليمــة العقــد غيــر وجيــه ألنــه قــام بهــا مــن تلقــاء نفســه ولــم تكــن‬\n‫مشــروطه يف العقــد لــذا حكمــت احملكمــة علــى املدعــى عليــه وابنتــه‬\n‫ا وقيمــة الشــبكة وثبــت لــدى احملكمــة مخالعــة‬           ‫بإعــادة املهــر كام ـ ً‬\n    ‫املدعــى للمدعــى عليهــا ‪ ،‬اعتــرض املدعــى عليــه ‪ ،‬صــدق احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n‫العامــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بخميــس مشــيط برقــم ‪ 33659139‬وتاريــخ‬\n‫‪1433/11/16‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332040183‬وتاريــخ‬\n‫‪1433/11/16‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1434/01/27‬ه ـ افتتحــت‬\n‫اجللســة الســاعة (‪ )9:00‬وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ ).....‬وادعــى علــى احلاضــر معــه (‪ ).....‬ســعودي‬\n‫ا يف دعــواه إنــه يف شــهر شــعبان لعــام ‪1433‬ه ـ قمت بخطبة‬      ‫اجلنســية قائـ ً‬\n‫ابنــة هــذا احلاضــر املســماة (‪ ).....‬وقــد قــام املدعــى عليــه بالترحيــب بــي‬\n‫وقمــت بتســليمه يــوم اخلطبــة مبلغ ـ ًا ثــم بعــد ذلــك ويف تاريــخ كتابــة‬\n‫العقــد الشــرعي ‪1433/9/9‬ه ـ طلــب مهــر ًا وشــبكة ذهــب وبالفعــل‬\n‫قمــت بتســليمه مبلغ ـ ًا مبوجــب شــيك مســحوب علــى مصــرف (‪).....‬‬\n\n                                                                                         ‫‪60‬‬\n\f     ‫برقــم (‪ ).....‬إضافــة إلــى خمســة االف ريــال الســابقة التــي ســلمتها لــه‬\n     ‫يــوم اخلطبــة وشــبكة ذهــب مببلــغ كمــا أننــي قــد ســلمت ابنتــه مبلغ ـ ًا‬\n     ‫بعــد أن طلبــت هــذا املبلــغ لشــراء جــوال ودبلــة يــوم كتابــة العقــد كمــا‬\n     ‫أننــي قــد حولــت لهــا مبلغــا يف تاريــخ ‪1433/9/23‬ه ـ بعــد أن طلبــت ذلــك‬\n     ‫منــي لشــراء أغــراض للعيــد وبعــد ذلــك طلبــت منــه حتديــد موعــد للــزواج‬\n     ‫ولكــن املدعــى عليــه ماطــل بــي بشــكل كبيــر ولــذا فإنــي أطالبــه‬\n     ‫ا أو إرجــاع املبلــغ الــذي ســلمته لــه والبنتــه وإرجــاع‬‫اآلن بتزويجــي عاجـ ً‬\n     ‫الشــبكة هــذه دعــواي وبســؤال املدعــى عليــه عــن ذلــك أجــاب قائــا‬\n     ‫مــا ذكــره املدعــي يف دعــواه مــن خطبتــه البنتــي (‪ ).....‬يف شــهر شــعبان‬\n     ‫واســتالمي منــه مبلغـ ًا مبوجــب الشــيك الــذي ذكــره يــوم كتابــة العقــد‬\n     ‫صحيــح وأيض ـ ًا مــا ذكــره مــن أنــه ســلم شــبكة ذهــب البنتــي صحيــح‬\n     ‫وقــد قمــت أنــا باالتصــال عليــه وطلبــت ذلــك منــه إال أننــي ال أعلــم عــن‬\n     ‫قيمتهــا وأمــا مــا ذكــره مــن أنــه ســلم مبلغ ـ ًا البنتــي بعــد أن طلبــت منــه‬\n     ‫هــذا املبلــغ لشــراء جــوال ودبلــة يــوم كتابــة العقــد وأنــه حــول لهــا مبلغـ ًا‬\n     ‫يف تاريــخ ‪1433/9/23‬ه ـ بعــد أن طلبــت ذلــك منــه لشــراء أغــراض للعيد‬\n     ‫فــا أعلــم عــن ذلــك شــيئا وأمــا مــا ذكــره مــن أنــه طلــب منــي حتديــد‬\n     ‫موعــد الــزواج ولكنــي ماطلــت بــه فــا صحــة لذلــك وأمــا طلبــه اآلن‬\n     ‫تزويجــه فأنــا ال مانــع لــدي إال أن البنــت رفضــت ذلــك ولــم تعــد ترغــب يف‬\n     ‫الــزواج منــه وأنــا مســتعد بتســليمه فقــط نظــر ًا ألننــي قمــت بعمــل حفــل‬\n     ‫يــوم كتابــة العقــد وقــد كلفنــي ذلــك مبلغـ ًا هكذا أجــاب وبعرض ذلك‬\n     ‫علــى املدعــي قــال الصحيــح مــا ذكرتــه وأمــا مــا ذكــره مــن أنــه أقــام‬\n     ‫حفلــة عشــاء يــوم كتابــة العقــد وكلفتــه املبلــغ الــذي ذكــره فلــم أطلــب‬\n     ‫ذلــك منــه وال عالقــة لــي بذلــك أبــد ًا هكــذا أجــاب وبعــرض ذلــك علــى‬\n\n\n‫‪61‬‬\n\f‫املدعــى عليــه قــال مــا ذكــره مــن أنــه لــم يطلــب ذلــك فصحيــح ولكنهــا‬\n‫عــادة معروفــة بــن النــاس هكــذا أجــاب ثــم جــرى ســؤال املدعــى عليــه‬\n‫عــن ابنتــه املذكــورة فقــال لــم أحضرهــا يف هــذا اليــوم فجــرى إفهامــه‬\n‫بضــرورة إحضارهــا يف اجللســة القادمــة فقــال أنــا مســتعد بذلــك وألجــل‬\n‫ذلــك فقــد رفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي واملدعــى عليــه‬\n‫وقــد أحضــر معــه ابنتــه زوجــة املدعــي املســماة (‪ ).....‬ســعودية اجلنســية‬\n‫ســجل مدنــي رقــم (‪ ).....‬بعــد أن جــرى إفهامــه يف اجللســة الســابقة‬\n‫بإحضارهــا وقــد جــرى ســؤال ابنتــه يف هــذه اجللســة عــن رغبتهــا يف إمتــام‬\n‫الــزواج مــن املدعــي مــن عــدم ذلــك فأجابــت قائلــة ليــس لــي أي رغبــة‬\n‫يف الــزواج منــه أبــدا هكــذا أجابــت وبعــرض ذلــك علــى املدعــي قــال‬\n‫إننــي أحصــر مطالبتــي اآلن يف إرجــاع املبلــغ الــذي مت اســتالمه مــن قبــل‬\n‫املدعــى عليــه وابنتــه كمــا أننــي مســتعد مبخالعــة ابنتــه بعــد اســتالمي‬\n‫لهــذا املبلــغ هكــذا قــرر ثــم جــرى ســؤالها عــن اســتالمها يف يــوم كتابــة‬\n‫العقد ملبلغ وعن اســتالمها ملبلغ يف تاريخ ‪1433/9/23‬هـ فأجابت قائلة‬\n‫نعــم لقــد اســتلمت هذيــن املبلغــن املذكوريــن كمــا جــرى ســؤالها عــن‬\n‫اســتالمها لشــبكة الذهــب يف يــوم كتابــة العقــد مــن عدمــه فصادقــت‬\n‫علــى صحــة ذلــك فجــرى ســؤالها هــل تعلمــن قيمتهــا قالــت ال أعلــم عــن‬\n‫قيمتهــا أي شــيء هكــذا أجابــت ثــم جــرى ســؤال املدعــي عــن إثبــات‬\n‫قيمــة شــبكة الذهــب فقــال ليــس لــدي اآلن أي إثبــات لقيمتهــا نظــر ًا‬\n‫لكونــي اشــتريتها مبوجــب فاتــورة ووضعتهــا مــع نفــس شــبكة الذهــب‬\n‫عنــد تســليمي لزوجتــي هــذه احلاضــرة وبعــرض ذلــك عليهــا قالــت نعــم‬\n‫رأيــت الفاتــورة مــع شــبكة الذهــب ولكننــي ال أعلــم عــن قيمتهــا شــيئ ًا‬\n‫لكننــي مســتعدة بإرجــاع قيمتهــا التــي ذكرهــا هكــذا أقــرت ثــم جــرى‬\n\n\n                                                                                    ‫‪62‬‬\n\f     ‫طلــب وثيقــة عقــد النــكاح فأبرزهــا املدعــى عليــه فوجدتهــا صــادرة مــن‬\n     ‫املــأذون الشــرعي (‪ ).....‬بــدون رقــم وبــدون تاريــخ وغيــر مصــادق عليهــا‬\n     ‫مــن قبــل احملكمــة متضمنــة أن قــدر الصــداق أربعــون ألــف ريــال فقــط‬\n     ‫انتهــى وقــد جــرى وعــظ الزوجــة وإفهامهــا بانقيادهــا لبيــت زوجهــا إال‬\n     ‫أنهــا رفضــت ذلــك فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن‬\n     ‫املدعــي قــد طالــب زوجتــه املدعــى عليهــا بانقيادهــا إلــى بيــت الزوجيــة‬\n     ‫أو إرجــاع املبلــغ الــذي ســلمه لهــا ولوالدهــا ومبــا أنهــا رفضــت انقيادهــا‬\n     ‫لبيــت زوجهــا وذكــرت عــدم رغبتهــا فيــه ونظــر ًا ألن املدعــي قــد حصــر‬\n     ‫دعــواه يف مطالبتــه بإرجــاع املبالــغ املســتلمة مــن قبــل زوجتــه ووالدهــا‬\n     ‫ونظــرا ملصادقــة املدعــى عليــه علــى اســتالمه مــن املدعــي ملبلــغ ونظــر ًا‬\n     ‫ملصادقــة زوجــة املدعــي علــى اســتالمها منــه ملبلــغ نقــدي واســتالمها منــه‬\n     ‫شــبكة ذهــب ونظــر ًا الســتعدادها بإرجــاع قيمتهــا ونظــرا ألن املنــع مــن‬\n     ‫إمتــام عقــد الــزواج ليــس مــن قبــل املدعــي وإمنــا مــن قبــل زوجتــه ونظــر ًا‬\n     ‫ألن الضــرر يــزال ونظــر ًا ألن الضــرر يف الشــريعة اإلســامية مدفــوع‬\n     ‫قبــل وقوعــه ومرفــوع بعــد وقوعــه ونظــر ًا لقــول الرســول صلــى اهلل عليــه‬\n     ‫وســلم ( ال ضــرر وال ضــرار) ونظــرا لكــون مــا دفــع بــه املدعــى عليــه‬\n     ‫مــن تســليم املدعــي مبلغـ ًا فقــط مــع إقــراره باســتالمه منــه مبلغـ ًا بحجــة‬\n     ‫أنــه قــد عمــل وليمــة ليلــة كتابــة العقــد غيــر وجيــه وذلــك لكونــه غيــر‬\n     ‫مشــروط عليــه مــن قبــل املدعــي وإمنــا قــام بــه املدعــى عليــه مــن تلقــاء‬\n     ‫نفســه ولهــذا كلــه وملــا تقــدم فقــد قــررت مــا يلــي ‪ :‬أوالً‪ :‬ألزمــت املدعــى‬\n     ‫عليــه املســمى (‪ ).....‬والــد زوجــة املدعــي بإرجــاع املبلــغ الــذي اســتلمه مــن‬\n     ‫املدعــي حــا ًال ثانيـاً‪ :‬ألزمــت املدعــى عليهــا املســماة (‪ ).....‬زوجــة املدعــي‬\n     ‫بإرجــاع املبلــغ النقــدي الــذي اســتلمته مــن املدعــي وإرجــاع قيمــة شــبكة‬\n\n\n‫‪63‬‬\n\f‫الذهــب التــي اســتعدت ســلفا بهــا وبــكل مــا ســبق حكمــت وبعــرض‬\n‫احلكــم علــى املدعــى عليهمــا قــررا معارضتهمــا عليــه واســتعدا بتقــدمي‬\n‫الئحتهمــا االعتراضيــة ويف نفــس اجللســة جــرى تســليمهما صــورة مــن‬\n‫صــك احلكــم لتقــدمي مــا لديهمــا مــن اعتــراض عنــد رغبتهمــا يف ذلــك‬\n‫خــال املــدة احملــددة نظامـ ًا وقدرهــا ثالثــون يومـ ًا ابتــداء مــن تاريــخ هــذا‬\n‫اليــوم وإفهامهمــا بــأن املــدة إذا انتهــت ولــم يتقدمــا باملعارضــة خاللهــا‬\n‫فــإن حقهمــا يف االعتــراض يســقط ويكتســب احلكــم الصفــة القطعيــة‬\n‫ففهمــا ذلــك كمــا جــرى إفهــام املدعــي بأنــه لــن يتــم تســليمه املبلــغ‬\n‫احملكــوم لهبــه إال بعــد قيامــه مبخالعــة زوجتــه فقــال ال مانــع لــدي مــن‬\n‫ذلــك واختتمــت اجللســة عنــد الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/2‬هـ‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم االثنــن املوافــق ‪1434/08/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة التاســعة وقــد عــادت املعاملــة بخطــاب رئيــس‬\n‫محكمــة االســتئناف مبنطقــة عســير برقــم ‪ 341142868‬وتاريــخ‬\n‫‪1434/07/04‬ه ـ مشــفوع ًا بهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة‬\n‫املختصــة بتدقيــق قضايــا األحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال مبحكمــة االســتئناف بعســير رقــم ‪34251262‬‬\n‫يف ‪1434/06/25‬ه ـ املتضمــن إنــه وبدراســة الصــك وصــورة ضبطــه‬\n‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم باألكثريــة قاضــي‬\n‫اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه‬\n‫رئيــس الدائــرة (‪ ).....‬ختمــه وتوقيعــه ولــذا فقــد جــرى إحلاقــه حتــى ال‬\n‫يخفــى وأمــرت بالتهميــش بذلــك علــى ســجله وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم وحــرر يف ‪1434/08/01‬هـ ‪.‬‬\n\n\n                                                                                         ‫‪64‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":59,"source_page_end":64,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9ee537fe04ba6ad0d58a639fd1c4e2a5aa0bdd4161565b21ab779b1e13e1707f","normalized_text_hash":"26f065f9c82fddd4cb43f9ddf9fb6bc24f797ccbf577653df89ee8620990ec66","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p59-34201385"},{"id":"a39b5fda-2887-52a4-b3c6-70a0da86332b","document_type":"judgment","category":"judicial","subcategory":"general","title":"صداق -مطالبة مطلقة بالصداق املؤخر -عدم السداد والدفع أن الطاق سببه الزوجة -السند الشرعي للحكم (عقد النكاح -صك الطاق ومصادقة املدعى عليه على املؤخر وعدم دفعه) -احلكم بإلزام املدعى عليه بدفع املؤخر .","document_number":"34311727","case_number":"34186643","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/3","year":"1434","subject":"صداق -مطالبة مطلقة بالصداق املؤخر -عدم السداد والدفع أن الطاق سببه الزوجة -السند الشرعي للحكم (عقد النكاح -صك الطاق ومصادقة املدعى عليه على املؤخر وعدم دفعه) -احلكم بإلزام املدعى عليه بدفع املؤخر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/9/3 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34311727 :‬‬\n                        ‫َر ْق ُم الدعوى‪34186643 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34322007‬تاريخه‪1434/9/17 :‬هـ‬\n\n\n     ‫صــداق ‪ -‬مطالبــة مطلقــة بالصــداق املؤخــر ‪ -‬عــدم الســداد والدفــع أن‬\n     ‫الطــاق ســببه الزوجــة ‪ -‬الســند الشــرعي للحكــم (عقــد النكاح ‪ -‬صك‬\n     ‫الطــاق ومصادقــة املدعــى عليــه علــى املؤخــر وعــدم دفعــه) ‪ -‬احلكــم‬\n                                            ‫بإلــزام املدعــى عليــه بدفــع املؤخــر ‪.‬‬\n\n\n\n     ‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                                 ‫تســبيب احلكــم‪.‬‬\n\n\n\n\n     ‫ادعــت املدعيــة بدعــوى تطالــب مطلقهــا مبؤخــر صداقهــا ‪ ،‬اقــر املدعــى‬\n     ‫عليــه بالنــكاح والطــاق واملؤخــر وأنــه لــم يســلمه لهــا ورفــض تســليم‬\n     ‫املدعيــة مؤخــر الصــداق وذلــك الن الطــاق كان بســببها وذكــر‬\n     ‫للمحكمــة أســباب ًا دعتــه لطالقهــا وطالــب بــرد دعــوى املدعيــة وتوبيخها‬\n     ‫وأخــذ التعهــد عليهــا بعــدم التعــرض لــه ‪ ،‬أنكــرت املدعيــة مــا قالــه‬\n     ‫املدعــى عليــه واطلعــت احملكمــة علــى عقــد النــكاح ومــا أثبــت فيــه مــن‬\n     ‫مؤخــر وصــك الطــاق املثبــت لطــاق املدعــى عليــه للمدعيــة ‪ ،‬إلقــرار‬\n     ‫الطرفــن بالنــكاح والطــاق واملؤخــر لــذا حكمــت احملكمــة علــى‬\n     ‫املدعــى عليــه بدفــع املؤخــر للمدعيــة ‪ ،‬اعتــرض املدعــى عليــه ‪ ،‬صــدق‬\n                                                                            ‫احلكــم ‪.‬‬\n‫‪65‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض وتاريــخ ‪1434/04/23‬ه ـ املقيــدة باحملكمــة وتاريــخ‬\n‫‪1434/04/23‬ه ـ ففــي يــوم األربعــاء املوافــق ‪1434/09/02‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــرت (‪ ).....‬ســورية اجلنســية مســلمة الديانــة حتمــل‬\n‫اإلقامــة رقــم (‪ ).....‬املعــرف بهــا مــن قبــل أخيهــا (‪ ).....‬ســوري اجلنســية‬\n‫مســلم الديانــة يحمــل رخصــة اإلقامــة رقــم (‪ ).....‬وادعــت ضــد احلاضــر‬\n‫معهــا باملجلــس (‪ ).....‬حامــل بطاقــة هويــة رقــم (‪ ).....‬قائلــة يف دعواهــا إن‬\n‫هــذا احلاضــر كان زوجــي تزوجنــي ودخــل بــي علــى مهــر قــدره أربعــون‬\n‫ألــف ريــال مقــدم واملؤخــر قــدره ثالثــون ألــف ريــال وقــد طلقنــي بتاريــخ‬\n‫‪1434/2/11‬ه ـ وأنــا أطلــب احلكــم عليــه بتســليمي مؤخــر صداقــي‬\n‫وقــدره ثالثــون ألــف ريــال هــذه دعــواي وبعرضهــا علــى املدعــى عليــه قــال‬\n‫مــا ذكرتــه املدعيــة فهــو صحيــح ولكــن ال أوافــق علــى تســليمها املؤخــر‬\n                             ‫ألنهــا مــن دفعنــي لطالقهــا لألســباب التاليــة ‪:‬‬\n‫‪ .1‬إهمــال األوالد وعــدم االهتمــام بتربيتهــم وإســناد أمــور إطعامهــم‬\n‫والعنايــة بهــم وتوصيلهــم إلــى املــدارس إلــى عامــات املنــزل مــع علمهــا‬\n‫برفضــي التــام لذلــك ومنعــي لهــا مــن تكــرار هــذا الفعــل وشــرح خطــورة‬\n                   ‫االعتمــاد والثقــة بعامــات املنــزل ولكــن دون جــدوى‪.‬‬\n‫‪ .2‬اخلــروج إلــى األســواق واملطاعــم بــدون علمــي أو أذنــي والعــودة الــى‬\n‫املنــزل بأوقــات متأخــرة مــن الليــل وذلــك أثنــاء ســفري أو عنــد املبيــت‬\n‫لــدى الزوجــة الثانيــة مــع العلــم مبنعــي لهــا مــرار ًا وتكــرار ًا ويوجــد‬\n\n                                                                                      ‫‪66‬‬\n\f     ‫رســائل جــوال تؤكــد ذلــك وتفيــد عصيانهــا لــي حيــث قامــت أيض ـ ًا‬\n     ‫بقطــع نظــام التتبــع للســيارة بنفســها إلخفــاء أماكــن تواجدهــا وأوقــات‬\n              ‫عودتهــا مــع الســائق ‪ .‬ويشــهد الســائق املســلم مكفولــي بذلــك‬\n     ‫‪ .3‬تعليــم األوالد الكــذب‪ ،‬حيــث تخــرج مــن املنــزل وإيــداع األوالد‬\n     ‫الصغــار عنــد أهلهــا ومــن ثــم اخلــروج إلــى منــزل صديقتهــا (‪ ).....‬التــي‬\n     ‫منعتهــا مــن االتصــال بهــا مــرارا ( مفصــا يف الضبــط ) وجتبــر األوالد‬\n                          ‫الكــذب العمــد وتكــراره الدائــم علــى أنــا والدهــم‪.‬‬\n     ‫‪ .4‬تعليــم األوالد أســلوب احللــف الكــذب علــى القــرآن كتــاب اهلل‬\n                                                                         ‫العظيــم ‪....‬‬\n     ‫‪ .5‬تعليــم األوالد اخلــداع حيــث كان تلبــس نقابهــا أمامــي وتخلعــه عنــد‬\n                                  ‫اخلــروج بدونــي وهــذا عصيــان هلل ثــم ألوامــري‪.‬‬\n     ‫‪ .6‬إرســال البنــات للمبيــت يف بيــت أهلهــا وعصيانهــا ألوامــري بعــدم‬\n                 ‫مبيــت األوالد يف بيــت أي أحــد حتــى ولــو كان بيــت أهلــي‪.‬‬\n                                                ‫‪ .7‬رفع الصوت بشكل عالي جداً‪.‬‬\n     ‫‪ .8‬إســاءة ســمعتي أمــام عائلتــي وعائــات أصدقائــي حيــث كانــت‬\n     ‫تتســلف منهــم املــال بــدون علمــي علــى أســاس أننــي ال أصــرف علــى‬\n     ‫املنــزل وأن أوالدي جوعــى وكانــت دائم ـ ًا تهــدد بتنفيــذ ذلــك يف حــال‬\n                               ‫رفضــت إعطائهــا املــال (مصروفهــا الشــخصي)‪.‬‬\n     ‫ولكــن حســبي اهلل ونعــم الوكيــل‪ .‬ويف النهايــة ونظــر ًا لألســباب أعــاه‬\n     ‫فقــد هددتهــا بالطــاق إن لــم متتنــع عــن هــذه األفعــال محاولــه منــي‬\n     ‫إلصالحهــا وتقوميهــا ولكنهــا توجــت تصرفاتهــا الســابقة وقامــت بتقــدمي‬\n     ‫شــكوى كيديــه وكاذبــه ضــدي بضربهــا يف شــرطة العليــا بعــد أن‬\n     ‫اســتدرجتني إلــى املنــزل بوجــود نواقــص هامــه لــأوالد (حيــث كنــت‬\n\n\n‫‪67‬‬\n\f‫غضبــان منهــا بســبب اإلهانــات وعصيانهــا لــي وخرجــت مــن املنــزل مــده‬\n‫طويلــه) وهــذا مثبــت برســائل جــوال بينــي وبينهــا وعنــد حضــوري للمنــزل‬\n‫وتأمــن النواقــص املطلوبــة قامــت بافتعــال وخلــق مشــكلة كالعــادة‬\n‫وخرجــت هارب ـ ًا مــن املنــزل لتفــادي املشــاكل وفوجئــت باســتدعاء‬\n‫الشــرطة لــي واتهامــي بضربهــا وهنــا مت طالقــي لهــا الطلقــة الثالثــة‬\n‫بشــهادة شــهود وبحضــور والدهــا وأخيهــا وبعدهــا حتولــت القضيــة‬\n‫إلــى هيئــه التحقيــق واالدعــاء العــام وحفظــت القضيــة ‪ ،‬كمــا أحــب‬\n‫أن أضيــف لفضيلتكــم للعلــم وهــذا مثبــت مبحاضــر الشــرطة بأنهــا‬\n‫بلغــت عنــي الدوريــات والشــرطة قبــل ســنوات بنفــس األســلوب واتهمتنــي‬\n‫بشــكل كيــدي بتواجــد أســلحة يف بيتــي وأنــي أحــاول قتلهــا علــى‬\n‫الرغــم مــن تواجــد أمهــا وأخواتهــا الصغــار يف منزلــي يف هــذا اليــوم‬\n‫ا حضــرت الدوريــات إلــى منزلــي صبــاح يــوم جمعــة ولــم يجــدوا‬       ‫وفع ـ ً‬\n‫شــيئ ًا مــن مــا ذكــر وكتــب تقريــر بذلــك بأنهــا قضيــة عائليــة وتنازلــت‬\n‫يف احملضــر عــن قضيــة كيديــه ضدهــا وهنــا وقعــت طلقتهــا الثانيــة‬\n‫وبعــد اعتذارهــا عمــا حــدث وعلمــي أيض ـ ًا مبرضهــا النفســي ورغبــة‬\n‫منــي يف إصــاح ذات البــن ومــن أجــل احملافظــة علــى بيتــي وأوالدي مت‬\n‫قبــول رجعتهــا علــى الرغــم مــن الفضيحــة التــي ســببتها لــي مــع اجليــران‬\n‫واإلهانــة أمــام عائلتــي‪ .‬الطلبــات‪ :‬أوالً‪ :‬رد دعــوى املدعيــة(‪ ).....‬طلبهــا‬\n‫مؤخــر الصــداق اســتناد ًا لألســباب املذكــورة أعــاه‪ .‬ثاني ـاً‪ :‬توبيــخ‬\n‫املدعيــة وزجرهــا علــى أفعالهــا وعصيانهــا ألوامــر زوجهــا واإلهمــال يف‬\n‫حــق أوالدهــا وحقــوق بيــت الزوجيــة‪ .‬ثالث ـاً‪ :‬أخــذ التعهــد علــى مطلقتــي‬\n‫بعــدم الكــذب وتشــويه ســمعتي واإلســاءة لــي باأللفــاظ واألفعــال‬\n‫واالبتعــاد عــن عائلتــي والكــف عــن نشــر حياتــي الشــخصية واحلميميــة‬\n\n\n                                                                                    ‫‪68‬‬\n\f     ‫عنــد اآلخريــن فمــا زلــت وســأبقي أب أوالدهــا‪ ).‬أ‪.‬ه ـ ‪ .‬هكــذا أجــاب‬\n     ‫وبعرضهــا علــى املدعــى عليهــا قالــت مــا ذكــره املدعــى عليــه إجابتــه‬\n     ‫فغيــر صحيــح جملــة وتفصيــا والصحيــح أنــه كان هنــاك مشــاكل‬\n     ‫بينــي وبينــه ولــم أدفعــه إلــى طالقــي ولكــن الطــاق كان علــى لســانه‬\n     ‫بشــكل دائــم وأنــا علــى مطالبتــي مبؤخــر الصــداق هكــذا أجابــت‬\n     ‫وهــذا وقــد جــرى االطــاع علــى صــك الطــاق الصــادر مــن محكمــة‬\n     ‫األحــوال الشــخصية بالريــاض برقــم ‪ 38/61/5‬يف ‪1434/2/11‬ه ـ‬\n     ‫واملتضمــن طــاق (‪ ).....‬لزوجتــه (‪ ).....‬بعــد الدخــول علــى غيــر عــوض‬\n     ‫وهــي الطلقــة الثالثــة ‪ ،‬كمــا جــرى االطــاع علــى صــورة مــن وثيقــة عقــد‬\n     ‫النــكاح املبــرزة مــن املدعيــة الصــادرة مــن محكمة األحوال الشــخصية‬\n     ‫بالريــاض برقــم ‪ 175‬يف ‪1421/9/16‬ه واملتضمنــة بعقــد املدعــى عليــه‬\n     ‫علــى املدعيــة بصــداق قــدرة أربعــون ألــف ريــال مقدمــة مقبوضــة املؤخــر‬\n     ‫ثالثــون ألــف ريــال ســعودي حلــن فرقــة الطــاق ‪ ،‬الشــروط ال يوجــد‬\n     ‫شــروط بينهمــا وبعرضهــا علــى املدعــى عليــه صــادق علــى مــا ورد فيهــا‬\n     ‫وأنــه لــم يســلم لهــا مــن املؤخــر شــيء ‪ ،‬وهــذا قــد مت عــرض الصلــح علــى‬\n     ‫الطرفــن ورفضــه املدعــى عليــه‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n     ‫واإلجابــة وملصادقــة املدعــى عليــه علــى الطــاق البائــن للمدعيــة وعلــى‬\n     ‫املؤخــر املدعــى بــه ولذلــك كلــه فقــد ألزمــت املدعــى عليــه بــأن يســلم‬\n     ‫للمدعيــة املؤخــر وقــدره ثالثــون ألــف ريــال وبــه حكمــت وبعــد إعــان‬\n     ‫احلكــم لــم يقنــع بــه املدعــى عليــه وطلــب متييــزه وقــرر بأنــه مكتفــي مبــا‬\n     ‫قدمــه بإجابتــه ويطلــب رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة‬\n     ‫اعتراضيــه وأجيــب لطلبــه‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/9/2‬ه ـ ‪.‬‬\n\n\n‫‪69‬‬\n\f‫احلمد هلل وحده وبعد ففي يوم األحد املوافق ‪ 1434/10/25‬هـ افتتحت‬\n‫اجللســة‪ ،‬هــذا و قــد وردتنــا املعاملــة مــن رئيــس محكمــة االســتئناف‬\n‫بكتابــه ذي الرقــم يف ‪1434/9/23‬ه ـ املرفــق بــه القــرار الصــادر مــن‬\n‫دائــرة األحــوال الشــخصية الثانيــة برقــم يف ‪1434/9/17‬ه ـ واملتضمــن‬\n‫املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/10/25‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫برقــم وتاريــخ ‪1434/9/6‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم (‪ ).....‬وتاريــخ‬\n‫‪1434/9/3‬ه ـ اخلــاص بدعــوى (‪ ).....‬اجلنســية حتمــل إقامــة رقــم (‪).....‬‬\n‫ضــد (‪ ).....‬يحمــل الســجل املدنــي رقــم (‪ ).....‬بشــأن مطالبتهــا مبؤخــر‬\n‫الصــداق ‪ .‬وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة تقــرر الدائــرة‬\n‫املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و‬\n                                                    ‫علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪70‬‬\n\f71\n\f72\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":65,"source_page_end":72,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6381aa13f9bb8d65a90a8f46d35b5405b3cfda0fa89ba2762d6509b367593aff","normalized_text_hash":"420159acd01bbfa6183a2646191e074960ed13bdf29fc568dd765f85667e1a6c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p65-34311727"},{"id":"54631f9e-29f1-544b-b662-965cfc35f037","document_type":"judgment","category":"judicial","subcategory":"general","title":"عضل -والية -مطالب أم بإثبات عضل األب لبنته ونقل الوالية إلى األخوة -أنكر املدعى عليه العضل -لم تثبت املدعية ما تدعيه من العضل -ألن األصل براءة الذمة والبينة على املدعي أخلت المحكمة سبيل املدعى عليه -أفهمت المحكمة املدعية أنه متى تقدم الكفء للنكاح ورفضه املدعى عليه فلها التقدم بدعوى العضل.","document_number":"33359281","case_number":"3348517","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/28","year":"1434","subject":"عضل -والية -مطالب أم بإثبات عضل األب لبنته ونقل الوالية إلى األخوة -أنكر املدعى عليه العضل -لم تثبت املدعية ما تدعيه من العضل -ألن األصل براءة الذمة والبينة على املدعي أخلت المحكمة سبيل املدعى عليه -أفهمت المحكمة املدعية أنه متى تقدم الكفء للنكاح ورفضه املدعى عليه فلها التقدم بدعوى العضل.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/7/28 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33359281 :‬‬\n                         ‫َر ْق ُم الدعوى‪3348517 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3417318‬تاريخه‪1434/1/20:‬هـ‬\n\n\n\n     ‫عضــل ‪ -‬واليــة ‪ -‬مطالــب أم بإثبــات عضــل األب لبنتــه ونقــل الواليــة‬\n     ‫إلــى األخــوة ‪ -‬أنكــر املدعــى عليــه العضــل ‪ -‬لــم تثبــت املدعيــة مــا تدعيــه‬\n     ‫مــن العضــل ‪ -‬ألن األصــل بــراءة الذمــة والبينــة علــى املدعــي أخلــت‬\n     ‫احملكمــة ســبيل املدعــى عليــه ‪ -‬أفهمــت احملكمــة املدعيــة أنــه متــى تقــدم‬\n         ‫الكــفء للنــكاح ورفضــه املدعــى عليــه فلهــا التقــدم بدعــوى العضــل‪.‬‬\n\n\n\n\n     ‫‪-1‬قــول الرســول صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن‬\n                                                               ‫علــى مــن أنكــر) ‪.‬‬\n                                                 ‫‪-2‬قاعدة‪ :‬األصل براءة الذمة ‪.‬‬\n\n\n\n\n     ‫ادعــت امــرأة بوكالتهــا عــن ابنتهــا دعــوى علــى والــد ابنتهــا تطالــب‬\n     ‫بإثبــات عضلــه لهــا وفســخ واليتــه عنهــا وعــن بقيــة بناتهــا منــه وجعــل‬\n     ‫الواليــة إلخــوة البنــات وذكــرت أن املدعيــة أصالــة وبقيــة بناتهــا يســكن‬\n     ‫معهــا الن املدعــى عليــه ســيئ العشــرة ‪ -‬أنكــر املدعــى عليــه العضــل‬\n     ‫وادعــى أنــه لــم يتقــدم لبناتــه املدعيــات الكــفء الصالــح وأنــه ال مانــع‬\n     ‫لديــه مــن تزويجهــن إذا تقــدم لهــم الكــفء ‪ -‬حاولــت احملكمــة الصلــح‬\n     ‫بــن الطرفــن فلــم يحصــل ذلــك‪ -‬ســألت احملكمــة املدعيــة البينــة علــى‬\n‫‪73‬‬\n\f‫العضــل فقالــت ال بينــة لهــا فأفهمتهــا احملكمــة بــأن لهــا ميــن املدعــى‬\n‫عليــه ‪ -‬لقولــه عليــه الصــاة والســام (البينــة علــى املدعــى واليمــن علــى‬\n‫مــن أنكــر) فرفضــت ميينــه وألن األصــل بــراءة الذمــة ردت احملكمــة‬\n‫دعــوى املدعيــة وأفهمتهــا بــأن لهــا ميــن املدعــى عليــه متــى طلبتهــا وبعــد‬\n‫مخابــرة مــع محكمــة االســتئناف أفهمــت احملكمــة املدعيــة أنــه متــى‬\n‫مــا تقــدم الكــفء ورفضــه املدعــى عليــه فــإن عليهــا مراجعــة احملكمــة‬\n             ‫للنظــر يف ذلــك ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة وتاريــخ ‪1433/01/18‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 33125089‬وتاريــخ ‪1433/1/18‬ه ـ ففــي هــذا اليــوم الثالثــاء املوافــق‪:‬‬\n‫‪1433/02/02‬ه ـ افتتحــت اجللســة الســاعة العاشــرة وفيهــا حضــرت‬\n‫(‪ ).....‬ســعودية الوكيلــة عــن مبوجــب الوكالــة يف ‪1433/01/29‬ه ـ‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة واملعــرف عليهــا‬\n‫مــن قبــل (‪ ).....‬ســعودي مبوجــب رقــم الســجل املدنــي (‪ ).....‬ولــم يحضــر‬\n‫املدعــى عليــه وقــد وردنــا خطــاب رئيــس قســم محضــري اخلصــوم املــؤرخ‬\n‫يف ‪1433/01/18‬ه ـ ومفــاده بأنــه مت الذهــاب برفقــة احملضــر (‪).....‬‬\n‫ووجــد البــاب مغلــق مــن اخلــارج عــدة مــرات أ‪.‬ه ـ ورفعــت اجللســة إلحضــار‬\n‫إثبــات املدعيــة وكالــة وبعثهــا لقســم الصلــح إلــى يــوم الثالثــاء املوافــق‬\n‫‪1433/03/08‬ه ـ الســاعة العاشــرة والنصــف وأقفلــت اجللســة الســاعة‬\n‫العاشــرة والنصــف وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                                      ‫‪74‬‬\n\f                                                             ‫آلــه وصحبــه أجمعــن‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n     ‫(‪ ).....‬املــازم القضائــي مبكتــب الشــيخ (‪ ).....‬القاضــي يف احملكمــة‬\n     ‫العامــة وبنــاء علــى املعاملــة احملالــة لفضيلتــه مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة برقــم وتاريــخ ‪1433/01/18‬ه املقيــدة باحملكمــة‬\n     ‫وتاريــخ ‪1433/01/18‬ه ففــي يــوم االثنــن املوافــق ‪1433/3/14‬ه ـ‬\n     ‫حضــرت (‪ ).....‬ســعودية مبوجــب الســجل املدنــي رقــم (‪ ).....‬الوكيلــة‬\n     ‫عــن مبوجــب الوكالــة يف ‪1433/01/29‬ه ـ الصــادرة مــن كتابــة العــدل‬\n     ‫الثانيــة باملدينــة املنــورة واملعــرف عليهــا مــن قبــل (‪ ).....‬ســعودي مبوجــب‬\n     ‫الســجل املدنــي رقــم (‪ ).....‬وادعــت علــى احلاضــر معهــا قائلــة إن املدعــى‬\n     ‫عليــه عاضــل لبنتــه البالغــة مــن العمــر ثمانيــة وعشــرين ســنه فقــد تقــدم‬\n     ‫لهــا الكــفء ولــم يزوجهــا أطلــب إثبــات عضلــه ملوكلتــي وفســخ واليتــه‬\n     ‫عنهــا وعــن أبنتــي منــه وجعــل الواليــة إلخــوة البنــات علم ـ ًا أن البنــات‬\n     ‫يســكن عنــدي ألنــه ســيء العشــرة ويضربهــن وهــذا تقريــر ًا طبيـ ًا بذلــك‬\n     ‫عــن بنتــن هكــذا ادعــت وبســؤال املدعــى عليــه أجــاب بأنــه لــم يتقــدم‬\n     ‫لهــن الكــفء الصالــح وإذا تقــدم لهــن الكــفء فــا مانــع لــدي مــن‬\n     ‫تزويجهــن وأنــه تقــدم لهــا رجــل صالــح طيــب ولكنــه طلــب أن يكــون‬\n     ‫الدخــول بعــد ســنة ليهيــأ نفســه فرفضــت ذلــك وقلــت لــك شــهر وإال فــا‬\n     ‫أوافــق ولــم أشــاور البنــت ولــم أعــرف رأيهــا هكــذا أجــاب ومبداولــة‬\n     ‫الصلــح بينهمــا لــم يصطلحــا فرفعــت اجللســة إلحالتهــم القســم الصلــح‬\n     ‫حملاولــة الصلــح بينهمــا ويف جلســة أخــرى لــدي أنــا (‪ ).....‬حضــرت‬\n     ‫املدعيــة وكالــة ولــم يحضــر املدعــى عليــه وقــد وردتنــا افادة رئيس قســم‬\n     ‫الصلــح يف‪1433/4/24‬ه ـ ونــص احلاجــة منهــا اســتعد ولــي أمــر املدعيــة‬\n\n\n‫‪75‬‬\n\f‫بتزويجهــا اذا أتــاه الرجــل الكــفء أ‪.‬ه ـ ثــم ســألت املدعيــة هــل لديهــا‬\n‫بينــة علــى دعواهــا قالــت ال فأفهمتهــا أن لهــا ميــن املدعــى عليــه قالــت‬\n‫ال اطلــب ميينــه ويف جلســة اخــرى حضــرت املدعيــة وكالــة ولــم يحضــر‬\n‫املدعــى عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ولقولــه صلــى‬\n‫أنكــر)) ومبــا‬\n             ‫ن علــى َمــنْ َ‬        ‫((الب ِّي َنـ ُة َع َلــى امل َُّدعِ ــي َ‬\n                               ‫واليمِ ـ ُ‬                                 ‫اهلل عليــه وســلم َ‬\n‫أنــه ال بينــة للمدعيــة وكالــة واألصــل بــراءة املدعــى عليــه ممــا نســب إليه‬\n‫لذلــك فقــد رددت دعــوى املدعيــة وكالــة وأخليــت ســبيل املدعــى عليــه‬\n‫وبــه حكمــت وأفهمــت املدعيــة وكالــة بــأن لهــا ميــن املدعــى عليــه متــى‬\n‫مــا طلبتهــا وبعــرض ذلــك علــى املدعيــة وكالــة لــم تقنــع بــه فأفهمــت‬\n‫مبقتضــى تعليمــات االســتئناف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                     ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫ويف هــذا اليــوم الثالثــاء املوافــق ‪1433/10/17‬ه ـ الســاعة الثانيــة عشــر‬\n‫وردتنــا املعاملــة مــن محكمــة االســتئناف يف ‪1433/09/09‬ه ـ مرفقــا‬\n‫بهــا قــرار الدائــرة األولــى لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال يف ‪1433/9/4‬ه ـ ونــص احلاجــة منــه ((وبدراســة‬\n‫الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة‬\n‫حاكمهــا ملالحظــة مــا يلــي ‪ -1 :‬فضيلتــه قــام بتحويــل طــريف الدعــوى‬\n‫إلــى جلنــة الصلــح قبــل أن يــدون دعــوى املدعيــة علــى وجــه التفصيل بشــأن‬\n‫عضــل املدعــى عليــه البنتــه فلــم يذكــر تاريــخ بــدء العضــل وكــم عــدد‬\n‫الذيــن تقدمــوا خلطبــة ابنتــه مــع ذكــر أســماء اخلاطبــن ممــا يؤيــد دعــوى‬\n‫املدعيــة ‪ -2‬جــاء يف الالئحــة االعتراضيــة مــا يشــير إلــى ســبق عضــل‬\n‫املدعــى عليــه البنتــه (‪ ).....‬وأنهــا لــم تتــزوج إال بعــد إقامــة دعــوى ضــد‬\n‫والدهــا ولــم جنــد فضيلتــه ناقــش ذلــك كمــا جــاء فيهــا أيضــا أن والــد‬\n\n\n                                                                                                 ‫‪76‬‬\n\f     ‫البنــت لــم يخبرهــا باخلاطــب لهــا ولــم جنــد فضيلتــه ناقشــه عــن ســبب‬\n     ‫ذلــك ‪ -3‬كان علــى فضيلتــه لتمحيــص هــذه الدعــوى إحضــار ابنــة‬\n     ‫املدعــى عليــه بحضــور الطرفــن ومناقشــة اجلميــع حيــال هــذه الدعــوى إذ‬\n     ‫أن صــرف النظــر عــن هــذه الدعــوى وإفهــام املدعيــة بــأن لهــا ميــن املدعــى‬\n     ‫عليــه علــى نفــي هــذه الدعــوى واحلــال مــا ذكــر هــو محــل نظــر ))أ‪.‬ه ـ‬\n     ‫قاضــي اســتئناف موافــق علــى املالحظــة الثانيــة ‪ ،‬قاضــي اســتئناف‪،‬‬\n     ‫رئيــس الدائــرة أختامهــم وتواقيعهــم وعليــه أجــاب أصحــاب الفضيلــة‬\n     ‫بأنــه جــرى ســؤال املدعيــة وكالــة عــن بــدء عضلــه موكلتهــا قالــت قبــل‬\n     ‫ســنتني تقريب ـ ًا وتقــدم ثالثــة مــن اخلطــاب وهــم فســألتها هــل تســتطيع‬\n     ‫إحضارهــم قالــت ال ؛ ثــم ســألتها عــن دعــوى ابنتهــا األخــرى علــى والدهــا‬\n     ‫بالعضــل هــل حكــم بهــا قالــت ال وقــد قــال لــه القاضــي إذا لــم تزوجهــا‬\n     ‫فاحملكمــة ســتزوجها وعندمــا حضــر خطيــب وافــق علــى تزويجــه‬\n     ‫بعدمــا ذكــر لــه ابنــه أنــه إذا لــم يزوجهــا فســيتقدم للمحكمــة ‪ ،‬كمــا‬\n     ‫حضــرت املدعيــة أصالــة (‪ ).....‬ســعودية مبوجــب املعــرف عليهــا مــن قبــل‬\n     ‫املعــرف باملدعيــة وكالــة وقالــت بأننــي ال أســتطيع التواصــل مــع والــدي‬\n     ‫ألنــه ال يســتقبلني بــدون ســبب ثــم ســألتها هــل لديهــا بينــة قالــت ســوف‬\n     ‫أحــاول ويف جلســة أخــرى أحضــرت املدعيــة للشــهادة (‪ ).....‬ســعودي‬\n     ‫ا إننــي كنــت إمامـ ًا للمســجد القريــب مــن منــزل (‪ ).....‬وتركتــه يف‬     ‫قائـ ً‬\n     ‫شــهر ربيــع األول املاضــي وقــد طرقــت بــاب منــزل أربــع مــرات األســبوع‬\n     ‫املاضــي ولــم يفتــح البــاب كمــا أنــه لــم يكــن يصلــي معنــا مــع قــرب‬\n     ‫منزلــه للمســجد ويوجــد مســجد ًا أخــر يبعــد عنــه كمــا يبعــد مســجدنا‬\n     ‫وال اعلــم هــل يصلــي بــه أم ال واســمع مــن جماعــة املســجد أنــه دائم ـ ًا‬\n     ‫يف مشــاكل مــع أوالده كمــا شــاهدته األســبوع املاضــي وهــو ميشــي‬\n\n\n‫‪77‬‬\n\f‫مــع زوجتــه بالقــرب مــن املنــزل كمــا أحضــرت للشــهادة (‪ ).....‬وشــهد‬\n‫ا اشــهد إننــي قــد ذهبــت إلــى منــزل (‪ ).....‬وطرقــت البــاب وردت‬        ‫قائ ـ ً‬\n‫زوجتــه فســألتها عــن شــقة ابــن (‪ ).....‬الــذي يســكن معــه فقالــت بالــدور‬\n‫الرابــع وكثيــر مــن جماعتنــا يتجنبونــه لكثــرة مشــاكله مــع أوالده‬\n‫وغيرهــم وال يــزوره مــع كبــر ســنه إال القليــل لهــذا الســبب ثــم ســألت‬\n‫املدعيــة وكالــة عــن ســبب رد اخلاطــب الــذي وصــل لوالــد ابنتهــا قالــت‬\n‫أنــه قــال لــه معــك شــهر إلمتــام الــزواج فقــال ال أســتطيع ألننــي أحتــاج‬\n‫إلــى اســتئجار شــقة وتأثيثهــا وذلــك يحتــاج إلــى وقــت فقــال ليــس لــك‬\n‫إال شــهر‪ ،‬وليــس لــدي بينــة علــى ذلــك‪ ،‬كمــا أجيــب عمــا ذكــر ثاني ـ ًا‬\n‫حــول رد اخلاطــب فقــد ذكــره املدعــى عليــه وهــو أن اخلاطــب طلــب إمتــام‬\n‫الــزواج بعــد ســنة وذلــك ضــرر يعــود تقديــره للولــي وقــد طلــب مــن املتقــدم‬\n‫للخطبــة مــا هــو خــاف العضــل وهــو تعجيــل النــكاح ومبــا أن العضــل‬\n‫منــع الولــي الكــفء مــن زواج موليتــه ولــم يثبــت ذلــك لــدي لــذا فقــد‬\n‫بقيــت علــى مــا حكمــت بــه وأفهمــت املدعيــة وكالــة أنــه متــى مــا تقــدم‬\n‫الكــفء ورفضــه املدعــى عليــه فــإن عليهــا مراجعــة احملكمــة للنظــر يف‬\n‫ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                         ‫أجمعــن‪.‬‬\n‫ويف هــذا اليــوم الســبت املوافــق ‪1434/02/23‬ه ـ افتتحــت اجللســة‬\n‫الســاعة التاســعة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف يف‬\n‫‪1434/01/27‬ه ـ مرفق ـ ًا بهــا قــرار دائــرة األحــوال الشــخصية يف‬\n‫‪1434/01/20‬ه ـ ونــص احلاجــة منــه ((وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم بعد اإلجــراء األخير‬\n‫مــع التنبيــه املرفــق)) أ‪.‬ه ـ قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضــي‬\n\n\n                                                                                       ‫‪78‬‬\n\f     ‫اســتئناف (‪ ).....‬ختمــه وتوقيعــه رئيــس الدائــرة(‪ ).....‬ختمــه وتوقيعــه‬\n     ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلى آلــه وصحبه أجمعني‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n     ‫نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية واألوقــاف والوصايــا‬\n     ‫والقصــار وبيــوت املــال يف محكمــة االســتئناف مبنطقــة مكة املكرمة‬\n     ‫جــرى منــا االطــاع علــى الصــك (‪ ).....‬وتاريــخ ‪1433/7/28‬ه ـ الصــادر‬\n     ‫مــن فضيلــة القاضــي باحملكمــة العامــة باملدينــة املنــورة الشــيخ(‪).....‬‬\n     ‫املتضمــن دعــوى عضــل وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n     ‫االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر مــع‬\n     ‫التنبيــه املرفــق‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪79‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":73,"source_page_end":79,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0fcbd614616967d1f6db4acb0e5f5418efe97fdd7a59d8399a48f554123897f7","normalized_text_hash":"936f3e4504a0d8b08251d24df7471c1d65f4e626275705bd9fe6a1c6665141a3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p73-33359281"},{"id":"62cf15d6-5f6d-591b-a39c-26f853e35802","document_type":"judgment","category":"judicial","subcategory":"general","title":"عضل -والية -رفع والية األب لتغيبه وجلعها لأخ الشقيق - تغيب األب شهادة الشهود العدول -الضرر يزال -رفع","document_number":"34179396","case_number":"3424479","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/6","year":"1434","subject":"عضل -والية -رفع والية األب لتغيبه وجلعها لأخ الشقيق - تغيب األب شهادة الشهود العدول -الضرر يزال -رفع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/6 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34179396 :‬‬\n                    ‫َر ْق ُم الدعوى‪3424479 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34250278‬تاريخه‪1434/6/25 :‬هـ‬\n\n\n\n‫عضــل ‪ -‬واليــة ‪ -‬رفــع واليــة األب لتغيبــه وجلعهــا لــأخ الشــقيق ‪-‬‬\n‫تغيــب األب شــهادة الشــهود العــدول ‪ -‬الضــرر يــزال ‪ -‬رفــع‬\n                                                            ‫البينــة علــى ّ‬\n               ‫احلكــم حملكمــة االســتئناف لتعــذر تبليــغ املدعــى عليــه‪.‬‬\n\n\n\n\n                ‫قول رسول اهلل صلى اهلل عليه وسلم (ال ضرر وال ضرار) ‪.‬‬\n\n\n\n\n‫ادعــت ابنــة تطالــب بإثبــات غيبــة والدهــا ورفــع واليــة تزويجهــا عنــه‬\n‫وجعلهــا لــأخ الشــقيق ‪ ،‬اطلعــت احملكمــة علــى خطابــات صــادرة‬\n‫مــن اجلهــات الرســمية تفيــد بــأن والــد املدعيــة غــادر اململكــة نهائي ـ ًا‬\n‫منــذ اكثــر مــن تســع ســنوات ‪ ،‬ســألت احملكمــة املدعيــة عــن بينتهــا‬\n‫فأحضــرت شــاهدين شــهدا بــأن والــد املدعيــة غــادر اململكــة منــذ‬\n‫أكثــر مــن تســع ســنوات ولــم يــروه بعــد ذلــك وال يعــرف لــه خبــر وأن‬\n‫أقــرب ولــي لهــا أخوهــا الشــقيق‪ ،‬فطلبــت احملكمــة مــن املدعيــة‬\n‫إحضــار أخيهــا الشــقيق فأحضرتــه وقــرر موافقتــه علــى تزويــج املدعيــة‬\n‫ممــن يتقــدم لهــا كمــا جــرى تزكيــة الشــاهدين‪ ،‬بنــاء علــى اإلفــادات‬\n‫الرســمية ولقولــه صلــى اهلل عليــه وســلم (ال ضــرر وال ضــرار) ولشــهادة‬\n‫الشــاهدين املعدلــن شــرع ًا ثبــت لــدى احملكمــة تغيــب والــد املدعيــة‬\n                                                                                    ‫‪80‬‬\n\f     ‫وأن واليتــه علــى ابنتــه قــد ارتفعــت كمــا ثبــت صالحيــة شــقيق املدعيــة‬\n                              ‫للواليــة وإقامتــه وليــا عليهــا‪ ،‬صــدق احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫وتاريــخ ‪1434/01/14‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1434/01/14‬ه ـ‬\n     ‫ففــي يــوم الثالثــاء املوافق‪1434/04/02‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫‪ 15:09‬وفيهــا حضــرت (‪ ).....‬مينيــة اجلنســية باإلقامــة رقــم (‪ ).....‬برفــق‬\n     ‫شــقيقها املعــرف بهــا وأدعــى علــى الغائــب عــن املجلــس الشــرعي املعــرف‬\n     ‫بــه مــن قبلهــا (‪ ).....‬مينــي اجلنســية باإلقامــة رقــم (‪ ).....‬قائلــة يف دعواهــا‬\n     ‫عليــه إن املدعــى عليــه هــو والــدي وقــد هجرنــي وذهــب إلــى اليمــن منــذ‬\n     ‫أكثــر مــن تســع ســنوات وبقيــت مــع والدتــي وقــد تقــدم خلطبتــي أحــد‬\n     ‫االشــخاص وحيــث أن والــدي متغيــب أطلــب أثبــات ذلــك ورفــع واليــة‬\n     ‫تزويجــي عنــه وجعلهــا يف أخــي الشــقيق األكبــر هــذا وباالطــاع‬\n     ‫علــى أوراق املعاملــة ظهــر خطــاب مديــر جــوازات منطقــة برقــم يف‬\n     ‫‪1434/2/9‬ه ـ املتضمــن أن املدعــى عليــه باإلقامــة املذكــورة قــد غــادر‬\n     ‫اململكــة بتأشــيرة خــروج نهائــي وذلــك يف ‪1423/6/21‬ه هــذا وبســؤال‬\n     ‫املدعــي عــن بينتهــا أحضــرت للشــهادة وأدائهــا كل مــن اجلنســية (‪).....‬‬\n     ‫مينــي اجلنســية حيــث قــرر االول قائــا ‪ :‬إننــي خــال املدعيــة كمــا ان‬\n     ‫والدهــا مــن أقاربنــا وأســكن يف مدينــة (‪ ).....‬كمــا قــرر الثانــي قائــا‬\n     ‫‪ :‬إن املدعيــة أبنــة خالتــي كمــا أن والدهــا مــن األقــارب وأســكن يف‬\n     ‫مدينــة (‪ ).....‬ثــم شــهد كل واحــد منهمــا قائــا ‪ :‬أشــهد هلل تعالــى بــأن‬\n\n‫‪81‬‬\n\f‫املدعــى عليــه هــو والــد املدعيــة (‪ ).....‬وقــد غــادر اململكــة إلــى اليمــن‬\n‫منــذ أكثــر مــن تســع ســنوات ولــم أعــد أره بعــد ذلــك ولــم يصلنــي أي‬\n‫خبــر عنــه ولــم يحضــر للمملكــة بعــد ذلــك كمــا أن جــد املدعيــة ألب‬\n‫متــويف منــذ زمــن بعيــد واقــرب ولــي هــو أخوهــا الشــقيق (‪ ).....‬وهــو‬\n‫عــدل صالــح لتزويــج املدعيــة هــذا مــا لــدي مــن شــهاده هــذا وبســؤال‬\n‫املدعيــة عــن أخيهــا املذكــور وعــن املزكــن للشــاهدين قالــت أطلــب‬\n‫امهالــي وعليــه رفعــت اجللســة ويف جلســه اخــرى حضــرت املدعيــة برفــق‬\n‫شــقيقها املذكــور ولــم يحضــر املدعــى عليــه وقــد حضــر شــقيق املدعيــة‬\n‫املدعــو (‪ ).....‬اجلنســية باإلقامــة رقــم (‪ ).....‬حيــث قــرر قائــا ‪ :‬أننــي‬\n‫شــقيق املدعيــة وابلــغ مــن العمــر اثنــن وعشــرين عامـ ًا وأنــا موافــق علــى‬\n‫تزويجهــا ممــن يتقــدم لهــا حيــث ان هنــاك أحــد االشــخاص يريــد التقــدم‬\n‫خلطبتهــا أمــا والــدي فقــد غــادر إلــى اليمــن قبــل حوالــي تســع ســنوات‬\n‫ولــم أره بعــد ذلــك كمــا أنــي ذهبــت إلــى اليمــن للبحــث عنــه ولــم أجــده‬\n‫كمــا أنــي أكبــر أشــقاء أختــي املذكــورة هــذا وبســؤال املدعيــة عــن‬\n‫املزكــن للشــاهدين املذكوريــن أحضــرت كال مــن (‪ ).....‬ســعودي‬\n‫اجلنســية و(‪ ).....‬مينــي اجلنســية باإلقامــة رقــم (‪ ).....‬حيــث شــهدا كل‬\n‫واحــد منهمــا بعدالــة الشــاهدين املذكوريــن فبنــاء علــى الدعــوى والبينــة‬\n‫املعدلــة شــرع ًا وخطــاب اجلــوازات املشــار إليــه أعــاه ولقولــه صلــى اهلل‬\n‫عليــه وســلم «ال ضــرر وال ضــرار» لــذا ثبــت لــدى تغيــب والــد املدعيــة‬\n‫وليهــا الشــرعي يف عقــد النــكاح وان الواليــة بذلــك ارتفعــت عنــه كمــا‬\n‫ثبــت لــدى صالحيــة شــقيق املدعيــة املذكــور للواليــة علــى اختــه املدعيــة‬\n‫فيعقــد النــكاح وأنــه الولــي األقــرب وأقمتــه وليـ ًا علــى شــقيقته املدعيــة‬\n‫(‪ ).....‬يتولــى تزويجهــا بالكــفء وبذلــك حكمــت وأفهمــت املدعيــة بأنــه‬\n\n\n                                                                                     ‫‪82‬‬\n\f     ‫ســيتم ابــاغ املدعــى عليــه بصــوره مــن صــك احلكــم لتقــدمي اعتراضــه‬\n     ‫خــال ثالثــن يومــا مــن اســتالم صــورة صــك احلكــم وأمــرت بتنظيــم‬\n     ‫صــك بذلــك وتســجيله وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/3‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد حيــث وردنــا خطــاب مديــر شــرطة يف‬\n     ‫‪1434/5/8‬ه ـ املتضمــن أنــه مت االستفســار عــن املذكــور مــن احلاســب‬\n     ‫اآللــي طرفنــا واتضــح أنــه غــادر بتأشــيرة خــروج نهائــي وذلــك حســبما‬\n     ‫يتضــح مــن البرنــت وإقــرار املدعيــة املرفــق أ‪.‬ه ـ وعليــه ولتعــذر ابــاغ‬\n     ‫املدعــى عليــه أمــرت برفــع املعاملــة وصــك احلكــم وصــوره ضبطــه‬\n     ‫حملكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/27‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد حيــث عــادت إلينــا املعاملــة بخطــاب فضيلــة رئيس‬\n     ‫محكمــة االســتئناف مبكــة املكرمــة املكلــف رقــم ‪ 34118545‬يف‬\n     ‫‪1434/6/4‬ه ـ املتضمــن أنــه جــرى تدقيــق احلكــم مــن الدائــرة الثانيــة‬\n     ‫وصــدر بحقــه القــرار رقــم ‪ 34250278‬يف ‪1434/6/25‬ه ـ املــدون علــى‬\n     ‫ظهــر الصــك واملتضمــن أنــه باالطــاع علــى الصك وتاريــخ ‪1434/4/6‬هـ‬\n     ‫الصــادر مــن فضيلــة الشــيخ (‪ ).....‬القاضــي باحملكمــة العامــة مبحافظــة‬\n     ‫املتضمــن دعــوى وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى‬\n     ‫احلكــم قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضــي اســتئناف (‪).....‬‬\n     ‫ختمــه وتوقيعــه ورئيــس الدائــرة (‪ ).....‬ختمــه وتوقيعــه ‪.‬وعليــه أمــرت‬\n     ‫بإحلــاق ذلــك يف ضبطــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                               ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/7/11‬ه ـ‬\n     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬فقــد جــرى منــا‬\n\n\n‫‪83‬‬\n\f‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال مبحكمــة االســتئناف االطــاع علــى الصــك‬\n‫الصــادر مــن فضيلــة الشــيخ (‪ ).....‬القاضــي باحملكمــة العامــة وتاريــخ‬\n‫‪1434/4/6‬ه ـ املتضمــن دعــوى‪ ،‬يف دعــوى عضــل‪ ،‬وبدراســة الصــك‬\n‫وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم مــع التنبيــه املرفــق واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪84‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":80,"source_page_end":84,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"56e7092b33ab9126a8fa177c670aba146935f6dc4d88eb3c56d32409c5b7c74c","normalized_text_hash":"762fbee613db95badfd881d7bfeb3a3e0e3740c77c392ab54d22dade08101e4a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p80-34179396"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"d0bf0167-1d8d-5e3c-aee2-019fac6b7a4d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد ذهب أخذه الزوج -انكار الدعوى -عدم وجود البينة من املدعية -البينة على املدعي واليمن على من أنكر -رفض املدعية مين املدعى عليه -احلكم برد دعوى املدعية.","document_number":"33468935","case_number":"32421469","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/29","year":"1434","subject":"مطالبة برد ذهب أخذه الزوج -انكار الدعوى -عدم وجود البينة من املدعية -البينة على املدعي واليمن على من أنكر -رفض املدعية مين املدعى عليه -احلكم برد دعوى املدعية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/11/29 :‬هـ‬\n                 ‫ُ‬                  ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪33468935 :‬‬\n                     ‫َر ْق ُم الدعوى‪32421469 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3434910‬تاريخه‪1434/2/11 :‬هـ‬\n\n\n  ‫مطالبــة بــرد ذهــب أخــذه الــزوج ‪ -‬انــكار الدعــوى ‪ -‬عــدم وجــود البينــة‬\n  ‫مــن املدعيــة ‪ -‬البينــة علــى املدعــي واليمــن علــى مــن أنكــر ‪ -‬رفــض‬\n             ‫املدعيــة ميــن املدعــى عليــه ‪ -‬احلكــم بــرد دعــوى املدعيــة‪.‬‬\n\n\n\n\n  ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( البينــة علــى املدعــي واليمــن علــى‬\n                                                                 ‫مــن أنكــر ) ‪.‬‬\n                          ‫‪ -2‬املادة ( ‪ ) 166‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n  ‫ادعــت املدعيــة بأنهــا كانــت زوجــة للمدعى عليه وقــام بطالقها مبوجب‬\n  ‫صــك الطــاق وقــد أخــذ ذهبهــا وتطلــب احلكــم لهــا بإعطائــه ذهبهــا‬\n  ‫‪،‬بعــرض دعــوى املدعيــة علــى املدعــى عليــه أنكــر مــا جــاء فيهــا وأنــه لــم‬\n  ‫يأخــذ منهــا شــيئ ًا والــذي حصــل أنــه رأى زوجتــه تلبــس الذهــب يف اليــوم‬\n  ‫الســابع مــن زواجهــا وال يــدري أيــن وضعتــه بعــد ذلــك وبعــد رجوعهــم‬\n  ‫مــن الســفر لــم يشــاهد الذهــب ‪ ،‬بطلــب البينــة مــن املدعيــة قالــت ال‬\n  ‫بينــة لهــا ‪ ،‬قــررت املدعيــة أنهــا ال تطلــب ميــن املدعــى عليــه ‪ ،‬بنــاء علــى‬\n  ‫مــا تقــدم مــن الدعــوى واإلجابــة وإلنــكار املدعــى عليــه دعــوى املدعيــة‬\n  ‫‪ ،‬ونظــر ًا لقولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن‬\n\n                                                                                          ‫‪44‬‬\n\f     ‫علــى مــن أنكــر ) وألنــه ال بينــة للمدعيــة علــى دعواهــا ‪ ،‬صــدر احلكــم‬\n     ‫بــرد دعــوى املدعيــة لعــدم ثبوتهــا ‪ ،‬قــرر املدعــى عليــه قناعتــه باحلكــم‬\n     ‫وقــررت املدعيــة اعتراضهــا علــى احلكــم بالئحــة اعتراضيــة فأفهمــت‬\n         ‫بتعليمــات االســتئناف ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n     ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32421469‬وتاريــخ‬\n     ‫‪ 1432/09/21‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321217633‬وتاريــخ‬\n     ‫‪1432/09/21‬ه ـ ففــي يــوم األربعــاء املوافق‪1432/10/30‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 01 : 51‬وفيهــا حضــرت ارتيريــة اجلنســية مبوجــب‬\n     ‫اإلقامــة رقــم وادعــت علــى الغائــب عــن مجلــس احلكــم قائلــه أن املدعــى‬\n     ‫عليــه كان زوجــي وطلقنــي مبوجــب صــك الطــاق رقــم ‪ 2/42/2‬وتاريخ‬\n     ‫‪1431/11/23‬ه ـ وقــد أخــذ ذهبــي وهــو عبــاره عــن طقم حبشــي وخمس‬\n     ‫بناجــر وســت خــوامت وطقــم ذهــب ومغــش ذهــب أطلــب احلكــم عليــه‬\n     ‫بإعطائــي ذهبــي هــذه دعــواي وإلحضــار املدعــى وعليــه تأجلــت اجللســة‬\n     ‫ويف جلســة أخــرى لــدي أنــا القاضــي يف احملكمــة العامــة مبحافظة جدة‬\n     ‫خلــف فضيلــة الشــيخ عليــه ففــي يــوم األحــد املوافق‪1433/11/28‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــرت املدعيــة ‪ .....‬أريتيريــة‬\n     ‫اجلنســية باإلقامــة رقــم‪ ...‬وحضــر حلضورهــا املدعــى عليــه ‪ .....‬اثيوبــي‬\n     ‫اجلنســية باإلقامــة رقــم‪ ...‬وبنــاء علــى املــادة ‪ 166‬مــن نظــام املرافعــات‬\n     ‫الشــرعية جــرى تــاوة مــا مت ضبطــه ســابقا فصادقــت عليــه املدعيــة‬\n‫‪45‬‬\n\f‫وبعــرض مــا جــاء يف الدعــوى علــى املدعــى عليــه قــال مــا ذكرتــه املدعيــة‬\n‫مــن الطــاق فصحيــح وأمــا مــا ذكرتــه مــن الذهــب فليــس بصحيــح وأنــا‬\n‫لــم أخــذ منهــا شــيئا والــذي حصــل أنــي رأيــت زوجتــي يف ســابع يــوم مــن‬\n‫زواجــي تلبــس الذهــب وال أدري أيــن وضعتــه بعــد ذلــك وبعــد رجوعنــا‬\n‫مــن الســفر لــم أشــاهد الذهــب أبــدا هكــذا قــال وبطلــب البينــة مــن‬\n‫املدعيــة قالــت ال بينــة لــدي هكــذا قالــت فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وإلنــكار املدعــى عليــه دعــوى املدعيــة ولقولــه صلــى‬\n‫اهلل عليــه وســلم ‪ ( :‬البينــة علــى املدعــي واليمــن علــى مــن أنكــر )‬\n‫احلديــث وألنــه ال بينــة للمدعيــة علــى دعواهــا فقــد حكمــت بــرد دعــوى‬\n‫املدعيــة لعــدم ثبوتهــا وأفهمتهــا بــأن لهــا ميــن املدعــى عليــه فقالــت ال‬\n‫أطلــب ميينــه هكــذا قالــت وبعرضــه علــى املدعــى عليــه قــرر القناعــة‬\n‫وبعرضــه علــى املدعيــة قــررت عــدم القناعــة وطلبــت االســتئناف فأجيــب‬\n‫إلــى طلبهــا وجــرى تســليمها نســخة مــن احلكــم لالعتــراض عليــه خــال‬\n‫ثالثــن يومــا تبــدأ مــن تاريــخ احلكــم وإذا انتهــت مــدة االعتــراض ولــم‬\n‫تتقــدم بالالئحــة االعتراضيــة فيســقط حقهــا يف طلــب االســتئناف‬\n‫ويكتســب احلكــم القطعيــة وأغلقــت اجللســة الســاعة ‪ 11 : 30‬وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                         ‫يف ‪1433/11/28‬ه ـ ‪.‬‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن قضــا َة‬\n‫االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n‫مــن فضيلــة الشــيخ القاضــي باحملكمــة العامــة بجــدة املســجل بعــدد‬\n‫‪ 33468935‬وتاريــخ ‪1433/11/29‬ه ـ املتضمــن دعــوى ضــد احملكــوم‬\n\n\n                                                                                    ‫‪46‬‬\n\f     ‫في ــه مبا دون باطن الصك ‪ ،‬وبدراســة احلكم وص ــورة ضبط ــه والئحته‬\n     ‫االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم وبــاهلل التوفيــق وصل ــى اهلل‬\n                                   ‫عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪47‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":44,"source_page_end":47,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1b96da165fee162158cc3b3a0798e27128ba06723d98881de5154a9260f8bd64","normalized_text_hash":"14c729254ee4ce7fb09752bf28f3c60d60cd0be2d5ee068dcaba10a9b3e59d7b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p44-33468935"},{"id":"2c246ac4-717b-556b-9752-3681db866fac","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -إعادة املهر مقابل الطاق -قيام والد الزوجة بتسليم زوج ابنته قيمة املهر مقابل الطاق -إقرار املدعى عليه (الزوج) باستالم املهر من والد زوجته هبة -ثبوت وقوع الطاق بدون عوض قبل قبض املهر -مطالبة والد الزوجة إعادة قيمة املهر -مصادقة املدعى عليه على حدوث الطاق بغير عوض -إلزام املدعى عليه بإعادة املبلغ للمدعي .","document_number":"3436764","case_number":"33583387","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/13","year":"1434","subject":"زوجية -إعادة املهر مقابل الطاق -قيام والد الزوجة بتسليم زوج ابنته قيمة املهر مقابل الطاق -إقرار املدعى عليه (الزوج) باستالم املهر من والد زوجته هبة -ثبوت وقوع الطاق بدون عوض قبل قبض املهر -مطالبة والد الزوجة إعادة قيمة املهر -مصادقة املدعى عليه على حدوث الطاق بغير عوض -إلزام املدعى عليه بإعادة املبلغ للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/13 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3436764 :‬‬\n                   ‫َر ْق ُم الدعوى‪33583387 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34202537‬تاريخه‪1434/4/30 :‬هـ‬\n\n\n‫زوجيــة ‪ -‬إعــادة املهــر مقابــل الطــاق‪ -‬قيــام والــد الزوجــة بتســليم‬\n‫زوج ابنتــه قيمــة املهــر مقابــل الطــاق ‪ -‬إقــرار املدعــى عليــه (الــزوج)‬\n‫باســتالم املهــر مــن والــد زوجتــه هبــة ‪ -‬ثبــوت وقــوع الطــاق بــدون عــوض‬\n‫قبــل قبــض املهــر ‪ -‬مطالبــة والــد الزوجــة إعــادة قيمــة املهــر ‪ -‬مصادقــة‬\n‫املدعــى عليــه علــى حــدوث الطــاق بغيــر عــوض ‪ -‬إلــزام املدعــى عليــه‬\n                                                      ‫بإعــادة املبلــغ للمدعــي ‪.‬‬\n\n\n\n\n                       ‫‪ .1‬قاعدة‪ :‬األصل أن على القابض ملال غيره الضمان‬\n                                            ‫‪ .2‬قاعدة‪ :‬األصل عدم الهبة‬\n                           ‫‪ .3‬املادة ‪ 49‬و ‪ 176‬من نظام املرافعات الشرعية‬\n\n\n\n\n‫أقــام وكيــل امــرأة دعــوى يطالــب فيهــا املدعــى عليــه بإعــادة مبلــغ‬\n‫اســتلمه مــن وليهــا مقابــل طالقهــا ألنــه تبــن أن الطــاق أثبــت مبوجــب‬\n‫صــك شــرعي قبــل اســتالم العــوض وذكــر فيــه أنــه بــا مقابــل فــا حــق‬\n‫للمدعــى عليــه باســتالم العــوض ‪ ،‬أقــر املدعــى عليــه مبــا جــاء يف دعــوى‬\n‫املدعــي مــن أنــه اســتلم املبلــغ مــن ولــي مطلقتــه وذكــر أنــه هبــة ‪ ،‬عــدل‬\n‫املدعــي وكالــة دعــواه فجعــل املدعــي ولــي املــرأة ألن املبلــغ صــرف مــن‬\n\n                                                                                      ‫‪48‬‬\n\f     ‫حســابه للمدعــى عليــه ‪ ،‬طلبــت احملكمــة مــن املدعــى عليــه البينــة علــى‬\n     ‫مــا ذكــره مــن الهبــة فقــال ال بينــة لــي فأفهمتــه احملكمــة بــأن لــه ميــن‬\n     ‫املدعــي الــذي ســلمه املبلــغ بأنــه لــم يســلمه لــه هبــة وإمنــا مقابــل طــاق‬\n     ‫ابنتــه وأنــه لــم يعلــم بطالقهــا قبــل تســليم املبلــغ ‪ ،‬فطلــب املدعــى عليــه‬\n     ‫ميــن املدعــي فحلفهــا ألن مــن املقــرر شــرعا أن األصــل عــدم الهبــة وأن‬\n     ‫القابــض ملــال غيــره عليــه الضمــان وألن اليمــن تشــرع يف جانــب أقــوى‬\n     ‫املتداعيــن وحيــث حلــف املدعــي أنــه لــم يســلم املــال للمدعــى عليــه هبــة‬\n     ‫وإمنــا مقابــل الطــاق ‪ ،‬لــذا حكمــت احملكمــة علــى املدعــى عليــه بدفــع‬\n                     ‫املبلــغ للمدعــي ‪ ،‬اعتــرض املدعــى عليــه ‪ ،‬صــدق احلكــم ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة وبنــاء‬\n     ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة برقــم‬\n     ‫وتاريخ ‪1433/9/20‬هـ املقيدة باحملكمة برقم وتاريخ ‪1433/09/20‬هـ‬\n     ‫حضــر ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬بصفتــه وكيال‬\n     ‫عن مبوجب الوكالة الصادرة من كتابة عدل برقم يف ‪1433/9/13‬هـ‬\n     ‫وادعــى علــى احلاضــر معــه ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪ ....‬بصفتــه وكيــا عــن مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n     ‫برقــم ‪ ....‬يف ‪1433/11/2‬ه ـ قائــا يف دعــواه كان املدعــى عليــه أصالــة‬\n     ‫زوجــا ملوكلتــي ثــم طلقهــا بتاريــخ ‪1433/6/10‬ه ـ بقولــه لهــا طالــق ثــم‬\n     ‫طالــق ثــم طالــق بعــد الدخــول دون عــوض قاصــدا إيقــاع ثــاث طلقــات‬\n     ‫وذلــك مبوجــب الصــك الصــادر مــن هــذه احملكمــة يف ‪1433/6/14‬ه ـ‬\n     ‫ولــم يخبــر موكلتــي بهــذا الطــاق حــن إصــدار صكــه وبعــد حصــول‬\n\n‫‪49‬‬\n\f‫الطــاق حضــر املدعــى عليــه وكالــة وهــو والــد املدعــى عليــه أصالــة‬\n‫إلــى والــد موكلتــي وتفــاوض معــه علــى أمــر موكلتــي واملدعــى عليــه‬\n‫أصالــة وانتهــى هــذا التفــاوض علــى أن يقــوم والــد موكلتــي بإرجــاع‬\n‫مهرهــا وقــدره أربعــون ألــف ريــال علــى أن يقــوم املدعــى عليــه بتطليــق‬\n‫موكلتــي بعــد اســتالم مبلــغ املهــر فقــام والــد موكلتــي بتســليم املهــر‬\n‫للمدعــى عليــه أصالــة وقــدره أربعــون ألــف ريــال وذلــك مبوجــب الشــيك‬\n‫رقــم ‪ 117‬يف ‪1433/8/14‬ه ـ علــى مصــرف الراجحــي مــن حســاب والــد‬\n‫موكلتــي ألمــر املدعــى عليــه أصالــة مببلــغ أربعــن ألــف ريــال ‪ 40000‬ثــم‬\n‫ســلم املدعــى عليــه ورقــة مراجعــة حملكمــة الســتالم صــك الطــاق‬\n‫وعنــد اســتالم والــد موكلتــي لصــك الطــاق املذكــور تبــن أن املدعــى‬\n‫عليــه أصالــة طلــق موكلتــي ثــاث طلقــات بــدون عــوض قبــل تفــاوض‬\n‫والــده مــع والــد موكلتــي وقــد خرجــت موكلتــي مــن العــدة ولكــون‬\n‫املدعــى عليــه أصالــة اســترجع املهــر مــع أنــه طلــق قبــل اســترجاع املهــر‬\n‫بــدون عــوض فإنــي أطلــب احلكــم علــى املدعــى عليــه أصالــة بــأن يعيــد‬\n‫إلــى موكلتــي مــا اســتلمه مــن والدهــا وقــدره أربعــون ألــف ريــال وذلــك‬\n‫ألن والــد موكلتــي أعــاد املهــر مــن حســاب موكلتــي نيابــة عنهــا هــذه‬\n‫دعــواي وبســؤال املدعــى عليــه وكالــة عــن دعــوى املدعــي وكالــة أجــاب‬\n‫بقولــه مــا ذكــره املدعــي وكالــة يف دعــواه مــن أن موكلــي طلــق‬\n‫موكلتــه بــدون عــوض باللفــظ املذكــور بعــد الدخــول بهــا وأن موكلــي‬\n‫اســتلم مــن حســاب والــد موكلــة املدعيــة بعــد الطــاق أربعــن ألــف ريــال‬\n‫بالشــيك املذكــور فهــذا صحيــح ولكــن والــد املدعيــة هــو الــذي ســلمني‬\n‫الشــيك املذكــور باملبلــغ املذكــور وذكــر أنــه هبــة البنــي املدعــى عليــه‬\n‫أصالــة فقمــت أنــا بتســليم ابنــي املدعــى عليــه أصالــة الشــيك املذكــور‬\n\n\n                                                                                    ‫‪50‬‬\n\f     ‫فصرفــه موكلــي ولــم نطلــب ال أنــا وال موكلــي إعــادة شــيء مــن مهــر‬\n     ‫موكلــة املدعــي ولــم نفــاوض والدهــا علــى ذلــك هكــذا أجــاب املدعــى‬\n     ‫عليــه وكالــة ونظــرا إلــى أن املهــر ســلم مــن والــد املدعية أصالــة بتصادق‬\n     ‫الطرفــن وهــو غيــر ممثــل يف هــذه الدعــوى فقــد قــررت إدخالــه لســماع‬\n     ‫مــا لديــه ووافــق الطرفــان علــى ذلــك ويف جلســة أخــرى حضــر ســعودي‬\n     ‫بالســجل رقــم وقــرر بقولــه إن املبلــغ املدعــى بــه دفعتــه أنــا مــن حســابي‬\n     ‫اخلــاص للمدعــى عليــه أصالــه وقــدره أربعــون ألــف ريــال وأنــا وبنتي شــيء‬\n     ‫واحــد ولذلــك قدمــت الدعــوى هــي وكل مــا جــاء يف دعــوى املدعــي‬\n     ‫وكالــة صحيــح وأطلــب إدخالــي يف الدعــوى واحلكــم لــي باملبلــغ املدعى‬\n     ‫بــه وإنــي أوكل املدعــي وكالــة يف النيابــة عنــي يف هــذه الدعــوى لــه حــق‬\n     ‫املرافعــة واملدافعــة والصلــح واإلقــرار والقناعــة باألحــكام واالعتــراض‬\n     ‫عليهــا هكــذا قــرر احلاضــر ووافــق الطرفــان علــى إدخالــه ويف جلســة‬\n     ‫أخــرى حضــر املدعــي وكالــة واملدعــى عليــه وكالــة وقــد قــرر املدعــي‬\n     ‫وكالــة بقولــه إن موكلتــي ليــس لهــا دعــوى يف املبلــغ املدعــى بــه ألنــه‬\n     ‫لوالدهــا وإننــي أعــدل الطلــب يف دعــواي وأطلــب احلكــم باملبلــغ املدعــى‬\n     ‫بــه لوالــد موكلتــي املذكــور الــذي وكلنــي باملطالبة يف اجللســة املاضية‬\n     ‫هكــذا قــرر املدعــي وكالــة وقــد ســألت املدعــى عليــه وكالــة عــن‬\n     ‫الشــيك هــل ســلمه والــد املدعيــة بعــد علمــه بالطــاق أو قبلــه فأجــاب إن‬\n     ‫والــد املدعيــة ســلمني الشــيك هبــة باختيــاره بعــد صــدور الطــاق بــدون‬\n     ‫عــوض وبعــد علمــه بــأن الطــاق حصــل بــدون عــوض هكــذا قــرر‬\n     ‫املدعــى عليــه وكالــة وبعرضــه علــى املدعــي وكالــة قــال إن والــد‬\n     ‫موكلتــي ســلم املدعــى عليــه شــيكا بأربعــن ألــف ريــال لصرفــه بأمــره‬\n     ‫هــو ال بأمــر ابنــه املدعــى عليــه أصالــة وذلــك بعــد شــهرين مــن حصــول‬\n\n\n‫‪51‬‬\n\f‫الطــاق وقبــل علمــه بحصــول الطــاق ولــم يســلمه علــى أنــه هبــة وإمنــا‬\n‫علــى أنــه عــوض للطــاق قبــل علمــه بحصولــه فلمــا ســلمه هــذا الشــيك‬\n‫قــام املدعــى عليــه وكالــة بتســليم والــد موكلتــي تذكــرة مراجعــة‬\n‫ملراجعــة احملكمــة الســتالم صــك الطــاق فاتصــل علــي والــد موكلتــي‬\n‫وأخبرنــي بذلــك فقلــت مــا دام أن الطــاق حصــل فإنه ال يســتحق العوض‬\n‫فاســحب الشــيك فقــال إننــي ال أســتطيع ســحبه خشــية حــدوث مشــكلة‬\n‫فقلــت لــه أصــدر شــيكا أخــر بنفــس املبلــغ باســم املدعــى عليــه أصالــة‬\n‫وبأمــره شــخصيا حتــى نســتطيع اســترجاعه بعــد االطــاع علــى صــك‬\n‫الطــاق فقــام والــد موكلتــي بســحب الشــيك األول وإبدالــه بالشــيك‬\n‫محــل الدعــوى ألمــر املدعــى عليــه أصالــة هكــذا قــرر املدعــي وكالــة‬\n‫وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال صحيــح أن والــد املدعيــة‬\n‫ســلمني شــيكني يف وقتــن مختلفــن باملبلــغ املدعــى بــه األول باســمي‬\n‫والثانــي باســم موكلــي وكالهمــا ســلم بعــد علمــه بحصــول الطــاق‬\n‫وقــد ســلمني الشــيك األول الــذي باســمي عصــرا وطلــب منــي أن أذهــب‬\n‫إلــى احملكمــة لتســجيله بصــك الطــاق ثــم حضــر إلــي بعــد العشــاء مــن‬\n‫نفــس اليــوم واســترجع الشــيك األول وســلمني الشــيك الثانــي وقــال إن‬\n‫ذلــك أســهل عنــد الشــيخ حتــى يســجل أنكــم أخــذمت حقكــم فذهبــت‬\n‫إلــى الشــيخ الــذي أصــدر الطــاق فقــال إن الطــاق حصــل بــدون عــوض‬\n‫هكــذا قــرر املدعــى عليــه وكالــة ويف جلســة أخــرى حضــر املدعــي‬\n‫وكالــة واملدعــى عليــه وكالــة وقــد أحضــر الطرفــان ردا مفصــا حلالــة‬\n‫الزوجــن منــذ العقــد وحتــى الفــراق وقــد أرفــق صــورة مــن تفصيــل‬\n‫املدعــي وكالــة واملدعــى عليــه علــى الدعــوى يف املعاملــة وقــد ســألت‬\n‫الطرفــن هــل لديهمــا زيــادة بينــة وإيضــاح علــى مــا تقــدم فأجابــا بالنفــي‬\n\n\n                                                                                     ‫‪52‬‬\n\f     ‫ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه وكالــة وقــد‬\n     ‫قــدم الطرفــان ردودهمــا وأرفقــت باملعاملــة وهــي ردود مطولــة وقــد‬\n     ‫ســألت املدعــى عليــه وكالــة هــل قــام والــد املدعيــة بتســليم الشــيك بعــد‬\n     ‫تســلمه للصــك أم قبلــه فقــال إننــي ســلمت لوالــد املدعيــة تذكــرة‬\n     ‫املراجعــة وأخبرتــه أن الطــاق حصــل مــن دون عــوض وأن صــك الطــاق‬\n     ‫يف احملكمــة فســلمني الشــيك وال أعلــم هــل كان قــد اســتلم الصــك أم‬\n     ‫ال هكــذا قــرر وبعرضــه علــى املدعــي وكالــة قــرر بقولــه إن موكلــي‬\n     ‫ســلم الشــيك قبــل أن يعلــم أن الطــاق بــدون عــوض هكــذا قــرر املدعــي‬\n     ‫وكالــة فســألت املدعــى عليــه وكالــة هــل لديــه بينــة علــى أن والــد‬\n     ‫املدعيــة ســلم الشــيك بعــد علمــه بــأن الطــاق حصــل بــدون عــوض فقــال‬\n     ‫نعــم لــدي بينــة علــى ذلــك وأطلــب املهلــة إلحضارهــا ويف جلســة أخــرى‬\n     ‫حضــر املدعــي وكالــة واملدعــى عليــه وكالــة وقــد قــرر املدعــى عليــه‬\n     ‫وكالــة بقولــه إننــي ال أســتطيع إحضــار الشــاهد الــذي وعــدت بإحضاره‬\n     ‫يف اجللســة الســابقة وال أســتطيع إحضــار زيــادة بينــة علــى أن املبلــغ هبــة‬\n     ‫أو زيــادة بينــة علــى ســائر مــا قدمتــه وقــد قــرر املدعــي وكالــة بقولــه إننــا‬\n     ‫ال نعلــم لنــا بينــة غيــر مــا قدمنــاه وقــد جــرى االطــاع علــى صــورة الشــيك‬\n     ‫التــي قدمهــا املدعــى عليــه وكالــة وذكــر أنهــا صــورة طبــق األصــل‬\n     ‫فوجــد أن رقــم الشــيك وتاريخــه كمــا ذكــر املدعــي وكالــة وقيمتــه‬\n     ‫وقــد ذكـ ــر فيـ ــه أن املبلـ ــغ اســترجاع كـام ــل املهــر كم ــا اطلعــت علــى‬\n     ‫صـ ــك طــاق املذكــور الص ــادر مــن هــذه احملكمــة برق ــم يف‬\n     ‫‪1433/6/14‬ه ـ املتضمــن طــاق ‪ ..........‬لزوجتــه املدخــول بهــا ‪ ..........‬يف‬\n     ‫‪1433/6/10‬ه ـ بلفــظ طالــق ثــم طالــق ثــم طالــق بقصــد إيقــاع ثــاث‬\n     ‫طلقــات بــدون عــوض فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي وكالــة‬\n\n\n‫‪53‬‬\n\f‫املتضمنــة أن املدعــى عليــه أصالــة اســترجع مهــر بنــت موكلــه وقــدره‬\n‫أربعــون ألــف ريــال مــع أنــه طلــق قبــل اســترجاع املهــر بــدون عــوض وطلبــه‬\n‫احلكــم علــى املدعــى عليــه أصالــة بــأن يعيد إلــى والد موكلتــه املتداخل‬\n‫يف هــذه الدعــوى مــا اســتلمه منــه وقــدره أربعــون ألــف ريــال وملصادقــة‬\n‫املدعــى عليــه وكالــة علــى أن موكلــه طلــق بنــت املدعــي أصالــة‬\n‫املتداخــل يف هــذه الدعــوى بــدون عــوض باللفــظ املذكــور بعــد الدخــول‬\n‫بهــا وأن موكلــه اســتلم مــن حســاب والــد البنــت بعــد الطــاق أربعــن‬\n‫ألــف ريــال بالشــيك املذكــور ودفعــه بــأن هــذا املبلــغ ســلم هبــة ملوكلــه‬\n‫دون طلــب أو تفــاوض علــى إعــادة املهــر ونظــرا إلــى أن صــك الطــاق‬\n‫أثبــت أن الطــاق بــدون عــوض علــى الصفــة املذكــورة ونظــرا إلــى أن‬\n‫األصــل يف القابــض ملــال غيــره الضمــان واألصــل عــدم الهبــة خاصــة أنــه‬\n‫ذكــر يف الشــيك أنــه اســترجاع لكامــل املهــر ممــا يقــوي جانــب املدعــي‬\n‫املتداخــل أنــه إمنــا دفــع عوضــا مــن أجــل التطليــق ال هبــة ونظــرا إلــى أنــه‬\n‫تبــن أن الطــاق حصــل بــدون عــوض قبــل دفــع املبلــغ ولــم يحضــر املدعى‬\n‫عليــه وكالــة بينــة علــى أن املبلــغ دفــع بعــد العلــم أن الطــاق حصــل‬\n‫بــدون عــوض واألصــل عــدم العلــم بذلــك وألن اليمــن تشــرع يف حــق مــن‬\n‫ظهــر صدقــه وقــوي جانبــه تقويــة لقولــه واســتظهارا فقــد أفهمــت املدعى‬\n‫عليــه وكالــة بــأن ملوكلــه ميــن املتداخــل أصالــة والــد البنــت بأنــه إمنــا‬\n‫دفــع املبلــغ املذكــور عوضــا للطــاق ال هبــة وأنــه دفعــه قبــل علمــه بــأن‬\n‫الطــاق حصــل بــدون عــوض فقــال املدعــى عليــه وكالــة نطلــب ميينــه‬\n‫علــى ذلــك وبســؤال املدعــي وكالــة عــن اســتعداد موكلــه باليمــن قــال‬\n‫إن لــدى موكلــي بينــة علــى أن املبلــغ دفــع عوضــا للطــاق ال هبــة وأطلــب‬\n‫ســماعها ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليه وكالة‬\n\n\n                                                                                         ‫‪54‬‬\n\f     ‫وقــد حضــر يف هــذه اجللســة املتداخــل أصالــة وقــرر بقولــه إننــي ال‬\n     ‫أســتطيع إحضــار الشــاهد ومســتعد بــأداء اليمــن املطلوبــة وقــرر املدعــى‬\n     ‫عليــه وكالــة طلبــه ميــن املتداخــل املذكــور وبطلــب اليمني مــن املتداخل‬\n     ‫فهــد العامــر حلــف قائــا واهلل العظيــم إننــي إمنــا دفعــت املبلــغ املذكــور‬\n     ‫وقــدره أربعــون ألــف ريــال عوضــا للطــاق ال هبــة وإننــي دفعتــه قبــل‬\n     ‫علمــي بــأن الطــاق حصــل بــدون عــوض هكــذا حلــف فبنــاء علــى مــا‬\n     ‫تقــدم مــن دعــوى املدعــي وألداء اليمــن املطلوبــة فقــد حكمــت علــى‬\n     ‫املدعــى عليــه أصالــة بــأن يعيــد للمتداخــل املبلــغ املذكــور الــذي اســتلمه‬\n     ‫منــه وقــدره أربعــون ألــف ريــال وبعــرض احلكــم علــى املدعــى عليــه‬\n     ‫وكالــة قــرر عــدم القناعــة وطلــب االســتئناف بالئحــة اعتراضيــة فأفهــم‬\n     ‫بــأن صــك احلكــم يصــدر غــدا وأن عليــه احلضــور غــدا الســتالم صــورة‬\n     ‫صــك احلكــم وتقــدمي الالئحــة خــال ثالثــن يومــا مــن تاريــخ يــوم غــد‬\n     ‫فــإن لــم يقــدم الالئحــة خاللهــا ســقط حقــه يف االســتئناف واكتســب‬\n     ‫احلكــم القطعيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                      ‫آله وصحبه وسلم ‪ .‬حرر يف ‪1434/2/12‬هـ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة وبنــاء‬\n     ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة برقــم‬\n     ‫وتاريــخ ‪1433/9/20‬ه ـ املقيــدة باحملكمة برقــم وتاريخ ‪1433/09/20‬‬\n     ‫ه ـ ففــي يــوم اإلثنــن املوافق‪1434/04/22‬ه ـ افتتحــت اجللســة وقــد‬\n     ‫عــادت إلينــا املعاملــة مــن محكمــة االســتئناف بالقصيــم وبرفقهــا‬\n     ‫قــرار محكمــة االســتئناف رقــم يف ‪1434/4/6‬ه ـ املتضمــن مــا نصــه‬\n     ‫بعــد املقدمــة وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫وأوراق املعاملــة لوحــظ اآلتــي أوال أن املدعــى عليــه وكالــة أقــر باســتالم‬\n\n\n‫‪55‬‬\n\f‫موكلــه للمبلــغ املدعــى بــه بالشــيك املذكــور ورضــي بيمــن املتداخــل‬\n‫املدعــي أصالــة ولــم جنــد أن فضيلتــه حتقــق مــن أن املدعــى عليــه وكالــة‬\n‫مخــول لــه يف الوكالــة حــق اإلقــرار وقبــول اليمــن وذلــك وفــق املــادة‬\n‫‪ 49‬مــن نظــام املرافعــات الشــرعية ثانيــا لــم يــدون فضيلتــه يف الضبــط‬\n‫اســتالم املدعــى عليــه وكالــة لنســخة احلكــم لالعتــراض عليــه وأخــذ‬\n‫توقيعــه يف دفتــر الضبــط وهــذا مخالــف ملقتضــى املــادة (‪ )176‬مــن نظــام‬\n‫املرافعــات الشــرعية فعلــى فضيلتــه مالحظــة مــا ذكــر وإحلــاق مــا يجريه‬\n‫بالضبــط والصــك وســجله ثــم إعــادة املعاملــة إلكمــال الزمهــا انتهــى‬\n‫قــرار االســتئناف ويف هــذه اجللســة حضــر املدعــى عليــه وكالــة وحضــر‬\n‫حلضــوره املدعــى عليــه أصالــه ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم وجــرى ســؤال املدعــى عليــه أصالــه هــل خــول موكلــة باإلقــرار‬\n‫وطلــب اليمــن وقبولهــا فأجــاب املدعــى عليــه أصالــه بقولــه إننــي ذهبــت‬\n‫لكاتــب عــدل ووكلــت والــدي بالوكالــة املذكــورة وطلبــت أن أوكلــه‬\n‫يف كل مــا يخــص هــذه القضيــة فأصــدر لــي الوكالــة املذكــورة‬\n‫وبالنســبة لإلقــرار الــذي أقــر بــه موكلــي عنــي فإنــي أنــا الــذي خولــت‬\n‫موكلــي املذكــور باإلقــرار عنــي يف هــذه القضيــة وطلــب اليمــن‬\n‫وقبولهــا والرضــى بهــا وجميــع مــا قالــه موكلــي وأقــر بــه نيابــة عنــي‬\n‫يف اجللســات الســابقة فإنــه صحيــح وقــد مت بعــد الرجــوع إلــي وموافقتــي‬\n‫وقــد أجــزت جميــع مــا قــام بــه نيابــة عنــي يف كل اجللســات الســابقة مــن‬\n‫إقــرار وطلــب ميــن وقبولهــا ورضــا بهــا وغيــر ذلــك هكــذا قــرر املدعــى‬\n‫عليــه أصالــه وعليــه أجيــب أصحــاب الفضيلــة عــن املالحظــة االولــى‬\n‫أن املدعــى عليــه أصالــه قــد أجــاز إقــرار موكلــه عنــه وقبولــه اليمــن‬\n‫عنــه وذكــر أنــه مت بعــد الرجــوع إليــه وموافقتــه وأجيــب عــن املالحظــة‬\n\n\n                                                                                   ‫‪56‬‬\n\f     ‫الثانيــة بــأن املدعــى عليــه وكالــة ســلم نســخة مــن الصــك يف تاريــخ‬\n     ‫‪1434/2/13‬ه ـ وقــدم الالئحــة االعتراضيــة قبــل انتهــاء املــدة ولــم يتــم‬\n     ‫أخــذ توقيعــه علــى الضبــط ســهوا مــن الكاتــب وقــد قــرر املدعــى عليــه‬\n     ‫وكالــة يف هــذه اجللســة بقولــه إننــي اســتلمت صــورة صــك احلكــم يف‬\n     ‫تاريخ‪1434/2/13‬ه ـ هكــذا قــرر هــذا مــا أجيــب بــه أصحــاب الفضيلــة‬\n     ‫ولــم يظهــر لــي خــاف مــا حكمــت بــه وبــاهلل التوفيــق وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/22‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة وبنــاء‬\n     ‫علــى املعاملــة احملالــة لنــا من فضيلة رئيس احملكمة العامة برقم وتاريخ‬\n     ‫‪1433/9/20‬ه املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/09/20‬ه ـ ففــي‬\n     ‫يـ ــوم الســبت املوافــق ‪1434/05/11‬ه ـ افتتحــت اجللســة الســاعة الثانيــة‬\n     ‫عشــر وخمســة عشــرة دقيقــة وقــد عــادت إلينــا املعاملــة مــن محكمــة‬\n     ‫االســتئناف بالقصيــم برقــم يف ‪1434/5/11‬ه ـ وبرفقهــا قــرار محكمــة‬\n     ‫االســتئناف بالقصيــم رقــم يف ‪1434/4/30‬ه ـ املتضمــن املصادقــة علــى‬\n     ‫احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                            ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/11‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا رئيــس احملكمــة والقائــم بعمــل‬\n     ‫املكتــب القضائــي الســادس وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة برقــم وتاريــخ ‪1433/09/20‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/09/20‬ه ـ ففــي يــوم اإلثنــن‬\n     ‫املوافق‪1434/06/12‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة‬\n     ‫ســعودي بالســجل رقــم بصفتــه وكيــا عــن مبوجــب الوكالــة الصــادرة‬\n     ‫مــن كتابــة عــدل برقــم يف ‪1433/9/13‬ه وقــرر بقولــه إننــي اســتلمت‬\n\n\n‫‪57‬‬\n\f‫املبلــغ احملكــوم بــه وقــدره أربعــون ألــف ريــال مبوجــب الشــيك املســحوب‬\n‫علــى مصــرف الراجحــي فــرع الريــان برقــم يف ‪2013/4/10‬م وقــرر أنــه‬\n‫هــذا هــو آخــر املبلــغ املطالــب بــه هكــذا قــرر وعلــى ذلــك جــرت منــي‬\n‫املصادقــة وبذلــك تكــون القضيــة منتهيــة وجــرى إحلاقــه حتــى ال يخفــى‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪1434/6/12‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة عنيــزة برقــم ( ‪ ) ....‬وتاريــخ ‪1434/4/24‬هــ؛ املقيــدة‬\n‫لــدى احملكمــة برقــم ( ‪ ) ....‬وتاريــخ ‪1434/4/28‬هــ؛ اخلاصــة بدعــوى‬\n‫‪ ....‬الوكيــل عــن ‪ ....‬ضــد ‪ ....‬الوكيــل عــن ‪ ....‬؛ بشــأن مطالبتــه بــأن‬\n‫يعيــد املدعــى عليــه أصالــة إلــى موكلتــه املهــر الــذي اســتلمه مــن والدهــا‬\n‫وقــدره أربعــون ألــف ريــال؛ املنتهيــة بالصــك الصــادر مــن فضيلــة الشــيخ‬\n‫‪ ....‬القاضــي باحملكمــة؛ املســجل برقــم ( ‪ ) ....‬وتاريــخ ‪1434/2/13‬ه ـ‬\n‫؛ املتضمــن حكــم فضيلتــه علــى املدعــى عليــه أصالــة بــأن يعيــد املبلــغ‬\n‫املذكــور إلــى والــد املدعيــة أصالــة ؛ علــى النحــو املفصــل فيــه؛ وقــد‬\n‫ســبق منــا دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة‪ .‬وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط والصك‬\n‫ـاء علــى قرارنــا رقــم ( ‪ ) ....‬وتاريــخ ‪1434/4/6‬ه ـ قررنــا املصادقة على‬   ‫بنـ ً‬\n‫مــا حكــم بــه فضيلتــه بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل‬\n                                     ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                      ‫‪58‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":48,"source_page_end":58,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2ca6757cf50f851e32207d4686367bce9d01ed9c763ca16684bdaee6af419a7d","normalized_text_hash":"49124a4073a3244e8fac99409905636faa9ff4fc363788c39fa1729cf1b47c14","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p48-3436764"},{"id":"44b77a53-08f1-543e-81b0-3adba6a7ff33","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -مطالبة زوج إمتام النكاح أو رد املهر والشبكة -صادق املدعى عليه وقرر أن الزوجة رفضت إمتام النكاح لغير سبب ظاهر -قصر الطلبات على رد املهر والشبكة واملبالغ التي سلمها املدعى -ال ضرر وال ضرار -احلكم بإلزام املدعى عليها إرجاع املبالغ املدعى بها - إفهام املدعى بعدم استالم املبلغ إال عند املخالعة.","document_number":"34201385","case_number":"33659139","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/29","year":"1434","subject":"زوجية -مطالبة زوج إمتام النكاح أو رد املهر والشبكة -صادق املدعى عليه وقرر أن الزوجة رفضت إمتام النكاح لغير سبب ظاهر -قصر الطلبات على رد املهر والشبكة واملبالغ التي سلمها املدعى -ال ضرر وال ضرار -احلكم بإلزام املدعى عليها إرجاع املبالغ املدعى بها - إفهام املدعى بعدم استالم املبلغ إال عند املخالعة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/4/29 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34201385 :‬‬\n                        ‫َر ْق ُم الدعوى‪33659139 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34251262‬تاريخه‪1434/6/25 :‬هـ‬\n\n\n     ‫زوجيــة ‪ -‬مطالبــة زوج إمتــام النــكاح أو رد املهــر والشــبكة ‪ -‬صــادق املدعى‬\n     ‫عليــه وقــرر أن الزوجــة رفضــت إمتــام النــكاح لغيــر ســبب ظاهــر‪ -‬قصــر‬\n     ‫الطلبــات علــى رد املهــر والشــبكة واملبالــغ التــي ســلمها املدعــى ‪ -‬ال ضــرر‬\n     ‫وال ضــرار ‪ -‬احلكــم بإلــزام املدعــى عليهــا إرجــاع املبالــغ املدعــى بهــا ‪-‬‬\n                           ‫إفهــام املدعــى بعــدم اســتالم املبلــغ إال عنــد املخالعــة‪.‬‬\n\n\n\n\n                   ‫‪ .1‬قول الرسول صلى اهلل عليه وسلم (ال ضرر وال ضرار)‬\n                                                      ‫‪ .2‬قاعدة الضرر يزال‬\n     ‫‪ .3‬مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة يف‬\n                                                           ‫تســبيب احلكــم ‪.‬‬\n\n\n\n\n     ‫أقــام املدعــي دعــوى يطالــب والــد زوجتــه بإمتــام الــزواج ومتكينــه مــن‬\n     ‫زوجتــه أو إرجــاع املهــر والشــبكة ‪ ،‬اقــر املدعــى عليــه مبــا جــاء يف‬\n     ‫دعــوى املدعــي وقــرر أن ابنتــه هــي التــي رفضــت إمتــام النــكاح فجــرى‬\n     ‫إحضارهــا وســؤالها فقــررت انــه ال رغبــة لهــا يف إمتــام النــكاح مــن غيــر‬\n     ‫ســبب ظاهــر فقــرر املدعــي انــه ال مانــع لديــه مــن مخالعــة املدعــى عليهــا‬\n     ‫مقابــل إعــادة املبالــغ التــي دفعهــا لهــا مــن املهــر والشــبكة كمــا قــررت‬\n\n‫‪59‬‬\n\f‫املــرأة ووليهــا املوافقــة علــى املخالعــة بعــد خصــم قيمــة احلفــل الــذي أقيــم‬\n‫بعــد كتابــة العقــد ‪ ،‬وعظــت احملكمــة املــرأة للرجــوع إلــى زوجهــا إال‬\n‫أنهــا أصــرت علــى مفارقتــه وألن املانــع مــن إمتــام النــكاح كان مــن قبــل‬\n‫املــرأة ونظــر ًا الن الضــرر يــزال ولقــول الرســول صلــى اهلل عليــه وســلم‬\n‫( ال ضــرر وال ضــرار ) وألن مــا يطالــب بــه املدعــى عليــه مــن خصــم‬\n‫قيمــة وليمــة العقــد غيــر وجيــه ألنــه قــام بهــا مــن تلقــاء نفســه ولــم تكــن‬\n‫مشــروطه يف العقــد لــذا حكمــت احملكمــة علــى املدعــى عليــه وابنتــه‬\n‫ا وقيمــة الشــبكة وثبــت لــدى احملكمــة مخالعــة‬           ‫بإعــادة املهــر كام ـ ً‬\n    ‫املدعــى للمدعــى عليهــا ‪ ،‬اعتــرض املدعــى عليــه ‪ ،‬صــدق احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n‫العامــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بخميــس مشــيط برقــم ‪ 33659139‬وتاريــخ‬\n‫‪1433/11/16‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332040183‬وتاريــخ‬\n‫‪1433/11/16‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1434/01/27‬ه ـ افتتحــت‬\n‫اجللســة الســاعة (‪ )9:00‬وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ ).....‬وادعــى علــى احلاضــر معــه (‪ ).....‬ســعودي‬\n‫ا يف دعــواه إنــه يف شــهر شــعبان لعــام ‪1433‬ه ـ قمت بخطبة‬      ‫اجلنســية قائـ ً‬\n‫ابنــة هــذا احلاضــر املســماة (‪ ).....‬وقــد قــام املدعــى عليــه بالترحيــب بــي‬\n‫وقمــت بتســليمه يــوم اخلطبــة مبلغ ـ ًا ثــم بعــد ذلــك ويف تاريــخ كتابــة‬\n‫العقــد الشــرعي ‪1433/9/9‬ه ـ طلــب مهــر ًا وشــبكة ذهــب وبالفعــل‬\n‫قمــت بتســليمه مبلغ ـ ًا مبوجــب شــيك مســحوب علــى مصــرف (‪).....‬‬\n\n                                                                                         ‫‪60‬‬\n\f     ‫برقــم (‪ ).....‬إضافــة إلــى خمســة االف ريــال الســابقة التــي ســلمتها لــه‬\n     ‫يــوم اخلطبــة وشــبكة ذهــب مببلــغ كمــا أننــي قــد ســلمت ابنتــه مبلغ ـ ًا‬\n     ‫بعــد أن طلبــت هــذا املبلــغ لشــراء جــوال ودبلــة يــوم كتابــة العقــد كمــا‬\n     ‫أننــي قــد حولــت لهــا مبلغــا يف تاريــخ ‪1433/9/23‬ه ـ بعــد أن طلبــت ذلــك‬\n     ‫منــي لشــراء أغــراض للعيــد وبعــد ذلــك طلبــت منــه حتديــد موعــد للــزواج‬\n     ‫ولكــن املدعــى عليــه ماطــل بــي بشــكل كبيــر ولــذا فإنــي أطالبــه‬\n     ‫ا أو إرجــاع املبلــغ الــذي ســلمته لــه والبنتــه وإرجــاع‬‫اآلن بتزويجــي عاجـ ً‬\n     ‫الشــبكة هــذه دعــواي وبســؤال املدعــى عليــه عــن ذلــك أجــاب قائــا‬\n     ‫مــا ذكــره املدعــي يف دعــواه مــن خطبتــه البنتــي (‪ ).....‬يف شــهر شــعبان‬\n     ‫واســتالمي منــه مبلغـ ًا مبوجــب الشــيك الــذي ذكــره يــوم كتابــة العقــد‬\n     ‫صحيــح وأيض ـ ًا مــا ذكــره مــن أنــه ســلم شــبكة ذهــب البنتــي صحيــح‬\n     ‫وقــد قمــت أنــا باالتصــال عليــه وطلبــت ذلــك منــه إال أننــي ال أعلــم عــن‬\n     ‫قيمتهــا وأمــا مــا ذكــره مــن أنــه ســلم مبلغ ـ ًا البنتــي بعــد أن طلبــت منــه‬\n     ‫هــذا املبلــغ لشــراء جــوال ودبلــة يــوم كتابــة العقــد وأنــه حــول لهــا مبلغـ ًا‬\n     ‫يف تاريــخ ‪1433/9/23‬ه ـ بعــد أن طلبــت ذلــك منــه لشــراء أغــراض للعيد‬\n     ‫فــا أعلــم عــن ذلــك شــيئا وأمــا مــا ذكــره مــن أنــه طلــب منــي حتديــد‬\n     ‫موعــد الــزواج ولكنــي ماطلــت بــه فــا صحــة لذلــك وأمــا طلبــه اآلن‬\n     ‫تزويجــه فأنــا ال مانــع لــدي إال أن البنــت رفضــت ذلــك ولــم تعــد ترغــب يف‬\n     ‫الــزواج منــه وأنــا مســتعد بتســليمه فقــط نظــر ًا ألننــي قمــت بعمــل حفــل‬\n     ‫يــوم كتابــة العقــد وقــد كلفنــي ذلــك مبلغـ ًا هكذا أجــاب وبعرض ذلك‬\n     ‫علــى املدعــي قــال الصحيــح مــا ذكرتــه وأمــا مــا ذكــره مــن أنــه أقــام‬\n     ‫حفلــة عشــاء يــوم كتابــة العقــد وكلفتــه املبلــغ الــذي ذكــره فلــم أطلــب‬\n     ‫ذلــك منــه وال عالقــة لــي بذلــك أبــد ًا هكــذا أجــاب وبعــرض ذلــك علــى‬\n\n\n‫‪61‬‬\n\f‫املدعــى عليــه قــال مــا ذكــره مــن أنــه لــم يطلــب ذلــك فصحيــح ولكنهــا‬\n‫عــادة معروفــة بــن النــاس هكــذا أجــاب ثــم جــرى ســؤال املدعــى عليــه‬\n‫عــن ابنتــه املذكــورة فقــال لــم أحضرهــا يف هــذا اليــوم فجــرى إفهامــه‬\n‫بضــرورة إحضارهــا يف اجللســة القادمــة فقــال أنــا مســتعد بذلــك وألجــل‬\n‫ذلــك فقــد رفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي واملدعــى عليــه‬\n‫وقــد أحضــر معــه ابنتــه زوجــة املدعــي املســماة (‪ ).....‬ســعودية اجلنســية‬\n‫ســجل مدنــي رقــم (‪ ).....‬بعــد أن جــرى إفهامــه يف اجللســة الســابقة‬\n‫بإحضارهــا وقــد جــرى ســؤال ابنتــه يف هــذه اجللســة عــن رغبتهــا يف إمتــام‬\n‫الــزواج مــن املدعــي مــن عــدم ذلــك فأجابــت قائلــة ليــس لــي أي رغبــة‬\n‫يف الــزواج منــه أبــدا هكــذا أجابــت وبعــرض ذلــك علــى املدعــي قــال‬\n‫إننــي أحصــر مطالبتــي اآلن يف إرجــاع املبلــغ الــذي مت اســتالمه مــن قبــل‬\n‫املدعــى عليــه وابنتــه كمــا أننــي مســتعد مبخالعــة ابنتــه بعــد اســتالمي‬\n‫لهــذا املبلــغ هكــذا قــرر ثــم جــرى ســؤالها عــن اســتالمها يف يــوم كتابــة‬\n‫العقد ملبلغ وعن اســتالمها ملبلغ يف تاريخ ‪1433/9/23‬هـ فأجابت قائلة‬\n‫نعــم لقــد اســتلمت هذيــن املبلغــن املذكوريــن كمــا جــرى ســؤالها عــن‬\n‫اســتالمها لشــبكة الذهــب يف يــوم كتابــة العقــد مــن عدمــه فصادقــت‬\n‫علــى صحــة ذلــك فجــرى ســؤالها هــل تعلمــن قيمتهــا قالــت ال أعلــم عــن‬\n‫قيمتهــا أي شــيء هكــذا أجابــت ثــم جــرى ســؤال املدعــي عــن إثبــات‬\n‫قيمــة شــبكة الذهــب فقــال ليــس لــدي اآلن أي إثبــات لقيمتهــا نظــر ًا‬\n‫لكونــي اشــتريتها مبوجــب فاتــورة ووضعتهــا مــع نفــس شــبكة الذهــب‬\n‫عنــد تســليمي لزوجتــي هــذه احلاضــرة وبعــرض ذلــك عليهــا قالــت نعــم‬\n‫رأيــت الفاتــورة مــع شــبكة الذهــب ولكننــي ال أعلــم عــن قيمتهــا شــيئ ًا‬\n‫لكننــي مســتعدة بإرجــاع قيمتهــا التــي ذكرهــا هكــذا أقــرت ثــم جــرى‬\n\n\n                                                                                    ‫‪62‬‬\n\f     ‫طلــب وثيقــة عقــد النــكاح فأبرزهــا املدعــى عليــه فوجدتهــا صــادرة مــن‬\n     ‫املــأذون الشــرعي (‪ ).....‬بــدون رقــم وبــدون تاريــخ وغيــر مصــادق عليهــا‬\n     ‫مــن قبــل احملكمــة متضمنــة أن قــدر الصــداق أربعــون ألــف ريــال فقــط‬\n     ‫انتهــى وقــد جــرى وعــظ الزوجــة وإفهامهــا بانقيادهــا لبيــت زوجهــا إال‬\n     ‫أنهــا رفضــت ذلــك فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن‬\n     ‫املدعــي قــد طالــب زوجتــه املدعــى عليهــا بانقيادهــا إلــى بيــت الزوجيــة‬\n     ‫أو إرجــاع املبلــغ الــذي ســلمه لهــا ولوالدهــا ومبــا أنهــا رفضــت انقيادهــا‬\n     ‫لبيــت زوجهــا وذكــرت عــدم رغبتهــا فيــه ونظــر ًا ألن املدعــي قــد حصــر‬\n     ‫دعــواه يف مطالبتــه بإرجــاع املبالــغ املســتلمة مــن قبــل زوجتــه ووالدهــا‬\n     ‫ونظــرا ملصادقــة املدعــى عليــه علــى اســتالمه مــن املدعــي ملبلــغ ونظــر ًا‬\n     ‫ملصادقــة زوجــة املدعــي علــى اســتالمها منــه ملبلــغ نقــدي واســتالمها منــه‬\n     ‫شــبكة ذهــب ونظــر ًا الســتعدادها بإرجــاع قيمتهــا ونظــرا ألن املنــع مــن‬\n     ‫إمتــام عقــد الــزواج ليــس مــن قبــل املدعــي وإمنــا مــن قبــل زوجتــه ونظــر ًا‬\n     ‫ألن الضــرر يــزال ونظــر ًا ألن الضــرر يف الشــريعة اإلســامية مدفــوع‬\n     ‫قبــل وقوعــه ومرفــوع بعــد وقوعــه ونظــر ًا لقــول الرســول صلــى اهلل عليــه‬\n     ‫وســلم ( ال ضــرر وال ضــرار) ونظــرا لكــون مــا دفــع بــه املدعــى عليــه‬\n     ‫مــن تســليم املدعــي مبلغـ ًا فقــط مــع إقــراره باســتالمه منــه مبلغـ ًا بحجــة‬\n     ‫أنــه قــد عمــل وليمــة ليلــة كتابــة العقــد غيــر وجيــه وذلــك لكونــه غيــر‬\n     ‫مشــروط عليــه مــن قبــل املدعــي وإمنــا قــام بــه املدعــى عليــه مــن تلقــاء‬\n     ‫نفســه ولهــذا كلــه وملــا تقــدم فقــد قــررت مــا يلــي ‪ :‬أوالً‪ :‬ألزمــت املدعــى‬\n     ‫عليــه املســمى (‪ ).....‬والــد زوجــة املدعــي بإرجــاع املبلــغ الــذي اســتلمه مــن‬\n     ‫املدعــي حــا ًال ثانيـاً‪ :‬ألزمــت املدعــى عليهــا املســماة (‪ ).....‬زوجــة املدعــي‬\n     ‫بإرجــاع املبلــغ النقــدي الــذي اســتلمته مــن املدعــي وإرجــاع قيمــة شــبكة‬\n\n\n‫‪63‬‬\n\f‫الذهــب التــي اســتعدت ســلفا بهــا وبــكل مــا ســبق حكمــت وبعــرض‬\n‫احلكــم علــى املدعــى عليهمــا قــررا معارضتهمــا عليــه واســتعدا بتقــدمي‬\n‫الئحتهمــا االعتراضيــة ويف نفــس اجللســة جــرى تســليمهما صــورة مــن‬\n‫صــك احلكــم لتقــدمي مــا لديهمــا مــن اعتــراض عنــد رغبتهمــا يف ذلــك‬\n‫خــال املــدة احملــددة نظامـ ًا وقدرهــا ثالثــون يومـ ًا ابتــداء مــن تاريــخ هــذا‬\n‫اليــوم وإفهامهمــا بــأن املــدة إذا انتهــت ولــم يتقدمــا باملعارضــة خاللهــا‬\n‫فــإن حقهمــا يف االعتــراض يســقط ويكتســب احلكــم الصفــة القطعيــة‬\n‫ففهمــا ذلــك كمــا جــرى إفهــام املدعــي بأنــه لــن يتــم تســليمه املبلــغ‬\n‫احملكــوم لهبــه إال بعــد قيامــه مبخالعــة زوجتــه فقــال ال مانــع لــدي مــن‬\n‫ذلــك واختتمــت اجللســة عنــد الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/2‬هـ‬\n‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم االثنــن املوافــق ‪1434/08/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة التاســعة وقــد عــادت املعاملــة بخطــاب رئيــس‬\n‫محكمــة االســتئناف مبنطقــة عســير برقــم ‪ 341142868‬وتاريــخ‬\n‫‪1434/07/04‬ه ـ مشــفوع ًا بهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة‬\n‫املختصــة بتدقيــق قضايــا األحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال مبحكمــة االســتئناف بعســير رقــم ‪34251262‬‬\n‫يف ‪1434/06/25‬ه ـ املتضمــن إنــه وبدراســة الصــك وصــورة ضبطــه‬\n‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم باألكثريــة قاضــي‬\n‫اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه‬\n‫رئيــس الدائــرة (‪ ).....‬ختمــه وتوقيعــه ولــذا فقــد جــرى إحلاقــه حتــى ال‬\n‫يخفــى وأمــرت بالتهميــش بذلــك علــى ســجله وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم وحــرر يف ‪1434/08/01‬هـ ‪.‬‬\n\n\n                                                                                         ‫‪64‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":59,"source_page_end":64,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9ee537fe04ba6ad0d58a639fd1c4e2a5aa0bdd4161565b21ab779b1e13e1707f","normalized_text_hash":"26f065f9c82fddd4cb43f9ddf9fb6bc24f797ccbf577653df89ee8620990ec66","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p59-34201385"},{"id":"a39b5fda-2887-52a4-b3c6-70a0da86332b","document_type":"judgment","category":"judicial","subcategory":"general","title":"صداق -مطالبة مطلقة بالصداق املؤخر -عدم السداد والدفع أن الطاق سببه الزوجة -السند الشرعي للحكم (عقد النكاح -صك الطاق ومصادقة املدعى عليه على املؤخر وعدم دفعه) -احلكم بإلزام املدعى عليه بدفع املؤخر .","document_number":"34311727","case_number":"34186643","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/3","year":"1434","subject":"صداق -مطالبة مطلقة بالصداق املؤخر -عدم السداد والدفع أن الطاق سببه الزوجة -السند الشرعي للحكم (عقد النكاح -صك الطاق ومصادقة املدعى عليه على املؤخر وعدم دفعه) -احلكم بإلزام املدعى عليه بدفع املؤخر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/9/3 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34311727 :‬‬\n                        ‫َر ْق ُم الدعوى‪34186643 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34322007‬تاريخه‪1434/9/17 :‬هـ‬\n\n\n     ‫صــداق ‪ -‬مطالبــة مطلقــة بالصــداق املؤخــر ‪ -‬عــدم الســداد والدفــع أن‬\n     ‫الطــاق ســببه الزوجــة ‪ -‬الســند الشــرعي للحكــم (عقــد النكاح ‪ -‬صك‬\n     ‫الطــاق ومصادقــة املدعــى عليــه علــى املؤخــر وعــدم دفعــه) ‪ -‬احلكــم‬\n                                            ‫بإلــزام املدعــى عليــه بدفــع املؤخــر ‪.‬‬\n\n\n\n     ‫مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة يف‬\n                                                                 ‫تســبيب احلكــم‪.‬‬\n\n\n\n\n     ‫ادعــت املدعيــة بدعــوى تطالــب مطلقهــا مبؤخــر صداقهــا ‪ ،‬اقــر املدعــى‬\n     ‫عليــه بالنــكاح والطــاق واملؤخــر وأنــه لــم يســلمه لهــا ورفــض تســليم‬\n     ‫املدعيــة مؤخــر الصــداق وذلــك الن الطــاق كان بســببها وذكــر‬\n     ‫للمحكمــة أســباب ًا دعتــه لطالقهــا وطالــب بــرد دعــوى املدعيــة وتوبيخها‬\n     ‫وأخــذ التعهــد عليهــا بعــدم التعــرض لــه ‪ ،‬أنكــرت املدعيــة مــا قالــه‬\n     ‫املدعــى عليــه واطلعــت احملكمــة علــى عقــد النــكاح ومــا أثبــت فيــه مــن‬\n     ‫مؤخــر وصــك الطــاق املثبــت لطــاق املدعــى عليــه للمدعيــة ‪ ،‬إلقــرار‬\n     ‫الطرفــن بالنــكاح والطــاق واملؤخــر لــذا حكمــت احملكمــة علــى‬\n     ‫املدعــى عليــه بدفــع املؤخــر للمدعيــة ‪ ،‬اعتــرض املدعــى عليــه ‪ ،‬صــدق‬\n                                                                            ‫احلكــم ‪.‬‬\n‫‪65‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض وتاريــخ ‪1434/04/23‬ه ـ املقيــدة باحملكمــة وتاريــخ‬\n‫‪1434/04/23‬ه ـ ففــي يــوم األربعــاء املوافــق ‪1434/09/02‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــرت (‪ ).....‬ســورية اجلنســية مســلمة الديانــة حتمــل‬\n‫اإلقامــة رقــم (‪ ).....‬املعــرف بهــا مــن قبــل أخيهــا (‪ ).....‬ســوري اجلنســية‬\n‫مســلم الديانــة يحمــل رخصــة اإلقامــة رقــم (‪ ).....‬وادعــت ضــد احلاضــر‬\n‫معهــا باملجلــس (‪ ).....‬حامــل بطاقــة هويــة رقــم (‪ ).....‬قائلــة يف دعواهــا إن‬\n‫هــذا احلاضــر كان زوجــي تزوجنــي ودخــل بــي علــى مهــر قــدره أربعــون‬\n‫ألــف ريــال مقــدم واملؤخــر قــدره ثالثــون ألــف ريــال وقــد طلقنــي بتاريــخ‬\n‫‪1434/2/11‬ه ـ وأنــا أطلــب احلكــم عليــه بتســليمي مؤخــر صداقــي‬\n‫وقــدره ثالثــون ألــف ريــال هــذه دعــواي وبعرضهــا علــى املدعــى عليــه قــال‬\n‫مــا ذكرتــه املدعيــة فهــو صحيــح ولكــن ال أوافــق علــى تســليمها املؤخــر‬\n                             ‫ألنهــا مــن دفعنــي لطالقهــا لألســباب التاليــة ‪:‬‬\n‫‪ .1‬إهمــال األوالد وعــدم االهتمــام بتربيتهــم وإســناد أمــور إطعامهــم‬\n‫والعنايــة بهــم وتوصيلهــم إلــى املــدارس إلــى عامــات املنــزل مــع علمهــا‬\n‫برفضــي التــام لذلــك ومنعــي لهــا مــن تكــرار هــذا الفعــل وشــرح خطــورة‬\n                   ‫االعتمــاد والثقــة بعامــات املنــزل ولكــن دون جــدوى‪.‬‬\n‫‪ .2‬اخلــروج إلــى األســواق واملطاعــم بــدون علمــي أو أذنــي والعــودة الــى‬\n‫املنــزل بأوقــات متأخــرة مــن الليــل وذلــك أثنــاء ســفري أو عنــد املبيــت‬\n‫لــدى الزوجــة الثانيــة مــع العلــم مبنعــي لهــا مــرار ًا وتكــرار ًا ويوجــد‬\n\n                                                                                      ‫‪66‬‬\n\f     ‫رســائل جــوال تؤكــد ذلــك وتفيــد عصيانهــا لــي حيــث قامــت أيض ـ ًا‬\n     ‫بقطــع نظــام التتبــع للســيارة بنفســها إلخفــاء أماكــن تواجدهــا وأوقــات‬\n              ‫عودتهــا مــع الســائق ‪ .‬ويشــهد الســائق املســلم مكفولــي بذلــك‬\n     ‫‪ .3‬تعليــم األوالد الكــذب‪ ،‬حيــث تخــرج مــن املنــزل وإيــداع األوالد‬\n     ‫الصغــار عنــد أهلهــا ومــن ثــم اخلــروج إلــى منــزل صديقتهــا (‪ ).....‬التــي‬\n     ‫منعتهــا مــن االتصــال بهــا مــرارا ( مفصــا يف الضبــط ) وجتبــر األوالد‬\n                          ‫الكــذب العمــد وتكــراره الدائــم علــى أنــا والدهــم‪.‬‬\n     ‫‪ .4‬تعليــم األوالد أســلوب احللــف الكــذب علــى القــرآن كتــاب اهلل‬\n                                                                         ‫العظيــم ‪....‬‬\n     ‫‪ .5‬تعليــم األوالد اخلــداع حيــث كان تلبــس نقابهــا أمامــي وتخلعــه عنــد‬\n                                  ‫اخلــروج بدونــي وهــذا عصيــان هلل ثــم ألوامــري‪.‬‬\n     ‫‪ .6‬إرســال البنــات للمبيــت يف بيــت أهلهــا وعصيانهــا ألوامــري بعــدم‬\n                 ‫مبيــت األوالد يف بيــت أي أحــد حتــى ولــو كان بيــت أهلــي‪.‬‬\n                                                ‫‪ .7‬رفع الصوت بشكل عالي جداً‪.‬‬\n     ‫‪ .8‬إســاءة ســمعتي أمــام عائلتــي وعائــات أصدقائــي حيــث كانــت‬\n     ‫تتســلف منهــم املــال بــدون علمــي علــى أســاس أننــي ال أصــرف علــى‬\n     ‫املنــزل وأن أوالدي جوعــى وكانــت دائم ـ ًا تهــدد بتنفيــذ ذلــك يف حــال‬\n                               ‫رفضــت إعطائهــا املــال (مصروفهــا الشــخصي)‪.‬‬\n     ‫ولكــن حســبي اهلل ونعــم الوكيــل‪ .‬ويف النهايــة ونظــر ًا لألســباب أعــاه‬\n     ‫فقــد هددتهــا بالطــاق إن لــم متتنــع عــن هــذه األفعــال محاولــه منــي‬\n     ‫إلصالحهــا وتقوميهــا ولكنهــا توجــت تصرفاتهــا الســابقة وقامــت بتقــدمي‬\n     ‫شــكوى كيديــه وكاذبــه ضــدي بضربهــا يف شــرطة العليــا بعــد أن‬\n     ‫اســتدرجتني إلــى املنــزل بوجــود نواقــص هامــه لــأوالد (حيــث كنــت‬\n\n\n‫‪67‬‬\n\f‫غضبــان منهــا بســبب اإلهانــات وعصيانهــا لــي وخرجــت مــن املنــزل مــده‬\n‫طويلــه) وهــذا مثبــت برســائل جــوال بينــي وبينهــا وعنــد حضــوري للمنــزل‬\n‫وتأمــن النواقــص املطلوبــة قامــت بافتعــال وخلــق مشــكلة كالعــادة‬\n‫وخرجــت هارب ـ ًا مــن املنــزل لتفــادي املشــاكل وفوجئــت باســتدعاء‬\n‫الشــرطة لــي واتهامــي بضربهــا وهنــا مت طالقــي لهــا الطلقــة الثالثــة‬\n‫بشــهادة شــهود وبحضــور والدهــا وأخيهــا وبعدهــا حتولــت القضيــة‬\n‫إلــى هيئــه التحقيــق واالدعــاء العــام وحفظــت القضيــة ‪ ،‬كمــا أحــب‬\n‫أن أضيــف لفضيلتكــم للعلــم وهــذا مثبــت مبحاضــر الشــرطة بأنهــا‬\n‫بلغــت عنــي الدوريــات والشــرطة قبــل ســنوات بنفــس األســلوب واتهمتنــي‬\n‫بشــكل كيــدي بتواجــد أســلحة يف بيتــي وأنــي أحــاول قتلهــا علــى‬\n‫الرغــم مــن تواجــد أمهــا وأخواتهــا الصغــار يف منزلــي يف هــذا اليــوم‬\n‫ا حضــرت الدوريــات إلــى منزلــي صبــاح يــوم جمعــة ولــم يجــدوا‬       ‫وفع ـ ً‬\n‫شــيئ ًا مــن مــا ذكــر وكتــب تقريــر بذلــك بأنهــا قضيــة عائليــة وتنازلــت‬\n‫يف احملضــر عــن قضيــة كيديــه ضدهــا وهنــا وقعــت طلقتهــا الثانيــة‬\n‫وبعــد اعتذارهــا عمــا حــدث وعلمــي أيض ـ ًا مبرضهــا النفســي ورغبــة‬\n‫منــي يف إصــاح ذات البــن ومــن أجــل احملافظــة علــى بيتــي وأوالدي مت‬\n‫قبــول رجعتهــا علــى الرغــم مــن الفضيحــة التــي ســببتها لــي مــع اجليــران‬\n‫واإلهانــة أمــام عائلتــي‪ .‬الطلبــات‪ :‬أوالً‪ :‬رد دعــوى املدعيــة(‪ ).....‬طلبهــا‬\n‫مؤخــر الصــداق اســتناد ًا لألســباب املذكــورة أعــاه‪ .‬ثاني ـاً‪ :‬توبيــخ‬\n‫املدعيــة وزجرهــا علــى أفعالهــا وعصيانهــا ألوامــر زوجهــا واإلهمــال يف‬\n‫حــق أوالدهــا وحقــوق بيــت الزوجيــة‪ .‬ثالث ـاً‪ :‬أخــذ التعهــد علــى مطلقتــي‬\n‫بعــدم الكــذب وتشــويه ســمعتي واإلســاءة لــي باأللفــاظ واألفعــال‬\n‫واالبتعــاد عــن عائلتــي والكــف عــن نشــر حياتــي الشــخصية واحلميميــة‬\n\n\n                                                                                    ‫‪68‬‬\n\f     ‫عنــد اآلخريــن فمــا زلــت وســأبقي أب أوالدهــا‪ ).‬أ‪.‬ه ـ ‪ .‬هكــذا أجــاب‬\n     ‫وبعرضهــا علــى املدعــى عليهــا قالــت مــا ذكــره املدعــى عليــه إجابتــه‬\n     ‫فغيــر صحيــح جملــة وتفصيــا والصحيــح أنــه كان هنــاك مشــاكل‬\n     ‫بينــي وبينــه ولــم أدفعــه إلــى طالقــي ولكــن الطــاق كان علــى لســانه‬\n     ‫بشــكل دائــم وأنــا علــى مطالبتــي مبؤخــر الصــداق هكــذا أجابــت‬\n     ‫وهــذا وقــد جــرى االطــاع علــى صــك الطــاق الصــادر مــن محكمــة‬\n     ‫األحــوال الشــخصية بالريــاض برقــم ‪ 38/61/5‬يف ‪1434/2/11‬ه ـ‬\n     ‫واملتضمــن طــاق (‪ ).....‬لزوجتــه (‪ ).....‬بعــد الدخــول علــى غيــر عــوض‬\n     ‫وهــي الطلقــة الثالثــة ‪ ،‬كمــا جــرى االطــاع علــى صــورة مــن وثيقــة عقــد‬\n     ‫النــكاح املبــرزة مــن املدعيــة الصــادرة مــن محكمة األحوال الشــخصية‬\n     ‫بالريــاض برقــم ‪ 175‬يف ‪1421/9/16‬ه واملتضمنــة بعقــد املدعــى عليــه‬\n     ‫علــى املدعيــة بصــداق قــدرة أربعــون ألــف ريــال مقدمــة مقبوضــة املؤخــر‬\n     ‫ثالثــون ألــف ريــال ســعودي حلــن فرقــة الطــاق ‪ ،‬الشــروط ال يوجــد‬\n     ‫شــروط بينهمــا وبعرضهــا علــى املدعــى عليــه صــادق علــى مــا ورد فيهــا‬\n     ‫وأنــه لــم يســلم لهــا مــن املؤخــر شــيء ‪ ،‬وهــذا قــد مت عــرض الصلــح علــى‬\n     ‫الطرفــن ورفضــه املدعــى عليــه‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n     ‫واإلجابــة وملصادقــة املدعــى عليــه علــى الطــاق البائــن للمدعيــة وعلــى‬\n     ‫املؤخــر املدعــى بــه ولذلــك كلــه فقــد ألزمــت املدعــى عليــه بــأن يســلم‬\n     ‫للمدعيــة املؤخــر وقــدره ثالثــون ألــف ريــال وبــه حكمــت وبعــد إعــان‬\n     ‫احلكــم لــم يقنــع بــه املدعــى عليــه وطلــب متييــزه وقــرر بأنــه مكتفــي مبــا‬\n     ‫قدمــه بإجابتــه ويطلــب رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة‬\n     ‫اعتراضيــه وأجيــب لطلبــه‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/9/2‬ه ـ ‪.‬‬\n\n\n‫‪69‬‬\n\f‫احلمد هلل وحده وبعد ففي يوم األحد املوافق ‪ 1434/10/25‬هـ افتتحت‬\n‫اجللســة‪ ،‬هــذا و قــد وردتنــا املعاملــة مــن رئيــس محكمــة االســتئناف‬\n‫بكتابــه ذي الرقــم يف ‪1434/9/23‬ه ـ املرفــق بــه القــرار الصــادر مــن‬\n‫دائــرة األحــوال الشــخصية الثانيــة برقــم يف ‪1434/9/17‬ه ـ واملتضمــن‬\n‫املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/10/25‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫برقــم وتاريــخ ‪1434/9/6‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم (‪ ).....‬وتاريــخ‬\n‫‪1434/9/3‬ه ـ اخلــاص بدعــوى (‪ ).....‬اجلنســية حتمــل إقامــة رقــم (‪).....‬‬\n‫ضــد (‪ ).....‬يحمــل الســجل املدنــي رقــم (‪ ).....‬بشــأن مطالبتهــا مبؤخــر‬\n‫الصــداق ‪ .‬وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة تقــرر الدائــرة‬\n‫املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و‬\n                                                    ‫علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪70‬‬\n\f71\n\f72\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":65,"source_page_end":72,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6381aa13f9bb8d65a90a8f46d35b5405b3cfda0fa89ba2762d6509b367593aff","normalized_text_hash":"420159acd01bbfa6183a2646191e074960ed13bdf29fc568dd765f85667e1a6c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p65-34311727"},{"id":"54631f9e-29f1-544b-b662-965cfc35f037","document_type":"judgment","category":"judicial","subcategory":"general","title":"عضل -والية -مطالب أم بإثبات عضل األب لبنته ونقل الوالية إلى األخوة -أنكر املدعى عليه العضل -لم تثبت املدعية ما تدعيه من العضل -ألن األصل براءة الذمة والبينة على املدعي أخلت المحكمة سبيل املدعى عليه -أفهمت المحكمة املدعية أنه متى تقدم الكفء للنكاح ورفضه املدعى عليه فلها التقدم بدعوى العضل.","document_number":"33359281","case_number":"3348517","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/28","year":"1434","subject":"عضل -والية -مطالب أم بإثبات عضل األب لبنته ونقل الوالية إلى األخوة -أنكر املدعى عليه العضل -لم تثبت املدعية ما تدعيه من العضل -ألن األصل براءة الذمة والبينة على املدعي أخلت المحكمة سبيل املدعى عليه -أفهمت المحكمة املدعية أنه متى تقدم الكفء للنكاح ورفضه املدعى عليه فلها التقدم بدعوى العضل.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/7/28 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33359281 :‬‬\n                         ‫َر ْق ُم الدعوى‪3348517 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3417318‬تاريخه‪1434/1/20:‬هـ‬\n\n\n\n     ‫عضــل ‪ -‬واليــة ‪ -‬مطالــب أم بإثبــات عضــل األب لبنتــه ونقــل الواليــة‬\n     ‫إلــى األخــوة ‪ -‬أنكــر املدعــى عليــه العضــل ‪ -‬لــم تثبــت املدعيــة مــا تدعيــه‬\n     ‫مــن العضــل ‪ -‬ألن األصــل بــراءة الذمــة والبينــة علــى املدعــي أخلــت‬\n     ‫احملكمــة ســبيل املدعــى عليــه ‪ -‬أفهمــت احملكمــة املدعيــة أنــه متــى تقــدم‬\n         ‫الكــفء للنــكاح ورفضــه املدعــى عليــه فلهــا التقــدم بدعــوى العضــل‪.‬‬\n\n\n\n\n     ‫‪-1‬قــول الرســول صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن‬\n                                                               ‫علــى مــن أنكــر) ‪.‬‬\n                                                 ‫‪-2‬قاعدة‪ :‬األصل براءة الذمة ‪.‬‬\n\n\n\n\n     ‫ادعــت امــرأة بوكالتهــا عــن ابنتهــا دعــوى علــى والــد ابنتهــا تطالــب‬\n     ‫بإثبــات عضلــه لهــا وفســخ واليتــه عنهــا وعــن بقيــة بناتهــا منــه وجعــل‬\n     ‫الواليــة إلخــوة البنــات وذكــرت أن املدعيــة أصالــة وبقيــة بناتهــا يســكن‬\n     ‫معهــا الن املدعــى عليــه ســيئ العشــرة ‪ -‬أنكــر املدعــى عليــه العضــل‬\n     ‫وادعــى أنــه لــم يتقــدم لبناتــه املدعيــات الكــفء الصالــح وأنــه ال مانــع‬\n     ‫لديــه مــن تزويجهــن إذا تقــدم لهــم الكــفء ‪ -‬حاولــت احملكمــة الصلــح‬\n     ‫بــن الطرفــن فلــم يحصــل ذلــك‪ -‬ســألت احملكمــة املدعيــة البينــة علــى‬\n‫‪73‬‬\n\f‫العضــل فقالــت ال بينــة لهــا فأفهمتهــا احملكمــة بــأن لهــا ميــن املدعــى‬\n‫عليــه ‪ -‬لقولــه عليــه الصــاة والســام (البينــة علــى املدعــى واليمــن علــى‬\n‫مــن أنكــر) فرفضــت ميينــه وألن األصــل بــراءة الذمــة ردت احملكمــة‬\n‫دعــوى املدعيــة وأفهمتهــا بــأن لهــا ميــن املدعــى عليــه متــى طلبتهــا وبعــد‬\n‫مخابــرة مــع محكمــة االســتئناف أفهمــت احملكمــة املدعيــة أنــه متــى‬\n‫مــا تقــدم الكــفء ورفضــه املدعــى عليــه فــإن عليهــا مراجعــة احملكمــة‬\n             ‫للنظــر يف ذلــك ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة وتاريــخ ‪1433/01/18‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 33125089‬وتاريــخ ‪1433/1/18‬ه ـ ففــي هــذا اليــوم الثالثــاء املوافــق‪:‬‬\n‫‪1433/02/02‬ه ـ افتتحــت اجللســة الســاعة العاشــرة وفيهــا حضــرت‬\n‫(‪ ).....‬ســعودية الوكيلــة عــن مبوجــب الوكالــة يف ‪1433/01/29‬ه ـ‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة باملدينــة املنــورة واملعــرف عليهــا‬\n‫مــن قبــل (‪ ).....‬ســعودي مبوجــب رقــم الســجل املدنــي (‪ ).....‬ولــم يحضــر‬\n‫املدعــى عليــه وقــد وردنــا خطــاب رئيــس قســم محضــري اخلصــوم املــؤرخ‬\n‫يف ‪1433/01/18‬ه ـ ومفــاده بأنــه مت الذهــاب برفقــة احملضــر (‪).....‬‬\n‫ووجــد البــاب مغلــق مــن اخلــارج عــدة مــرات أ‪.‬ه ـ ورفعــت اجللســة إلحضــار‬\n‫إثبــات املدعيــة وكالــة وبعثهــا لقســم الصلــح إلــى يــوم الثالثــاء املوافــق‬\n‫‪1433/03/08‬ه ـ الســاعة العاشــرة والنصــف وأقفلــت اجللســة الســاعة‬\n‫العاشــرة والنصــف وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                                      ‫‪74‬‬\n\f                                                             ‫آلــه وصحبــه أجمعــن‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n     ‫(‪ ).....‬املــازم القضائــي مبكتــب الشــيخ (‪ ).....‬القاضــي يف احملكمــة‬\n     ‫العامــة وبنــاء علــى املعاملــة احملالــة لفضيلتــه مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة برقــم وتاريــخ ‪1433/01/18‬ه املقيــدة باحملكمــة‬\n     ‫وتاريــخ ‪1433/01/18‬ه ففــي يــوم االثنــن املوافــق ‪1433/3/14‬ه ـ‬\n     ‫حضــرت (‪ ).....‬ســعودية مبوجــب الســجل املدنــي رقــم (‪ ).....‬الوكيلــة‬\n     ‫عــن مبوجــب الوكالــة يف ‪1433/01/29‬ه ـ الصــادرة مــن كتابــة العــدل‬\n     ‫الثانيــة باملدينــة املنــورة واملعــرف عليهــا مــن قبــل (‪ ).....‬ســعودي مبوجــب‬\n     ‫الســجل املدنــي رقــم (‪ ).....‬وادعــت علــى احلاضــر معهــا قائلــة إن املدعــى‬\n     ‫عليــه عاضــل لبنتــه البالغــة مــن العمــر ثمانيــة وعشــرين ســنه فقــد تقــدم‬\n     ‫لهــا الكــفء ولــم يزوجهــا أطلــب إثبــات عضلــه ملوكلتــي وفســخ واليتــه‬\n     ‫عنهــا وعــن أبنتــي منــه وجعــل الواليــة إلخــوة البنــات علم ـ ًا أن البنــات‬\n     ‫يســكن عنــدي ألنــه ســيء العشــرة ويضربهــن وهــذا تقريــر ًا طبيـ ًا بذلــك‬\n     ‫عــن بنتــن هكــذا ادعــت وبســؤال املدعــى عليــه أجــاب بأنــه لــم يتقــدم‬\n     ‫لهــن الكــفء الصالــح وإذا تقــدم لهــن الكــفء فــا مانــع لــدي مــن‬\n     ‫تزويجهــن وأنــه تقــدم لهــا رجــل صالــح طيــب ولكنــه طلــب أن يكــون‬\n     ‫الدخــول بعــد ســنة ليهيــأ نفســه فرفضــت ذلــك وقلــت لــك شــهر وإال فــا‬\n     ‫أوافــق ولــم أشــاور البنــت ولــم أعــرف رأيهــا هكــذا أجــاب ومبداولــة‬\n     ‫الصلــح بينهمــا لــم يصطلحــا فرفعــت اجللســة إلحالتهــم القســم الصلــح‬\n     ‫حملاولــة الصلــح بينهمــا ويف جلســة أخــرى لــدي أنــا (‪ ).....‬حضــرت‬\n     ‫املدعيــة وكالــة ولــم يحضــر املدعــى عليــه وقــد وردتنــا افادة رئيس قســم‬\n     ‫الصلــح يف‪1433/4/24‬ه ـ ونــص احلاجــة منهــا اســتعد ولــي أمــر املدعيــة‬\n\n\n‫‪75‬‬\n\f‫بتزويجهــا اذا أتــاه الرجــل الكــفء أ‪.‬ه ـ ثــم ســألت املدعيــة هــل لديهــا‬\n‫بينــة علــى دعواهــا قالــت ال فأفهمتهــا أن لهــا ميــن املدعــى عليــه قالــت‬\n‫ال اطلــب ميينــه ويف جلســة اخــرى حضــرت املدعيــة وكالــة ولــم يحضــر‬\n‫املدعــى عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ولقولــه صلــى‬\n‫أنكــر)) ومبــا‬\n             ‫ن علــى َمــنْ َ‬        ‫((الب ِّي َنـ ُة َع َلــى امل َُّدعِ ــي َ‬\n                               ‫واليمِ ـ ُ‬                                 ‫اهلل عليــه وســلم َ‬\n‫أنــه ال بينــة للمدعيــة وكالــة واألصــل بــراءة املدعــى عليــه ممــا نســب إليه‬\n‫لذلــك فقــد رددت دعــوى املدعيــة وكالــة وأخليــت ســبيل املدعــى عليــه‬\n‫وبــه حكمــت وأفهمــت املدعيــة وكالــة بــأن لهــا ميــن املدعــى عليــه متــى‬\n‫مــا طلبتهــا وبعــرض ذلــك علــى املدعيــة وكالــة لــم تقنــع بــه فأفهمــت‬\n‫مبقتضــى تعليمــات االســتئناف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                     ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫ويف هــذا اليــوم الثالثــاء املوافــق ‪1433/10/17‬ه ـ الســاعة الثانيــة عشــر‬\n‫وردتنــا املعاملــة مــن محكمــة االســتئناف يف ‪1433/09/09‬ه ـ مرفقــا‬\n‫بهــا قــرار الدائــرة األولــى لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال يف ‪1433/9/4‬ه ـ ونــص احلاجــة منــه ((وبدراســة‬\n‫الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة‬\n‫حاكمهــا ملالحظــة مــا يلــي ‪ -1 :‬فضيلتــه قــام بتحويــل طــريف الدعــوى‬\n‫إلــى جلنــة الصلــح قبــل أن يــدون دعــوى املدعيــة علــى وجــه التفصيل بشــأن‬\n‫عضــل املدعــى عليــه البنتــه فلــم يذكــر تاريــخ بــدء العضــل وكــم عــدد‬\n‫الذيــن تقدمــوا خلطبــة ابنتــه مــع ذكــر أســماء اخلاطبــن ممــا يؤيــد دعــوى‬\n‫املدعيــة ‪ -2‬جــاء يف الالئحــة االعتراضيــة مــا يشــير إلــى ســبق عضــل‬\n‫املدعــى عليــه البنتــه (‪ ).....‬وأنهــا لــم تتــزوج إال بعــد إقامــة دعــوى ضــد‬\n‫والدهــا ولــم جنــد فضيلتــه ناقــش ذلــك كمــا جــاء فيهــا أيضــا أن والــد‬\n\n\n                                                                                                 ‫‪76‬‬\n\f     ‫البنــت لــم يخبرهــا باخلاطــب لهــا ولــم جنــد فضيلتــه ناقشــه عــن ســبب‬\n     ‫ذلــك ‪ -3‬كان علــى فضيلتــه لتمحيــص هــذه الدعــوى إحضــار ابنــة‬\n     ‫املدعــى عليــه بحضــور الطرفــن ومناقشــة اجلميــع حيــال هــذه الدعــوى إذ‬\n     ‫أن صــرف النظــر عــن هــذه الدعــوى وإفهــام املدعيــة بــأن لهــا ميــن املدعــى‬\n     ‫عليــه علــى نفــي هــذه الدعــوى واحلــال مــا ذكــر هــو محــل نظــر ))أ‪.‬ه ـ‬\n     ‫قاضــي اســتئناف موافــق علــى املالحظــة الثانيــة ‪ ،‬قاضــي اســتئناف‪،‬‬\n     ‫رئيــس الدائــرة أختامهــم وتواقيعهــم وعليــه أجــاب أصحــاب الفضيلــة‬\n     ‫بأنــه جــرى ســؤال املدعيــة وكالــة عــن بــدء عضلــه موكلتهــا قالــت قبــل‬\n     ‫ســنتني تقريب ـ ًا وتقــدم ثالثــة مــن اخلطــاب وهــم فســألتها هــل تســتطيع‬\n     ‫إحضارهــم قالــت ال ؛ ثــم ســألتها عــن دعــوى ابنتهــا األخــرى علــى والدهــا‬\n     ‫بالعضــل هــل حكــم بهــا قالــت ال وقــد قــال لــه القاضــي إذا لــم تزوجهــا‬\n     ‫فاحملكمــة ســتزوجها وعندمــا حضــر خطيــب وافــق علــى تزويجــه‬\n     ‫بعدمــا ذكــر لــه ابنــه أنــه إذا لــم يزوجهــا فســيتقدم للمحكمــة ‪ ،‬كمــا‬\n     ‫حضــرت املدعيــة أصالــة (‪ ).....‬ســعودية مبوجــب املعــرف عليهــا مــن قبــل‬\n     ‫املعــرف باملدعيــة وكالــة وقالــت بأننــي ال أســتطيع التواصــل مــع والــدي‬\n     ‫ألنــه ال يســتقبلني بــدون ســبب ثــم ســألتها هــل لديهــا بينــة قالــت ســوف‬\n     ‫أحــاول ويف جلســة أخــرى أحضــرت املدعيــة للشــهادة (‪ ).....‬ســعودي‬\n     ‫ا إننــي كنــت إمامـ ًا للمســجد القريــب مــن منــزل (‪ ).....‬وتركتــه يف‬     ‫قائـ ً‬\n     ‫شــهر ربيــع األول املاضــي وقــد طرقــت بــاب منــزل أربــع مــرات األســبوع‬\n     ‫املاضــي ولــم يفتــح البــاب كمــا أنــه لــم يكــن يصلــي معنــا مــع قــرب‬\n     ‫منزلــه للمســجد ويوجــد مســجد ًا أخــر يبعــد عنــه كمــا يبعــد مســجدنا‬\n     ‫وال اعلــم هــل يصلــي بــه أم ال واســمع مــن جماعــة املســجد أنــه دائم ـ ًا‬\n     ‫يف مشــاكل مــع أوالده كمــا شــاهدته األســبوع املاضــي وهــو ميشــي‬\n\n\n‫‪77‬‬\n\f‫مــع زوجتــه بالقــرب مــن املنــزل كمــا أحضــرت للشــهادة (‪ ).....‬وشــهد‬\n‫ا اشــهد إننــي قــد ذهبــت إلــى منــزل (‪ ).....‬وطرقــت البــاب وردت‬        ‫قائ ـ ً‬\n‫زوجتــه فســألتها عــن شــقة ابــن (‪ ).....‬الــذي يســكن معــه فقالــت بالــدور‬\n‫الرابــع وكثيــر مــن جماعتنــا يتجنبونــه لكثــرة مشــاكله مــع أوالده‬\n‫وغيرهــم وال يــزوره مــع كبــر ســنه إال القليــل لهــذا الســبب ثــم ســألت‬\n‫املدعيــة وكالــة عــن ســبب رد اخلاطــب الــذي وصــل لوالــد ابنتهــا قالــت‬\n‫أنــه قــال لــه معــك شــهر إلمتــام الــزواج فقــال ال أســتطيع ألننــي أحتــاج‬\n‫إلــى اســتئجار شــقة وتأثيثهــا وذلــك يحتــاج إلــى وقــت فقــال ليــس لــك‬\n‫إال شــهر‪ ،‬وليــس لــدي بينــة علــى ذلــك‪ ،‬كمــا أجيــب عمــا ذكــر ثاني ـ ًا‬\n‫حــول رد اخلاطــب فقــد ذكــره املدعــى عليــه وهــو أن اخلاطــب طلــب إمتــام‬\n‫الــزواج بعــد ســنة وذلــك ضــرر يعــود تقديــره للولــي وقــد طلــب مــن املتقــدم‬\n‫للخطبــة مــا هــو خــاف العضــل وهــو تعجيــل النــكاح ومبــا أن العضــل‬\n‫منــع الولــي الكــفء مــن زواج موليتــه ولــم يثبــت ذلــك لــدي لــذا فقــد‬\n‫بقيــت علــى مــا حكمــت بــه وأفهمــت املدعيــة وكالــة أنــه متــى مــا تقــدم‬\n‫الكــفء ورفضــه املدعــى عليــه فــإن عليهــا مراجعــة احملكمــة للنظــر يف‬\n‫ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                         ‫أجمعــن‪.‬‬\n‫ويف هــذا اليــوم الســبت املوافــق ‪1434/02/23‬ه ـ افتتحــت اجللســة‬\n‫الســاعة التاســعة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف يف‬\n‫‪1434/01/27‬ه ـ مرفق ـ ًا بهــا قــرار دائــرة األحــوال الشــخصية يف‬\n‫‪1434/01/20‬ه ـ ونــص احلاجــة منــه ((وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم بعد اإلجــراء األخير‬\n‫مــع التنبيــه املرفــق)) أ‪.‬ه ـ قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضــي‬\n\n\n                                                                                       ‫‪78‬‬\n\f     ‫اســتئناف (‪ ).....‬ختمــه وتوقيعــه رئيــس الدائــرة(‪ ).....‬ختمــه وتوقيعــه‬\n     ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلى آلــه وصحبه أجمعني‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n     ‫نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية واألوقــاف والوصايــا‬\n     ‫والقصــار وبيــوت املــال يف محكمــة االســتئناف مبنطقــة مكة املكرمة‬\n     ‫جــرى منــا االطــاع علــى الصــك (‪ ).....‬وتاريــخ ‪1433/7/28‬ه ـ الصــادر‬\n     ‫مــن فضيلــة القاضــي باحملكمــة العامــة باملدينــة املنــورة الشــيخ(‪).....‬‬\n     ‫املتضمــن دعــوى عضــل وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n     ‫االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر مــع‬\n     ‫التنبيــه املرفــق‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪79‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":73,"source_page_end":79,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0fcbd614616967d1f6db4acb0e5f5418efe97fdd7a59d8399a48f554123897f7","normalized_text_hash":"936f3e4504a0d8b08251d24df7471c1d65f4e626275705bd9fe6a1c6665141a3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p73-33359281"},{"id":"62cf15d6-5f6d-591b-a39c-26f853e35802","document_type":"judgment","category":"judicial","subcategory":"general","title":"عضل -والية -رفع والية األب لتغيبه وجلعها لأخ الشقيق - تغيب األب شهادة الشهود العدول -الضرر يزال -رفع","document_number":"34179396","case_number":"3424479","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/6","year":"1434","subject":"عضل -والية -رفع والية األب لتغيبه وجلعها لأخ الشقيق - تغيب األب شهادة الشهود العدول -الضرر يزال -رفع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/6 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34179396 :‬‬\n                    ‫َر ْق ُم الدعوى‪3424479 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34250278‬تاريخه‪1434/6/25 :‬هـ‬\n\n\n\n‫عضــل ‪ -‬واليــة ‪ -‬رفــع واليــة األب لتغيبــه وجلعهــا لــأخ الشــقيق ‪-‬‬\n‫تغيــب األب شــهادة الشــهود العــدول ‪ -‬الضــرر يــزال ‪ -‬رفــع‬\n                                                            ‫البينــة علــى ّ‬\n               ‫احلكــم حملكمــة االســتئناف لتعــذر تبليــغ املدعــى عليــه‪.‬‬\n\n\n\n\n                ‫قول رسول اهلل صلى اهلل عليه وسلم (ال ضرر وال ضرار) ‪.‬‬\n\n\n\n\n‫ادعــت ابنــة تطالــب بإثبــات غيبــة والدهــا ورفــع واليــة تزويجهــا عنــه‬\n‫وجعلهــا لــأخ الشــقيق ‪ ،‬اطلعــت احملكمــة علــى خطابــات صــادرة‬\n‫مــن اجلهــات الرســمية تفيــد بــأن والــد املدعيــة غــادر اململكــة نهائي ـ ًا‬\n‫منــذ اكثــر مــن تســع ســنوات ‪ ،‬ســألت احملكمــة املدعيــة عــن بينتهــا‬\n‫فأحضــرت شــاهدين شــهدا بــأن والــد املدعيــة غــادر اململكــة منــذ‬\n‫أكثــر مــن تســع ســنوات ولــم يــروه بعــد ذلــك وال يعــرف لــه خبــر وأن‬\n‫أقــرب ولــي لهــا أخوهــا الشــقيق‪ ،‬فطلبــت احملكمــة مــن املدعيــة‬\n‫إحضــار أخيهــا الشــقيق فأحضرتــه وقــرر موافقتــه علــى تزويــج املدعيــة‬\n‫ممــن يتقــدم لهــا كمــا جــرى تزكيــة الشــاهدين‪ ،‬بنــاء علــى اإلفــادات‬\n‫الرســمية ولقولــه صلــى اهلل عليــه وســلم (ال ضــرر وال ضــرار) ولشــهادة‬\n‫الشــاهدين املعدلــن شــرع ًا ثبــت لــدى احملكمــة تغيــب والــد املدعيــة‬\n                                                                                    ‫‪80‬‬\n\f     ‫وأن واليتــه علــى ابنتــه قــد ارتفعــت كمــا ثبــت صالحيــة شــقيق املدعيــة‬\n                              ‫للواليــة وإقامتــه وليــا عليهــا‪ ،‬صــدق احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫وتاريــخ ‪1434/01/14‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1434/01/14‬ه ـ‬\n     ‫ففــي يــوم الثالثــاء املوافق‪1434/04/02‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫‪ 15:09‬وفيهــا حضــرت (‪ ).....‬مينيــة اجلنســية باإلقامــة رقــم (‪ ).....‬برفــق‬\n     ‫شــقيقها املعــرف بهــا وأدعــى علــى الغائــب عــن املجلــس الشــرعي املعــرف‬\n     ‫بــه مــن قبلهــا (‪ ).....‬مينــي اجلنســية باإلقامــة رقــم (‪ ).....‬قائلــة يف دعواهــا‬\n     ‫عليــه إن املدعــى عليــه هــو والــدي وقــد هجرنــي وذهــب إلــى اليمــن منــذ‬\n     ‫أكثــر مــن تســع ســنوات وبقيــت مــع والدتــي وقــد تقــدم خلطبتــي أحــد‬\n     ‫االشــخاص وحيــث أن والــدي متغيــب أطلــب أثبــات ذلــك ورفــع واليــة‬\n     ‫تزويجــي عنــه وجعلهــا يف أخــي الشــقيق األكبــر هــذا وباالطــاع‬\n     ‫علــى أوراق املعاملــة ظهــر خطــاب مديــر جــوازات منطقــة برقــم يف‬\n     ‫‪1434/2/9‬ه ـ املتضمــن أن املدعــى عليــه باإلقامــة املذكــورة قــد غــادر‬\n     ‫اململكــة بتأشــيرة خــروج نهائــي وذلــك يف ‪1423/6/21‬ه هــذا وبســؤال‬\n     ‫املدعــي عــن بينتهــا أحضــرت للشــهادة وأدائهــا كل مــن اجلنســية (‪).....‬‬\n     ‫مينــي اجلنســية حيــث قــرر االول قائــا ‪ :‬إننــي خــال املدعيــة كمــا ان‬\n     ‫والدهــا مــن أقاربنــا وأســكن يف مدينــة (‪ ).....‬كمــا قــرر الثانــي قائــا‬\n     ‫‪ :‬إن املدعيــة أبنــة خالتــي كمــا أن والدهــا مــن األقــارب وأســكن يف‬\n     ‫مدينــة (‪ ).....‬ثــم شــهد كل واحــد منهمــا قائــا ‪ :‬أشــهد هلل تعالــى بــأن‬\n\n‫‪81‬‬\n\f‫املدعــى عليــه هــو والــد املدعيــة (‪ ).....‬وقــد غــادر اململكــة إلــى اليمــن‬\n‫منــذ أكثــر مــن تســع ســنوات ولــم أعــد أره بعــد ذلــك ولــم يصلنــي أي‬\n‫خبــر عنــه ولــم يحضــر للمملكــة بعــد ذلــك كمــا أن جــد املدعيــة ألب‬\n‫متــويف منــذ زمــن بعيــد واقــرب ولــي هــو أخوهــا الشــقيق (‪ ).....‬وهــو‬\n‫عــدل صالــح لتزويــج املدعيــة هــذا مــا لــدي مــن شــهاده هــذا وبســؤال‬\n‫املدعيــة عــن أخيهــا املذكــور وعــن املزكــن للشــاهدين قالــت أطلــب‬\n‫امهالــي وعليــه رفعــت اجللســة ويف جلســه اخــرى حضــرت املدعيــة برفــق‬\n‫شــقيقها املذكــور ولــم يحضــر املدعــى عليــه وقــد حضــر شــقيق املدعيــة‬\n‫املدعــو (‪ ).....‬اجلنســية باإلقامــة رقــم (‪ ).....‬حيــث قــرر قائــا ‪ :‬أننــي‬\n‫شــقيق املدعيــة وابلــغ مــن العمــر اثنــن وعشــرين عامـ ًا وأنــا موافــق علــى‬\n‫تزويجهــا ممــن يتقــدم لهــا حيــث ان هنــاك أحــد االشــخاص يريــد التقــدم‬\n‫خلطبتهــا أمــا والــدي فقــد غــادر إلــى اليمــن قبــل حوالــي تســع ســنوات‬\n‫ولــم أره بعــد ذلــك كمــا أنــي ذهبــت إلــى اليمــن للبحــث عنــه ولــم أجــده‬\n‫كمــا أنــي أكبــر أشــقاء أختــي املذكــورة هــذا وبســؤال املدعيــة عــن‬\n‫املزكــن للشــاهدين املذكوريــن أحضــرت كال مــن (‪ ).....‬ســعودي‬\n‫اجلنســية و(‪ ).....‬مينــي اجلنســية باإلقامــة رقــم (‪ ).....‬حيــث شــهدا كل‬\n‫واحــد منهمــا بعدالــة الشــاهدين املذكوريــن فبنــاء علــى الدعــوى والبينــة‬\n‫املعدلــة شــرع ًا وخطــاب اجلــوازات املشــار إليــه أعــاه ولقولــه صلــى اهلل‬\n‫عليــه وســلم «ال ضــرر وال ضــرار» لــذا ثبــت لــدى تغيــب والــد املدعيــة‬\n‫وليهــا الشــرعي يف عقــد النــكاح وان الواليــة بذلــك ارتفعــت عنــه كمــا‬\n‫ثبــت لــدى صالحيــة شــقيق املدعيــة املذكــور للواليــة علــى اختــه املدعيــة‬\n‫فيعقــد النــكاح وأنــه الولــي األقــرب وأقمتــه وليـ ًا علــى شــقيقته املدعيــة‬\n‫(‪ ).....‬يتولــى تزويجهــا بالكــفء وبذلــك حكمــت وأفهمــت املدعيــة بأنــه‬\n\n\n                                                                                     ‫‪82‬‬\n\f     ‫ســيتم ابــاغ املدعــى عليــه بصــوره مــن صــك احلكــم لتقــدمي اعتراضــه‬\n     ‫خــال ثالثــن يومــا مــن اســتالم صــورة صــك احلكــم وأمــرت بتنظيــم‬\n     ‫صــك بذلــك وتســجيله وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/3‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد حيــث وردنــا خطــاب مديــر شــرطة يف‬\n     ‫‪1434/5/8‬ه ـ املتضمــن أنــه مت االستفســار عــن املذكــور مــن احلاســب‬\n     ‫اآللــي طرفنــا واتضــح أنــه غــادر بتأشــيرة خــروج نهائــي وذلــك حســبما‬\n     ‫يتضــح مــن البرنــت وإقــرار املدعيــة املرفــق أ‪.‬ه ـ وعليــه ولتعــذر ابــاغ‬\n     ‫املدعــى عليــه أمــرت برفــع املعاملــة وصــك احلكــم وصــوره ضبطــه‬\n     ‫حملكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/27‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد حيــث عــادت إلينــا املعاملــة بخطــاب فضيلــة رئيس‬\n     ‫محكمــة االســتئناف مبكــة املكرمــة املكلــف رقــم ‪ 34118545‬يف‬\n     ‫‪1434/6/4‬ه ـ املتضمــن أنــه جــرى تدقيــق احلكــم مــن الدائــرة الثانيــة‬\n     ‫وصــدر بحقــه القــرار رقــم ‪ 34250278‬يف ‪1434/6/25‬ه ـ املــدون علــى‬\n     ‫ظهــر الصــك واملتضمــن أنــه باالطــاع علــى الصك وتاريــخ ‪1434/4/6‬هـ‬\n     ‫الصــادر مــن فضيلــة الشــيخ (‪ ).....‬القاضــي باحملكمــة العامــة مبحافظــة‬\n     ‫املتضمــن دعــوى وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى‬\n     ‫احلكــم قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضــي اســتئناف (‪).....‬‬\n     ‫ختمــه وتوقيعــه ورئيــس الدائــرة (‪ ).....‬ختمــه وتوقيعــه ‪.‬وعليــه أمــرت‬\n     ‫بإحلــاق ذلــك يف ضبطــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                               ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/7/11‬ه ـ‬\n     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬فقــد جــرى منــا‬\n\n\n‫‪83‬‬\n\f‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال مبحكمــة االســتئناف االطــاع علــى الصــك‬\n‫الصــادر مــن فضيلــة الشــيخ (‪ ).....‬القاضــي باحملكمــة العامــة وتاريــخ‬\n‫‪1434/4/6‬ه ـ املتضمــن دعــوى‪ ،‬يف دعــوى عضــل‪ ،‬وبدراســة الصــك‬\n‫وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم مــع التنبيــه املرفــق واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪84‬‬\n\f","legal_